 for patch in select value from jsonb_array_elements($patches$[{"record":{"id":"waiter-internship","kind":"course","title":"90-е · Стандарты и стажировка официанта","course_id":null,"published":true,"department":null,"updated_at":"2026-11-17T15:01:20.91309+00:00","restaurant_id":null,"payload":{"id":"waiter-internship","kind":"internship","pass":80,"brand":"90","title":"90-е · Стандарты и стажировка официанта","outline":[{"type":"lesson","id":"122794","title":"Критерии оценки официанта: на что смотрят наставники и менеджеры 📋"},{"type":"lesson","id":"114183","title":"Смена 1. Погружение в атмосферу"},{"id":"100075","type":"test"},{"type":"lesson","id":"114185","title":"Смена 2. Врываемся в движ"},{"id":"100153","type":"test"},{"type":"lesson","id":"114188","title":"Смена 3. Первый выход в зал — наблюдаем и учимся у наставника 🎭"},{"id":"100159","type":"test"},{"type":"lesson","id":"114189","title":"Смена 4. Теперь ты в теме"},{"id":"100172","type":"test"},{"type":"lesson","id":"114190","title":"Смена 5. Совместный трек с кухней"},{"id":"104138","type":"test"},{"type":"lesson","id":"114191","title":"Смена 6. Включай iiko"},{"id":"104142","type":"test"},{"type":"lesson","id":"114192","title":"Смена 7. Практика в действии"},{"id":"104144","type":"test"},{"id":"104760","type":"test"},{"id":"104939","type":"test"},{"type":"lesson","id":"114193","title":"Смена 8. Всё под контролем"},{"id":"104160","type":"test"},{"type":"lesson","id":"114194","title":"Смена 9. Вайб, кэш и харизма"},{"id":"104161","type":"test"},{"type":"lesson","id":"114195","title":"Смена 10. Режим штурма"},{"id":"104181","type":"test"},{"id":"105476","type":"test"},{"type":"lesson","id":"114197","title":"Смена 11. Выход на большую сцену"},{"id":"104187","type":"test"},{"type":"lesson","id":"114198","title":"Смена 12. Чисто, чётко, по стилю"},{"id":"104335","type":"test"},{"id":"104336","type":"test"},{"type":"lesson","id":"114199","title":"Смена 13. Теперь ты — наставник"},{"id":"104337","type":"test"},{"type":"lesson","id":"114200","title":"Смена 14. Первый сольник"},{"id":"104338","type":"test"},{"type":"lesson","id":"114201","title":"Смена 15. Финальный трек"},{"type":"lesson","id":"114202","title":"Смена 16. Выпускной"}],"testIds":["100075","100153","100159","100172","104138","104142","104144","104160","104161","104181","104187","104335","104336","104337","104338","104760","104939","105476"],"priority":"start","sequence":[{"type":"lesson","id":"122794","title":"Критерии оценки официанта: на что смотрят наставники и менеджеры 📋"},{"type":"lesson","id":"114183","title":"Смена 1. Погружение в атмосферу"},{"id":"100075","type":"test"},{"type":"lesson","id":"114185","title":"Смена 2. Врываемся в движ"},{"id":"100153","type":"test"},{"type":"lesson","id":"114188","title":"Смена 3. Первый выход в зал — наблюдаем и учимся у наставника 🎭"},{"id":"100159","type":"test"},{"type":"lesson","id":"114189","title":"Смена 4. Теперь ты в теме"},{"id":"100172","type":"test"},{"type":"lesson","id":"114190","title":"Смена 5. Совместный трек с кухней"},{"id":"104138","type":"test"},{"type":"lesson","id":"114191","title":"Смена 6. Включай iiko"},{"id":"104142","type":"test"},{"type":"lesson","id":"114192","title":"Смена 7. Практика в действии"},{"id":"104144","type":"test"},{"id":"104760","type":"test"},{"id":"104939","type":"test"},{"type":"lesson","id":"114193","title":"Смена 8. Всё под контролем"},{"id":"104160","type":"test"},{"type":"lesson","id":"114194","title":"Смена 9. Вайб, кэш и харизма"},{"id":"104161","type":"test"},{"type":"lesson","id":"114195","title":"Смена 10. Режим штурма"},{"id":"104181","type":"test"},{"id":"105476","type":"test"},{"type":"lesson","id":"114197","title":"Смена 11. Выход на большую сцену"},{"id":"104187","type":"test"},{"type":"lesson","id":"114198","title":"Смена 12. Чисто, чётко, по стилю"},{"id":"104335","type":"test"},{"id":"104336","type":"test"},{"type":"lesson","id":"114199","title":"Смена 13. Теперь ты — наставник"},{"id":"104337","type":"test"},{"type":"lesson","id":"114200","title":"Смена 14. Первый сольник"},{"id":"104338","type":"test"},{"type":"lesson","id":"114201","title":"Смена 15. Финальный трек"},{"type":"lesson","id":"114202","title":"Смена 16. Выпускной"}],"positions":["Официант","Администратор зала","Хостес"],"questions":[],"coverLabel":"Стандарты и стажировка официанта","shortTitle":"Стандарты и стажировка","departments":["Зал"],"description":"Единая база сервиса и 16 практических смен с наставником. Открытие зала, обслуживание, iiko, продажи и подготовка к аттестации.","restaurantIds":["pushkino","khimki","mytishchi"],"trainingBrand":"90","audienceLevels":["trainee","certified"],"audiencePositions":["Официант","Администратор зала"],"audiencePriorities":{},"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"lessons":[{"id":"122794","title":"Критерии оценки официанта: на что смотрят наставники и менеджеры 📋","blocks":[{"id":"course-122794-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-0-0.jpg","label":"Стандарты и стажировка официанта","title":"Критерии оценки официанта: на что смотрят наставники и менеджеры 📋"},{"id":"course-122794-2","html":"<p>Привет, стажёр! 👋</p><p>Чтобы ты чётко понимал, к чему стремиться и как оценивают твою работу, мы создали Контрольный лист наблюдения (КЛН). Это свод стандартов, по которым каждый официант проверяется в течение смены и на финальной аттестации.</p><p>Ознакомься с ним в самом начале стажировки и возвращайся к нему после каждой смены, чтобы видеть свой прогресс. Твоя цель – к 16‑й смене набрать не менее 85% от максимального балла. Поехали! 🚀</p>","type":"text"},{"id":"course-122794-3","text":"Как оцениваются критерии?","type":"heading","level":2},{"id":"course-122794-4","text":"Каждый пункт оценивается по простой шкале:","type":"heading","level":3},{"id":"course-122794-5","type":"list","items":["1 балл – выполнено идеально, соответствует стандарту","0,5 балла – выполнено частично, есть мелкие недочёты","0 баллов – не выполнено или выполнено с грубыми ошибками"],"ordered":false},{"id":"course-122794-6","text":"После проверки все баллы суммируются и переводятся в проценты по формуле:","type":"heading","level":3},{"id":"course-122794-7","type":"list","items":["Итоговый результат = (сумма набранных баллов ÷ 29) × 100%","Максимум – 29 баллов (100%). Минимальный проходной порог – 85%."],"ordered":false},{"id":"course-122794-8","text":"Полный список критериев КЛН","type":"heading","level":2},{"id":"course-122794-9","text":"1. Общие стандарты","type":"heading","level":3},{"id":"course-122794-10","text":"2. Шаг 1 – Приветствие","type":"heading","level":3},{"id":"course-122794-11","text":"3. Шаг 2 – Принятие заказа","type":"heading","level":3},{"id":"course-122794-12","text":"4. Шаг 3 – Сервировка, подача блюд и напитков","type":"heading","level":3},{"id":"course-122794-13","text":"5. Шаг 4 – Check-back и дополнительный сервис","type":"heading","level":3},{"id":"course-122794-14","text":"6. Шаг 5 – Расчёт и прощание","type":"heading","level":3},{"id":"course-122794-15","src":"assets/extra-courses/waiter-internship-0-1.jpg","type":"image","caption":""},{"id":"course-122794-16","src":"assets/extra-courses/waiter-internship-0-2.jpg","type":"image","caption":""},{"id":"course-122794-17","src":"assets/extra-courses/waiter-internship-0-3.jpg","type":"image","caption":""},{"id":"course-122794-18","src":"assets/extra-courses/waiter-internship-0-4.jpg","type":"image","caption":""},{"id":"course-122794-19","src":"assets/extra-courses/waiter-internship-0-5.jpg","type":"image","caption":""},{"id":"course-122794-20","src":"assets/extra-courses/waiter-internship-0-6.jpg","type":"image","caption":""},{"id":"course-122794-21","text":"Как использовать этот лист в стажировке","type":"heading","level":2},{"id":"course-122794-22","type":"list","items":["1. В начале курса – прочитай все пункты, чтобы понимать, к чему мы идём."],"ordered":false},{"id":"course-122794-23","text":"2. В каждой смене – мы будем давать небольшие отсылки к КЛН, например:","type":"heading","level":3},{"id":"course-122794-24","type":"list","items":["«Сегодня тренируем критерии 14.0, 18.0, 21.0»","Это поможет тебе фокусироваться на конкретных навыках.","3. Наблюдай за наставником – отмечай, как он выполняет те или иные пункты. Учись на его примере.","4. В конце смены можешь попросить наставника предварительно оценить тебя по 2–3 пунктам, чтобы понимать свой прогресс.","5. Перед 16‑й сменой (обслуживание администрации) повтори все пункты – это будет твой финальный экзамен."],"ordered":false},{"id":"course-122794-25","text":"Что означают баллы в реальной работе","type":"heading","level":2},{"id":"course-122794-26","html":"<p>29 баллов – идеальный официант, гордость команды. Стремись к этому, но помни, что идеал недостижим, можно всегда расти.</p><p>25–28 баллов – отличный результат, ты уверенно держишь стандарты.</p><p>20–24 балла – хорошая база, есть над чем работать. Обрати внимание на пункты с низкими оценками.</p><p>Ниже 20 – нужно серьёзно подтянуть знания и навыки, не стесняйся просить помощи у наставника.</p><p>Успехов! Этот лист – твой навигатор в мире профессионального сервиса. Держи его в голове, и ты быстро станешь настоящим профи. 🔥</p>","type":"text"},{"id":"course-122794-27","url":"https://golnk.ru/J0xy0","text":"Контрольный лист наблюдения (КЛН).","type":"link"}]},{"id":"114183","title":"Смена 1. Погружение в атмосферу","blocks":[{"id":"course-114183-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-1-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 1. Погружение в атмосферу"},{"id":"course-114183-2","text":"Привет, новичок! 👋","type":"heading","level":2},{"id":"course-114183-3","html":"<p>Сегодня твой первый день в нашем баре — месте, где живёт дух 90-х💿, играет настоящая музыка🎶 и гости приходят не просто выпить, а отмотать время назад✨</p><p>Не спеши бежать за подносом — сегодня тебе важно впитать атмосферу, понять, как тут всё устроено, и познакомиться с командой 💪👯‍♀️</p><p>Добро пожаловать в семью — теперь ты часть настоящей эпохи!😉</p>","type":"text"},{"id":"course-114183-4","text":"Экскурсия по бару 🍸","type":"heading","level":2},{"id":"course-114183-5","html":"<p>Начни с прогулки по территории — ведь теперь это твой второй дом. 🏠✨</p>","type":"text"},{"id":"course-114183-6","text":"Загляни в каждое место, куда обычно гости не попадают:","type":"heading","level":3},{"id":"course-114183-7","type":"list","items":["🍸 Барная стойка — сердце нашего заведения.","👨‍🍳 Кухня — тут творится настоящая магия.","📦 Склады и раздевалка — без них бар бы не жил.","🚻 Санузлы — чистота и порядок важны даже там.","Присмотрись, как всё устроено!"],"ordered":false},{"id":"course-114183-8","text":"Правила игры 🎮","type":"heading","level":2},{"id":"course-114183-9","html":"<p>Каждое заведение живёт по своим законам — и у нас тоже есть свои.</p>","type":"text"},{"id":"course-114183-10","text":"⬇️Сегодня ты узнаешь про:","type":"heading","level":3},{"id":"course-114183-11","type":"list","items":["Внешний вид — у нас не скучно, но аккуратно. Опрятность — часть стиля.","Распорядок дня — когда приходить, где отмечаться и когда можно перекусить.","Регламенты — как носить униформу, как здороваться с гостями и что делать, если что-то пошло не по плану.","В 90-х каждый хотел выделиться. Главное — делай это со вкусом😉"],"ordered":false},{"id":"course-114183-12","text":"Внешний вид 😎","type":"heading","level":2},{"id":"course-114183-13","html":"<p>Наш официант — не просто человек с подносом. Он — часть шоу, моторчик движа и главный носитель атмосферы💫</p><p>Разберёмся, как именно должен выглядеть и чувствовать себя человек, который встречает гостей под хиты 90-х. Ты не должен быть моделью с обложки📖, но выглядеть свежо, бодро и уверенно💪 — обязательно.</p>","type":"text"},{"id":"course-114183-14","text":"✅ Вот чек-лист внешнего вида:","type":"heading","level":3},{"id":"course-114183-15","type":"list","items":["Чистая кожа (а если где-то «неидеал» — \"штукатурка\" в помощь 😎).","Уложенные волосы — никаких \"я только проснулся\".","Ухоженные руки и ногти — они в кадре чаще, чем ты думаешь.","Лёгкий аромат, без передоза парфюмом — гости пришли наслаждаться коктейлями, а не духами.","У нас не просто форма — у нас стиль эпохи.","Джинсовки, яркие цвета, цепочки, браслеты, резинки, чокеры — всё, что отсылает к 90-м, приветствуется❗","Главное — чисто, аккуратно и со вкусом. Если вид неопрятный, гость подумает, что и коктейль у нас такой же — «вчерашний». А нам такое не надо 😉"],"ordered":false},{"id":"course-114183-16","text":"🎉 Для нас ты — вайб:","type":"heading","level":3},{"id":"course-114183-17","type":"list","items":["⚡ Главный моторчик движа. Без тебя вечеринка не взлетит.","😄 Весёлый друг, которому не по барабану, что происходит в зале.","💖 Фанат заведения, который сам кайфует от атмосферы и заражает ею гостей.","Когда гость чувствует, что ты в потоке, он возвращается. Не потому что скидка, а потому что тут кайф!🥳","Будь симпатягой, стильным и уверенным.","Смотри в зеркало и спрашивай себя: «Я бы заказал у себя коктейль?».","Если ответ «да» — ты готов к смене💫"],"ordered":false},{"id":"course-114183-18","text":"Распорядок дня ⌚","type":"heading","level":2},{"id":"course-114183-19","html":"<p>Приход на работу</p>","type":"text"},{"id":"course-114183-20","text":"Время выхода и готовность зала","type":"heading","level":3},{"id":"course-114183-21","type":"list","items":["Перед сменой проверь время выхода и сбора в актуальном графике своей точки. Если график и памятка расходятся или предстоит банкет, заранее уточни время у ответственного за смену.","Уточни время брифинга и срок подготовки зала.","Если к согласованному времени зал готов, но терминал не работает, сообщи старшему и уточни порядок расчётов до устранения сбоя.","⏰ Опаздываешь? Проблема!","Заранее предупреди менеджера, если не успеваешь. Опоздания сбивают ритм и портят атмосферу💫","Здесь важен командный дух, поэтому подводить своих — не вариант👎","Если заранее нашёл себе замену — молодец 👍","Но всё равно сообщи менеджеру.","Короткий перерыв","Время перерыва зависит от загрузки и правил точки.","Согласуй короткий перерыв со старшим. Передай столы конкретному коллеге и убедись, что он принял подмену. Сообщи, что уже заказано, чего ждут гости и о чём они просили.","🚫 Не ходи курить толпой — ты же не на перемене в школе!","🌿 После перекура — жвачка или спрей для свежести.","Общение с гостями","Всегда улыбаемся!😊 Даже если день не задался — твоя улыбка делает атмосферу.","Используй лёгкий сленг 90-х💬 — гости сразу чувствуют вайб ностальгии.","Если что-то не знаешь❓ — уточни у менеджера. Если возник вопрос в разговоре с гостем — скажи, что уточнишь и вернёшься с ответом.","Держим лицо в любой ситуации😎 : даже если гость капризный — решаем всё с позитивом и юмором.","📚 Это ещё не все правила, которые тебе нужно знать.","❗ Загляни в Библиотеку — там тебя ждут «Правила сотрудника на смене»."],"ordered":false},{"id":"course-114183-22","text":"Структура зала 🗺️","type":"heading","level":2},{"id":"course-114183-23","text":"Каждый официант должен знать свой зал как свои пять ✋ пальцев:","type":"heading","level":3},{"id":"course-114183-24","type":"list","items":["изучи структуру и планировку💭 — где служебные зоны и основные проходы.","запомни нумерацию столов 🔢 — это поможет быстро ориентироваться и обслуживать без суеты.","разберись, какие зоны и столы закреплены за тобой🪑 — чтобы всегда быть на своём месте и держать ситуацию под контролем.","МСК, Химки, ул.Родионова, 2к1","МСК, Мытищи, пр-т Олимпийский, 29/2 (ТЦ Формат) 1 этаж","МСК, Пушкино, пр-т Московский 54А"],"ordered":false},{"id":"course-114183-25","src":"assets/extra-courses/waiter-internship-1-1.jpg","type":"image","caption":""},{"id":"course-114183-26","src":"assets/extra-courses/waiter-internship-1-2.jpg","type":"image","caption":""},{"id":"course-114183-27","src":"assets/extra-courses/waiter-internship-1-3.jpg","type":"image","caption":""},{"id":"course-114183-28","text":"Концепция и вайб 💫","type":"heading","level":2},{"id":"course-114183-29","html":"<p>💿Наш бар — не просто место с коктейлями. Это машина времени в 90-е✨</p><p>😎Музыка, напитки, выражения — всё из той эпохи. Гости приходят сюда не просто отдохнуть — они погружаются в ностальгию, чтобы снова почувствовать тот драйв⚡</p><p>❗Твоя задача — не только принести заказ, но и поддержать атмосферу: 😊 улыбка, 😏 лёгкая шутка,🕶️ свой стиль общения — всё это делает вечер по-настоящему улётным.</p><p>🎶 Почувствуй ритм бара, улови настроение — от этого зависит, как тебя воспримут гости.</p>","type":"text"},{"id":"course-114183-30","text":"Учись у старших 👀","type":"heading","level":2},{"id":"course-114183-31","text":"Сегодня твой главный инструмент — глаза и уши. Смотри внимательно, как работает твой наставник:","type":"heading","level":3},{"id":"course-114183-32","type":"list","items":["👋 Как он встречает гостей","👐 Как держит поднос и двигается по залу","⚡ Как реагирует, если что-то идёт не по плану","❗Не бойся задавать вопросы — даже самые простые.","Здесь никто не родился с подносом в руке, но каждый может стать гуру сервиса💪"],"ordered":false},{"id":"merged--1","type":"heading","text":"Правила общения и работы в команде","level":2},{"id":"merged--2","type":"text","html":"<p>Создавай атмосферу заведения и подстраивай тон под гостя. Если он не поддерживает шутки, общайся спокойно и доброжелательно. Если не знаешь ответа, уточни у менеджера и обязательно вернись к гостю.</p><p>Перед перерывом согласуй уход со старшим и передай столы конкретному коллеге. Сообщи, что заказано, чего ждут гости и какие у них просьбы. Убедись, что подмену приняли. Не уходите всей командой одновременно. О задержке или замене заранее сообщи менеджеру.</p><p>Проверь форму, обувь, волосы и руки перед выходом. Форма должна быть чистой и опрятной. Во время смены замени испачканный элемент, а сломанный аксессуар сними и согласуй замену, если он обязателен. Допустимые аксессуары уточняй по стандарту своей точки. Парфюм не должен быть резким.</p><p>Замечай просьбы гостей за соседними столами: уточни просьбу и передай ответственному официанту. Гость должен чувствовать внимание всей команды.</p>"},{"id":"merged-roles-0","type":"list","items":["Главный моторчик движа, без которого не будет улетной атмосферы.","Веселый друг, которому не фиолетово, что происходит в зале – он понимает, что всё зависит от него.","Человек, который сам тащится от заведения и заряжает этой любовью гостей. Они возвращаются снова и снова, потому что здесь кайф!"],"ordered":false},{"id":"merged-roles-1","type":"list","items":["Эмоции: Лучший друг","Свой в доску, всегда на позитиве, улыбается и создаёт уютную атмосферу домашнего праздника.","Личностные качества: Радушный хозяин","Внимательный – сразу видит, что нужно гостю, и приносит это моментально.","Честный – никаких мутных тем, репутация заведения на кону.","Держит лицо – даже если устал или день не задался, гостю этого видеть не положено.","Не сыплет негативом – бар должен быть местом кайфа, а не разборок.","Разруливает конфликты ещё до того, как они завелись.","Открытый – сам заводит разговор, легко общается, помогает выбрать блюдо.","Профнавыки: Знает и умеет","Разбирается в меню как настоящий профи: знает, что вкусное, как готовят, за сколько минут принесут.","Мастер подачи: напитки и блюда на столе всегда быстро, красиво и в правильном порядке.","Чек закроет в два счёта, а стол поддержит в идеальной чистоте"],"ordered":false}]},{"id":"114185","title":"Смена 2. Врываемся в движ","blocks":[{"id":"course-114185-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-2-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 2. Врываемся в движ"},{"id":"course-114185-2","text":"Расстановка столов и сервировка 🍽️","type":"heading","level":2},{"id":"course-114185-3","html":"<p>Вчера ты познакомился с атмосферой💫 и командой, а сегодня — врываемся в работу с головой🚀</p><p>Изучи схему зала — где какие столы, какие виды, какие гости любят сидеть где.</p><p>Сегодня наставник покажет, как правильно расставить приборы, салфетки, бокалы и специи😉</p><p>❗Обязательно загляни в раздел Библиотека, найдешь там важные файлы: \"Правила сотрудника на смене\", \"Распределение чаевых\".</p><p>✅Изучи их.</p>","type":"text"},{"id":"course-114185-4","text":"Открытие смены ⏰","type":"heading","level":2},{"id":"course-114185-5","html":"<p>❗Открытие зала</p><p>🧾Чек-лист – твой лучший инструмент, чтобы держать всё под контролем! Это список вещей, которые нельзя пропустить при открытии смены.</p><p>Мебель. Опустить стулья, выровнять мебель, почистить ее средством, протереть подножья столов и стульев</p><p>Столы. Протереть их чистой влажной тряпкой</p><p>Засервировать столы. Постановочная тарелка, столовые приборы (нож, вилка), хайбол, тейблтенты с актуальной информацией, салфетница, текстильная салфетка. Чистые вымытые приборы высушиваем и полируем чистой предназначенной для этого салфеткой</p><p>Проверить и заполнить расходники в стейшене, также в стейшенах всегда должна быть чистая вода в ведре для уборки столов</p><p>Привести в порядок декор зала, протереть пыль</p><p>Расставить таблички с надписями на барный стол</p><p>Всё в порядке? Значит, ты готов к улётной смене! 🚀</p>","type":"text"},{"id":"course-114185-6","text":"Акции 💥","type":"heading","level":2},{"id":"course-114185-7","html":"<p>Перед сменой уточни у менеджера, какие предложения действуют сегодня в твоей точке. Перед обещанием гостю проверь сроки, ограничения, совместимость со скидками и доступные способы оплаты.</p><p>На брифинге уточни, как применить предложение в iiko и к кому обратиться, если условия непонятны.</p>","type":"text"},{"id":"course-114185-8","text":"Меню и барная карта 📖","type":"heading","level":2},{"id":"course-114185-9","html":"<p>📖 Меню — это твой главный инструмент и визитка бара. Гость может простить долгую подачу, но не простит, если официант не знает, что у него в меню 😉</p><p>📚 Чтобы разбираться в блюдах и напитках, зайди в раздел “Меню” и внимательно изучи его. Там собраны Основное меню и Барная карта — с описаниями, составом и подачей.</p><p>⚡ Помни: меню периодически обновляется, и все новости об изменениях выходят прямо на платформе. Следи за обновлениями, чтобы не оказаться в ситуации, когда гость знает больше, чем ты.</p><p>🧠 И ещё: периодически проходи тесты на знание меню. Это не формальность, а способ держать себя в тонусе и быть профи, которому доверяют и коллеги, и гости.</p>","type":"text"},{"id":"course-114185-10","text":"Закрытие смены 🌙","type":"heading","level":2},{"id":"course-114185-11","html":"<p>Когда музыка стихает, начинается магия🔮 — закрытие смены.</p><p>Тут каждый должен быть в теме: убрать зал, собрать посуду, протереть столы, привести бар в порядок.</p><p>🧼 Делай так, чтобы утром всё выглядело как после клипа MTV — чисто, блестяще, готово к новому дню.</p><p>✅Наставник покажет все шаги — от кассы до последнего бокала.</p><p>❗Главное — не халтурь, это уважение к команде и к себе.</p>","type":"text"},{"id":"merged--3","type":"heading","text":"Контроль перед открытием","level":2},{"id":"merged--4","type":"text","html":"<p>Проверь входную группу, пол, подоконники, коврик, пепельницы и вентиляцию; в зале — столы, стулья, декор и чистоту поверхностей. В гостевом туалете проверь чистоту, смыв, мыло и полотенца. В подсобке обувь стоит на полках, вещи висят на вешалках.</p><p>Проверь исправность терминала и наличие чековой ленты. Меню должно быть чистым, целым и актуальным. В стейшене должны быть тряпки, полироль, салфетки, сахар и зубочистки. Соль и перец пополняй до ¾ ёмкости.</p><p>Чистые приборы после мойки вытри и отполируй предназначенной для этого чистой салфеткой. Прибор со следами еды отправь на повторную мойку. Не заменяй мойку полировкой.</p><p>Подробный порядок закрытия смены — в смене 12. Сегодня ознакомься с ним вместе с наставником.</p>"}]},{"id":"114188","title":"Смена 3. Первый выход в зал — наблюдаем и учимся у наставника 🎭","blocks":[{"id":"course-114188-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-3-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 3. Первый выход в зал — наблюдаем и учимся у наставника 🎭"},{"id":"course-114188-2","text":"Обслуживание гостей 👥","type":"heading","level":2},{"id":"course-114188-3","html":"<p>Ты прошёл первые 2️⃣ дня и уже чувствуешь ритм бара. Сегодня — первый выход в зал! Но не переживай, ты не один. Твоя задача — наблюдать за наставником, учиться и помогать. Никакой самостоятельности — только работа в паре. 🤝</p><p>Учиться шагам обслуживания, наблюдая за наставником</p><p>Разобраться, что такое стоп-лист и как с ним работать</p><p>Под присмотром наставника/менеджера подавать и убирать блюда</p><p>К концу смены управляющий решит, готов ли ты двигаться дальше 💪</p>","type":"text"},{"id":"course-114188-4","text":"Как ты работаешь сегодня","type":"heading","level":2},{"id":"course-114188-5","src":"assets/extra-courses/waiter-internship-3-1.jpg","type":"image","caption":""},{"id":"course-114188-6","text":"Шаги обслуживания — наблюдаем и запоминаем 👀","type":"heading","level":2},{"id":"course-114188-7","html":"<p>Сегодня ты проходишь все шаги обслуживания, но в роли наблюдателя. Наставник показывает — ты смотришь, запоминаешь, задаешь вопросы.</p><p>ШАГ 1️⃣ — Приветствие</p><p>Врываемся с улыбкой! 😃</p><p>Заходим на позитиве – дарим гостю хорошее настроение с порога и представляемся!</p><p>Меню подаём открытой рукой</p><p>Бонус: пока гость листает меню, предлагай что-нибудь освежающее – сразу +1 к продажам!</p>","type":"text"},{"id":"course-114188-8","text":"❗Важно! Наблюдай:","type":"heading","level":3},{"id":"course-114188-9","type":"list","items":["Как наставник заходит с улыбкой","Как представляется гостям","Как подает меню (открытой рукой)","Предлагает ли что-то освежающее, пока гость изучает меню","Твоя задача: запомнить эти движения и фразы. В следующих сменах будешь делать сам.","ШАГ 2️⃣ — Прием заказа","Выясняем, чего душа хочет, помогаем выбрать блюда","Раскачиваем эмоции – аппетитные описания блюд, от которых слюнки потекут.","Бонус: «Хотите крутой гарнир или эксклюзивный соус к этому?» – больше вкуса, больше кайфа, больше продаж!","Время приготовления – если задержка, сразу говорим реальное время, гость будет благодарен за честность.","Повторяем заказ – чтобы не испортить впечатления от возможной ошибки!"],"ordered":false},{"id":"course-114188-10","text":"❗Важно! Сегодня ты НЕ принимаешь заказ. Ты просто стоишь рядом (чуть поодаль) и слушаешь, как это делает наставник.","tone":"yellow","type":"callout","title":""},{"id":"course-114188-11","text":"На что обратить внимание:","type":"heading","level":3},{"id":"course-114188-12","type":"list","items":["Какие вопросы задает наставник?","Как описывает блюда, чтобы гостю захотелось заказать?","Как уточняет детали (прожарка, соус, аллергии)?","Как повторяет заказ перед отправкой на кухню?","Бонус: Если наставник разрешит, можешь записывать заказ в блокнот для тренировки — но в систему вносит только наставник.","ШАГ 3️⃣ — Подача","Блюда подаём открытой рукой, как профессионалы.","Всё приносим синхронно – никто не ждёт, все довольны!","Первыми – закуски, потом горячее, затем десерты – чистый ритм сервиса!"],"ordered":false},{"id":"course-114188-13","text":"❗Важно:","type":"heading","level":3},{"id":"course-114188-14","text":"Под присмотром наставника ты можешь:","type":"heading","level":3},{"id":"course-114188-15","type":"list","items":["Помочь нести блюда к столу (но только если уверен, что не уронишь!)","Подать тарелку гостю (наставник показывает, с какой стороны, а ты пробуешь)","Следить, чтобы блюда подавались синхронно (холодное, горячее, десерты)"],"ordered":false},{"id":"course-114188-16","text":"Важно: Не берись за сложные подачи (например, горячие тарелки или несколько блюд сразу), пока наставник не скажет, что ты готов.","tone":"yellow","type":"callout","title":""},{"id":"course-114188-17","html":"<p>ШАГ 4️⃣ — Чек-бэк</p><p>«Ну как? Огонь?» – не просто спрашиваем, а реально чувствуем эмоции гостя!🔥</p><p>❗Если что-то не так – сразу решаем вопрос. Гасим возможные конфликты ещё до их появления.</p><p>Подробнее о чек бэке - ниже.</p>","type":"text"},{"id":"course-114188-18","text":"❗Важно! Наблюдай: Наставник подходит к гостям через 2–3 минуты после подачи и спрашивает, всё ли нравится. Слушай, как он это делает — не скучное «Всё ли в порядке?», а искренний интерес.","tone":"yellow","type":"callout","title":""},{"id":"course-114188-19","html":"<p>ШАГ 5️⃣ — Расчет</p><p>Гость попросил счёт? Не стоим, несём моментально!</p><p>Если в точке действует программа лояльности, уточни у гостя, пользуется ли он ей. Перед расчётом проверь условия акции и доступные способы оплаты.</p><p>«Наличные или карта, общий или раздельный?» – всё чётко, без лишних вопросов.</p>","type":"text"},{"id":"course-114188-20","text":"❗Важно! Наблюдай: Как наставник реагирует на просьбу о счете, как уточняет способ оплаты, как благодарит и прощается","tone":"yellow","type":"callout","title":""},{"id":"course-114188-21","html":"<p>ШАГ 6️⃣ — Прощание</p><p>«Спасибо, что заглянули, ждём снова!» – главное, чтобы звучало искренне.</p>","type":"text"},{"id":"course-114188-22","text":"Финальный аккорд:","type":"heading","level":3},{"id":"course-114188-23","type":"list","items":["Улыбка😊, кивок, возможно даже стильный жест рукой✋ – гость должен уходить с ощущением, что его реально ждали!","Пересервируем стол🍽️ за 2-3 минуты – новые гости уже на подходе!🔥"],"ordered":false},{"id":"course-114188-25","html":"<p>Уборка посуды 🧹</p>","type":"text"},{"id":"course-114188-26","text":"Под контролем наставника:","type":"heading","level":3},{"id":"course-114188-27","type":"list","items":["Учишься забирать пустые тарелки (с какой стороны, как не мешать)","Учишься правильно держать стопку тарелок (грязное не смешивать с чистым)","Учишься убирать бокалы (только за ножку!)"],"ordered":false},{"id":"course-114188-28","text":"Чек-бэк и его важность 💭","type":"heading","level":2},{"id":"course-114188-29","html":"<p>Check Back (чек-бэк) – это твой инструмент, чтобы понять, насколько гость доволен.</p><p>Вкусно ли ему❓</p><p>Всё ли ок с качеством блюд и напитков❓</p><p>Не нужно ли ему что-то еще (салфетки, соус, пепельница)❓</p><p>❗А ещё чек-бэк – это твой шанс предотвратить конфликт на ранней стадии!</p><p>💭 Как его делать?</p><p>После подачи блюд ждём немного времени, чтобы гость успел попробовать.</p><p>Подходим, спрашиваем, как ему еда.</p><p>Если гость недоволен – выясняем, в чём дело.</p><p>Если проблема из-за качества блюда (неправильно приготовлено, остывшее и т.д.), сообщаем менеджеру.</p><p>Менеджер решает, включать ли блюдо в счёт.</p>","type":"text"},{"id":"course-114188-30","text":"✨Виды чек-бэка:","type":"heading","level":3},{"id":"course-114188-31","type":"list","items":["✅ Текущий – быстрый фидбэк","Ждёшь 2-3 минуты после первой вилки еды.","Подходишь, если гость заказал твою рекомендацию или новинку."],"ordered":false},{"id":"course-114188-32","text":"Важно! Не перебиваем важную беседу, ждём удачного момента.","tone":"yellow","type":"callout","title":""},{"id":"course-114188-33","html":"<p>✅ Поэтапный – шаг за шагом</p><p>Спрашиваем мнение, когда убираем тарелку.</p><p>Если гость не доел – обязательно выясняем, почему.</p><p>Если гость не в восторге от твоей рекомендации – не паримся: «Да, вкусы у всех разные, зато теперь я знаю, что советовать вам в следующий раз!»</p><p>✅ Контрольный – закрепляем успех</p><p>Спрашиваем о впечатлениях, когда гость просит счёт.</p><p>Он ещё раз вспоминает, как классно провёл время.</p><p>Проговаривая впечатления, фиксирует их в памяти, а значит, захочет вернуться!</p>","type":"text"},{"id":"course-114188-34","text":"❗Важный момент:","type":"heading","level":3},{"id":"course-114188-35","type":"list","items":["Не спрашиваем скучные «Всё ли в порядке?» или «Вам что-то не нравится?» – такие вопросы не цепляют. Подходи к гостю с искренним интересом!","Какой чек-бэк использовать? Решай сам, пробуй разные варианты и найди тот, который работает для тебя лучше всего! 🚀"],"ordered":false},{"id":"course-114188-36","text":"Что такое стоп-лист? 📋🚫","type":"heading","level":2},{"id":"course-114188-37","html":"<p>Стоп-лист — это список блюд, которые временно недоступны (закончились ингредиенты, не успевают готовить и т.д.).</p><p>Где смотреть стоп-лист?</p><p>В iiko на главном экране (обычно есть кнопка или значок)</p><p>На кухне на специальном стенде</p><p>В рабочем чате (если повара пишут туда)</p><p>Что делать, если гость заказал блюдо из стоп-листа?</p>","type":"text"},{"id":"course-114188-38","text":"Наставник покажет, как правильно предложить альтернативу. Например:","type":"heading","level":3},{"id":"course-114188-39","type":"list","items":["«К сожалению, этого блюда сегодня нет, но могу порекомендовать...»"],"ordered":false},{"id":"course-114188-40","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114188-41","html":"<p>Задание 1. Тень наставника</p><p>Весь вечер ходи за наставником (не мешая ему). Наблюдай за каждым его действием. В голове прокручивай: «Почему он так сделал?», «Что бы я сделал по-другому?».</p><p>Задание 2. Помощь в простых задачах</p>","type":"text"},{"id":"course-114188-42","text":"Когда наставник дает добро:","type":"heading","level":3},{"id":"course-114188-43","type":"list","items":["Поднеси стаканы с водой","Убери пустую тарелку (под контролем)","Принеси салфетки, если просят","Задание 3. Изучение стоп-листа","В начале смены попроси наставника показать, где смотреть стоп-лист. В середине смены подойди и проверь, не появились ли новые позиции.","Задание 4. Вопросы наставнику"],"ordered":false},{"id":"course-114188-44","text":"В конце смены спроси:","type":"heading","level":3},{"id":"course-114188-45","type":"list","items":["«Что у меня сегодня получилось хорошо?»","«На что мне обратить внимание в следующий раз?»"],"ordered":false},{"id":"course-114188-46","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114188-47","html":"<p>Я видел, как наставник приветствует гостей 😃</p><p>Я слышал, как правильно принимать заказ 📝</p><p>Я помогал подавать блюда под контролем 🍽️</p><p>Я помогал убирать посуду 🧹</p><p>Я узнал, где смотреть стоп-лист 📋</p><p>Я получил обратную связь от наставника 📝</p>","type":"text"},{"id":"course-114188-48","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114188-49","html":"<p>...гость обратился напрямую к тебе?</p><p>Улыбнись и скажи: «Я пока стажер, сейчас позову [Имя наставника], он вам поможет». Не пытайся отвечать на сложные вопросы.</p><p>...ты чуть не уронил тарелку?</p><p>Не паникуй. Если удержал — выдохни. Если уронил — сразу позови наставника или уборщицу.</p><p>...тебе кажется, что наставник делает что-то не так?</p><p>Не критикуй вслух. Просто запомни и позже, в подходящий момент, спроси: «А почему ты так сделал?» — возможно, у этого есть причина.</p><p>...наставник занят, а гость зовет?</p><p>Скажи: «Одну минуту, я позову коллегу» — и иди за наставником.</p>","type":"text"},{"id":"course-114188-50","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114188-51","html":"<p>Сегодня ты не звезда, ты — тень звезды. И это нормально! Лучший способ научиться — смотреть на профессионала и делать как он. Не стесняйся задавать вопросы, будь полезным и внимательным.</p><p>К концу смены управляющий скажет, готов ли ты идти дальше. Не переживай, если не всё получилось сразу — мы все через это проходили. 😊</p><p>Ты справишься! Уже через пару смен ты будешь работать увереннее. 💪</p><p>Следующая смена — знакомство с баром и посудой. Готовься! 🍸</p>","type":"text"},{"id":"merged--5","type":"heading","text":"Границы полномочий при жалобе","level":2},{"id":"merged--6","type":"text","html":"<p>Выясни, что именно не понравилось, поблагодари за обратную связь и сообщи менеджеру. Не обещай скидку, замену или исключение блюда из счёта самостоятельно. Решение по счёту принимает менеджер. Подробный алгоритм работы с жалобой отработаешь в смене 9.</p>"}]},{"id":"114189","title":"Смена 4. Теперь ты в теме","blocks":[{"id":"course-114189-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-4-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 4. Теперь ты в теме"},{"id":"course-114189-2","text":"Бар — сердце движа 🍸","type":"heading","level":2},{"id":"course-114189-3","html":"<p>✨Сегодня ты переходишь на новый уровень — знакомишься с баром, оргструктурой команды и внутренней коммуникацией.</p><p>🥂Бар — это не просто место, где наливают. Это сцена, где рождаются эмоции и стиль заведения.</p><p>Старший бармен или бармен проведёт для тебя мини-тренинг. Ты узнаешь, какие напитки считаются “фирменными” и как бар работает в пиковые часы⌛</p><p>Ниже⬇️ ты познакомишься с посудой, которую используют наши бармены.</p><p>Запомни не только внешний вид бокалов, но и их назначение — это поможет уверенно принимать заказы и выглядеть профи в глазах гостей.</p>","type":"text"},{"id":"course-114189-4","text":"Бокалы и их назначение 🍷","type":"heading","level":2},{"id":"course-114189-5","html":"<p>Штоф 0.5 л.</p><p>Штоф - сосуд для крепких спиртных напитков например: водка, виски, ром, текила, джин, бренди.</p><p>Хайбол 295 мл.</p><p>Хайбол - подается к холодным б/а напиткам (сок, морс, лимонад, кола и т.д), холодным литровым алко-коктейлям (Алёшка), к пиву. Также в нем отдаются некоторые коктейли вроде (Love is, Секс на пляже и т.д.).</p><p>Дабл хайбол 450 мл.</p><p>Дабл хайбол - используется для отдачи коктейлей (Мальчик хочет в Таиланд, Голубая лагуна, Младший лейтенант, Лонг Айленд, Мам Я в хлам, Галлюцинации фрекен бок и т.д.). Также используется для отдачи лимонадов (цитрусовый, ягодный, огуречный).</p><p>Кувшин 1 л.</p><p>Кувшин - используется для подачи (лимонадов, сока, морса, коктейля Алешка).</p><p>Олд фэшн 345 мл.</p><p>Олд фэшн - используется для отдачи коктейлей (Олд Фешн, Виски Саур, Москоу Невер Слип, Слово Пацана), из-за толстого дна бокал меньше нагревается за счет чего лед медленнее тает.</p><p>Рокс 269 мл.</p><p>Рокс - бокал для подачи недорогого крепкого алкоголя (виски, ром), кроме водки, а также вермуты в чистом виде (бьянко, фиеро и т.д.).</p><p>Капито 180 мл.</p><p>Капито - за счет форм бокала, алкоголь в нем равномерно насыщается кислородом. Советуется для подачи хорошего купажированного и однослодового виски, также коньяка.</p><p>Флютте 155 мл.</p><p>Флютте - за счет форм бокала, алкоголь в нем равномерно насыщается кислородом. Советуется для подачи хорошего купажированного и однослодового виски, также коньяка.</p><p>Эклипс 470 мл.</p><p>Эклипс - бокал (хрусталь) для коктейля «Нектар богов».</p><p>Винный бокал 385 мл.</p><p>Винный бокал - для вина, коктейлей.</p><p>Ревел Ап 500 мл.</p><p>Ревел Ап - форма бокала поможет напитку насытиться кислородом, что раскроет его вкус и аромат. Подходит для отдачи красного, белого и игристого вина, также подается к шампанскому.</p><p>Шалле 300 мл.</p><p>Шалле - коктейльный бокал (Порнстар Мартини, Кловер Клаб).</p><p>Тики бокалы 450 мл.</p><p>Тики бокалы - керамические коктейльные бокалы (Пина Колада, Май Тай, Студент Зомби). Элемент гавайской культуры для подачи тропических напитков.</p><p>Снифтер 398 мл.</p><p>Снифтер - для подачи бренди, коньяка, арманьяка и кальвадоса в чистом виде.</p><p>Коктейльная рюмка 190 мл.</p><p>Коктейльная рюмка - для охлажденных коктейлей среднего объема, но без льда. Не используется для подачи напитков со льдом и в чистом виде (в т.ч. и вермута Мартини, несмотря на название).</p><p>Маргаритка 250 мл.</p><p>Маргаритка - бокал под коктейль «Маргарита».</p><p>Кубок 300 мл.</p><p>Кубок - для горячих напитков (глинтвейна), т.к. у него толстые стенки.</p><p>Медная Кружка</p><p>Медная Кружка - предназначена для коктейля Московский мул.</p><p>Блюдца</p><p>Блюдца - большое под американо и капучино, маленькое под эспрессо.</p><p>Молочник</p><p>Молочник - предназначен для подачи сливок, молока, меда.</p><p>Чашка</p><p>Чашка - предназначена для американо, капучино и чая. Чашка маленького размера предназначена для эспрессо.</p><p>Шот 40 мл.</p><p>Шот - для крепких напитков (водка, ягермейтер) или коктейлей-шотов.</p><p>Френч-пресс</p><p>Френч-пресс - для заваривания чая или аналогичных напитков.</p><p>Подстаканник</p><p>Подстаканник - для эксклюзивной подачи коктейля \"РЖД\".</p>","type":"text"},{"id":"course-114189-6","src":"assets/extra-courses/waiter-internship-4-1.jpg","type":"image","caption":""},{"id":"course-114189-7","src":"assets/extra-courses/waiter-internship-4-2.jpg","type":"image","caption":""},{"id":"course-114189-8","src":"assets/extra-courses/waiter-internship-4-3.jpg","type":"image","caption":""},{"id":"course-114189-9","src":"assets/extra-courses/waiter-internship-4-4.jpg","type":"image","caption":""},{"id":"course-114189-10","src":"assets/extra-courses/waiter-internship-4-5.jpg","type":"image","caption":""},{"id":"course-114189-11","src":"assets/extra-courses/waiter-internship-4-6.jpg","type":"image","caption":""},{"id":"course-114189-12","src":"assets/extra-courses/waiter-internship-4-7.jpg","type":"image","caption":""},{"id":"course-114189-13","src":"assets/extra-courses/waiter-internship-4-8.jpg","type":"image","caption":""},{"id":"course-114189-14","src":"assets/extra-courses/waiter-internship-4-9.jpg","type":"image","caption":""},{"id":"course-114189-15","src":"assets/extra-courses/waiter-internship-4-10.jpg","type":"image","caption":""},{"id":"course-114189-16","src":"assets/extra-courses/waiter-internship-4-11.jpg","type":"image","caption":""},{"id":"course-114189-17","src":"assets/extra-courses/waiter-internship-4-12.jpg","type":"image","caption":""},{"id":"course-114189-18","src":"assets/extra-courses/waiter-internship-4-13.jpg","type":"image","caption":""},{"id":"course-114189-19","src":"assets/extra-courses/waiter-internship-4-14.jpg","type":"image","caption":""},{"id":"course-114189-20","src":"assets/extra-courses/waiter-internship-4-15.jpg","type":"image","caption":""},{"id":"course-114189-21","src":"assets/extra-courses/waiter-internship-4-16.jpg","type":"image","caption":""},{"id":"course-114189-22","src":"assets/extra-courses/waiter-internship-4-17.jpg","type":"image","caption":""},{"id":"course-114189-23","src":"assets/extra-courses/waiter-internship-4-18.jpg","type":"image","caption":""},{"id":"course-114189-24","src":"assets/extra-courses/waiter-internship-4-19.jpg","type":"image","caption":""},{"id":"course-114189-25","src":"assets/extra-courses/waiter-internship-4-20.jpg","type":"image","caption":""},{"id":"course-114189-26","src":"assets/extra-courses/waiter-internship-4-21.jpg","type":"image","caption":""},{"id":"course-114189-27","src":"assets/extra-courses/waiter-internship-4-22.jpg","type":"image","caption":""},{"id":"course-114189-28","src":"assets/extra-courses/waiter-internship-4-23.jpg","type":"image","caption":""},{"id":"course-114189-29","src":"assets/extra-courses/waiter-internship-4-24.jpg","type":"image","caption":""},{"id":"course-114189-30","text":"Коммуникации и чаты 💬","type":"heading","level":2},{"id":"course-114189-31","text":"📱Сегодня тебя добавят в рабочие чаты, тебе нужно:","type":"heading","level":3},{"id":"course-114189-32","type":"list","items":["подписаться на ASK и внутренние группы,","ознакомиться с Правилами общения в чатах — там важно сохранять уважение, юмор и позитив, как и в реальной жизни.","💡Совет: будь корректен в сообщениях — это тоже часть твоего профессионализма."],"ordered":false}]},{"id":"114190","title":"Смена 5. Совместный трек с кухней","blocks":[{"id":"course-114190-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-5-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 5. Совместный трек с кухней"},{"id":"course-114190-2","text":"Меню, кухня и работа на раздаче","type":"heading","level":2},{"id":"course-114190-3","html":"<p>Сегодня ты выходишь на новый уровень — начинаешь разбираться в том, чем живет наша кухня и как устроена работа на раздаче. 🍳🔥</p><p>Кухня — это сердце ресторана ❤️. Именно здесь рождаются блюда, ради которых гости возвращаются снова и снова. А раздача — твой главный штаб в зале. 🏆</p><p>Ниже — всё, что нужно знать, чтобы уверенно ориентироваться в меню, контролировать качество блюд и всегда быть готовым к вопросам гостей. 👇</p>","type":"text"},{"id":"course-114190-4","text":"Акции","type":"heading","level":2},{"id":"course-114190-5","html":"<p>Перед сменой уточни у менеджера, какие предложения действуют сегодня в твоей точке. Перед обещанием гостю проверь сроки, ограничения, совместимость со скидками и доступные способы оплаты.</p>","type":"text"},{"id":"course-114190-6","text":"Что уточнить на брифинге","type":"heading","level":3},{"id":"course-114190-7","type":"list","items":["Какие акции действуют сегодня и для каких гостей.","На какие позиции и в какое время они распространяются.","Можно ли сочетать их с бонусами и как их оформить в iiko."],"ordered":false},{"id":"course-114190-9","text":"🔥 Топ-позиции меню. Блюда на компанию","type":"heading","level":2},{"id":"course-114190-10","html":"<p>Это наши хиты — то, что гости заказывают чаще всего. Предлагай их, когда видишь компанию от 3–4 человек. Это выгодно гостю и увеличивает средний чек. 📈</p><p>💡 Совет: Если какая‑то позиция временно отсутствует (стоп‑лист), предложи альтернативу из этого же раздела. Гости ценят, когда им помогают выбрать.</p>","type":"text"},{"id":"course-114190-12","text":"👀 Работа на раздаче. Как проверять внешний вид блюд","type":"heading","level":2},{"id":"course-114190-13","html":"<p>Ты — последний, кто видит блюдо перед тем, как оно попадет к гостю. Если что-то не так — верни поварам. Гость оценивает глазами в первую очередь. 👁️👁️</p><p>✅ Чек-лист перед подачей</p><p>Блюдо выглядит как на фото в меню 📸</p><p>Всё выложено аккуратно, без «каши» на тарелке ✨</p><p>Края тарелки чистые (нет соусов и крошек) 🧼</p><p>Гарниры и соусы на своих местах 🥗</p><p>Украшение свежее и уместное 🌿</p><p>Тарелка чистая снаружи (никаких отпечатков) 👆</p><p>🔍 Как это выглядит на примерах</p><p>⚠️ По этому же принципу проверяй все блюда. Если сомневаешься — позови наставника. 30 секунд задержки лучше, чем испорченное впечатление гостя. 👌</p>","type":"text"},{"id":"course-114190-15","text":"⏱️ Время приготовления","type":"heading","level":2},{"id":"course-114190-16","html":"<p>При высокой загрузке уточни актуальный ориентир на раздаче и сообщи его гостю до подтверждения заказа. Время в таблице — пример для тренировки.</p>","type":"text"},{"id":"course-114190-17","src":"assets/extra-courses/waiter-internship-5-4.jpg","type":"image","caption":""},{"id":"course-114190-18","text":"🧹 Расходники на раздаче. Твоя зона ответственности","type":"heading","level":2},{"id":"course-114190-19","html":"<p>Раздача — твой штаб. Здесь всегда должен быть порядок. 🧘</p>","type":"text"},{"id":"course-114190-20","text":"✅ Перед сменой и в течение вечера проверяй:","type":"heading","level":3},{"id":"course-114190-21","type":"list","items":["Бумажные салфетки — полные салфетницы + запас 📄","Влажные салфетки — обязательно, если в меню есть блюда для еды руками 💧","Палочки для роллов 🥢","Соль и перец — мельницы полные и чистые 🧂","Зубочистки","Приборы (ножи, вилки, ложки) — в достатке 🍴","Чистые тарелки — разных размеров 🍽️","💡 Если салфетки закончились — доложи сразу. Не жди, пока гость попросит. ⏰"],"ordered":false},{"id":"course-114190-22","text":"🤝 Практика с наставником","type":"heading","level":2},{"id":"course-114190-23","html":"<p>🎯 Задание 1. Разбор меню</p>","type":"text"},{"id":"course-114190-24","text":"Подойди к наставнику и расскажи:","type":"heading","level":3},{"id":"course-114190-25","type":"list","items":["— Какие акции работают сегодня? 🎁","— Назови 3 блюда на компанию, состав и цену. 📋","— Сколько готовятся холодные закуски? А горячее? ⏱️","🎯 Задание 2. Раздача","Вместе подойдите к раздаче, когда готовится заказ. Найди 3 любых блюда из списка и проверь по чек-листу. Если найдешь косяк — попроси наставника показать, как правильно вернуть блюдо поварам. 👨‍🍳","🎯 Задание 3. Расходники"],"ordered":false},{"id":"course-114190-26","text":"Проверь станцию:","type":"heading","level":3},{"id":"course-114190-27","type":"list","items":["— Всё ли на месте? 🔍","— Чего не хватает? ❓","— Доложи наставнику, пополните запасы вместе. 🤲"],"ordered":false},{"id":"course-114190-28","text":"✅ Чек-лист: что ты забираешь с собой после этой смены","type":"heading","level":2},{"id":"course-114190-29","html":"<p>Я знаю все текущие акции 🎯</p><p>Могу назвать 5 топ-позиций из раздела «Блюда на компанию» 🏆</p><p>Помню время приготовления всех категорий ⏰</p><p>Умею проверять блюда перед подачей 👁️</p><p>Знаю, какие расходники должны быть на станции всегда 🧼</p><p>Прошел практику с наставником на раздаче 🤝</p><p>🎉 Отлично! Ты в теме.</p><p>Следующая смена — знакомимся с Iiko. Там будет интересно! 💻🔥</p>","type":"text"},{"id":"merged--7","type":"heading","text":"Состав и внешний вид блюд","level":2},{"id":"merged--8","type":"text","html":"<p>Открой актуальное <a href=\"https://askacademy.ru/#/menu?section=kitchen\">меню кухни своего заведения</a> в академии. Состав, подачу, цену и наличие проверяй по его действующим карточкам и стоп-листу смены.</p><p>Перед выдачей сверь блюдо, стол, модификаторы, комплектацию, внешний вид и температуру подачи. Если подача не соответствует карточке, сообщи на раздаче и не подавай блюдо до исправления.</p>"}]},{"id":"114191","title":"Смена 6. Включай iiko","blocks":[{"id":"course-114191-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-6-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 6. Включай iiko"},{"id":"course-114191-2","html":"<p>Привет! 👋 Сегодня ты осваиваешь главный рабочий инструмент — систему iiko. Ниже — понятная пошаговая инструкция: от входа в систему до расчета гостя. 📱💻</p>","type":"text"},{"id":"course-114191-3","text":"1. Вход в систему 🔑","type":"heading","level":2},{"id":"course-114191-4","html":"<p>На терминале (планшете или сенсорном мониторе) нажми на экран, чтобы выйти из режима ожидания. 👆</p><p>Перед тобой появится окно авторизации.</p><p>Прокати свою личную карту 🎫 (или введи PIN-код, если карта не считывается).</p><p>Ты попадаешь на главный экран iikoFront — обычно это схема зала или список столов. 🗺️</p><p>💡 Если карта не работает — позови наставника или менеджера. 🆘</p>","type":"text"},{"id":"course-114191-5","text":"2. Открытие заказа (новый гость) 🪑👥","type":"heading","level":2},{"id":"course-114191-6","html":"<p>На схеме зала нажми на номер стола, за который сели гости. 👆</p>","type":"text"},{"id":"course-114191-7","text":"Проверка занятости стола:","type":"heading","level":3},{"id":"course-114191-8","type":"list","items":["Если стол свободен (обозначен зеленым или без отметок) — сразу откроется окно нового заказа. Можно работать! ✅","Если на столе уже есть открытый заказ (обозначен красным или другим цветом), система НЕ даст создать новый. Вам нужно либо продолжить работать с этим заказом (если гости те же), либо, если гости ушли, но забыли закрыть счет — срочно позвать менеджера для принудительного закрытия. 🚫🆘"],"ordered":false},{"id":"course-114191-9","text":"3. В открывшемся окне нового заказа введи количество гостей (нажми на цифру и","type":"heading","level":3},{"id":"course-114191-10","html":"<p>выбери или введи вручную). 👨‍👩‍👧‍👦</p>","type":"text"},{"id":"course-114191-11","text":"4. Если гость пользуется программой лояльности точки","type":"heading","level":3},{"id":"course-114191-12","html":"<p>Проверь карту или профиль гостя в iiko по порядку своего заведения.</p>","type":"text"},{"id":"course-114191-13","text":"3. Добавление блюд в заказ","type":"heading","level":2},{"id":"course-114191-14","html":"<p>В левой части экрана — меню (поделено на группы: «Закуски», «Салаты», «Горячее», «Бар» и т.д.).</p><p>Нажимай на группы, чтобы найти нужное блюдо.</p><p>Нажми на название блюда — оно добавится в заказ.</p>","type":"text"},{"id":"course-114191-15","text":"Если нужно изменить количество:","type":"heading","level":3},{"id":"course-114191-16","type":"list","items":["Нажми на блюдо в правой части экрана (в списке заказа).","Появятся кнопки «+» (увеличить) и «−» (уменьшить)."],"ordered":false},{"id":"course-114191-17","text":"5. Если у блюда есть модификаторы (например, соус на выбор или степень прожарки):","type":"heading","level":3},{"id":"course-114191-18","type":"list","items":["После добавления блюда автоматически откроется окно выбора.","Выбери нужный вариант и нажми ОК.","🔥 Важно: если не выбрал модификатор, а он обязательный — заказ не сохранится."],"ordered":false},{"id":"course-114191-19","text":"4. Отправка заказа на кухню (печать)","type":"heading","level":2},{"id":"course-114191-20","html":"<p>Когда все блюда добавлены, нажми кнопку «Печать» (обычно внизу экрана).</p><p>Блюда уходят на кухню, а на экране появится сообщение об успешной отправке.</p><p>После печати заказ становится «открытым» — ты можешь добавлять новые блюда (дозаказ).</p><p>⚠️ Если ошибочно добавил блюдо и оно еще не напечатано — просто нажми на него в заказе и выбери «Удалить». Если блюдо уже напечатано — зови наставника.</p>","type":"text"},{"id":"course-114191-21","text":"5. Просмотр заказа и добавление новых позиций 🔍➕","type":"heading","level":2},{"id":"course-114191-22","html":"<p>В любой момент ты можешь вернуться к столу, нажав на него на схеме зала. 👆</p><p>Чтобы добавить новые блюда — просто выбери их из меню и снова нажми «Печать» 🖨️</p><p>Система отправит на кухню только новые позиции. ✅</p>","type":"text"},{"id":"course-114191-23","text":"6. Расчет гостя (закрытие заказа) 💰🧾","type":"heading","level":2},{"id":"course-114191-24","text":"Когда гость просит счет:","type":"heading","level":3},{"id":"course-114191-25","text":"1. Открой заказ (нажми на стол на схеме). 👆","type":"heading","level":3},{"id":"course-114191-26","text":"2. Внимательно проверь чек:","type":"heading","level":3},{"id":"course-114191-27","type":"list","items":["Все ли позиции добавлены? ✅","Верно ли указано количество? 🔢","Добавлен ли депозит (в выходные и праздничные дни)? ⚠️","Для компаний от 6 человек — добавлен ли сервисный сбор? (уточни у наставника процент) ⚠️","3. Если всё верно — нажми кнопку «Пречек» (предварительный чек) и покажи гостю для проверки. 🧾"],"ordered":false},{"id":"course-114191-28","text":"4. Уточни у гостя способ оплаты: «Вы будете оплачивать наличными или картой?» 🗣️","type":"heading","level":3},{"id":"course-114191-29","type":"list","items":["5. Для счёта с акцией сначала проверь её условия и назови гостю доступные способы оплаты. При сомнении обратись к менеджеру.","6. После уточнения способа оплаты позови менеджера. Он проведёт оплату и закроет стол. 🧑‍💼"],"ordered":false},{"id":"course-114191-30","text":"7. Накопительная система и скидки 🏷️✨","type":"heading","level":2},{"id":"course-114191-31","html":"<p>Проверь действующую программу лояльности своей точки и данные гостя в iiko, если условия зависят от его уровня. Назови подтверждённые условия начисления или списания. При сомнении уточни у менеджера.</p><p>Начисляй и списывай бонусы только в пределах своих полномочий. Если оформление требует согласования, передай данные менеджеру.</p>","type":"text"},{"id":"course-114191-32","text":"8. Возврат или удаление после оплаты ↩️❌","type":"heading","level":2},{"id":"course-114191-33","text":"Если ошибка обнаружилась уже после оплаты:","type":"heading","level":3},{"id":"course-114191-34","type":"list","items":["Не делай ничего самостоятельно. 🛑","Позови наставника или менеджера. 🆘","Они проведут операцию возврата или сторнирования. 🔄"],"ordered":false},{"id":"course-114191-35","text":"9. Закрытие стола 🔓","type":"heading","level":2},{"id":"course-114191-36","html":"<p>Закрытие стола выполняет менеджер. После того как менеджер завершит расчёт и гость уйдёт, стол на схеме зала освободится. Твоя задача — подготовить стол к следующей посадке (убрать, пересервировать).</p>","type":"text"},{"id":"course-114191-37","text":"❗️ Важно запомнить 🧠","type":"heading","level":2},{"id":"course-114191-38","html":"<p>Пречек — предварительный счёт для проверки гостем перед оплатой. Заказ на кухню и бар отправляется кнопкой «Печать».</p><p>Гостевой чек 🧾 — фискальный чек для гостя. 👤</p><p>Удалить блюдо после печати 🗑️ — только с разрешения наставника (и с причиной). 🆘</p><p>Скидки 🏷️ — применяются строго по правилам заведения. 📜</p><p>Если не знаешь, что делать — спроси наставника. 🙋‍♂️🙋‍♀️</p>","type":"text"},{"id":"course-114191-39","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114191-40","html":"<p>Вместе создайте тренировочный заказ. 🧪</p><p>Добавь 2–3 блюда, отправь на печать. 🍔🍟🥤</p><p>Попробуй сделать дозаказ. 🔄</p><p>Ты справишься! Уже через пару дней будешь работать в iiko уверенно. 💪🚀✨</p>","type":"text"}]},{"id":"114192","title":"Смена 7. Практика в действии","blocks":[{"id":"course-114192-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-7-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 7. Практика в действии"},{"id":"course-114192-2","text":"Работа в паре с наставником — наблюдаем и помогаем 🤝","type":"heading","level":2},{"id":"course-114192-3","html":"<p>Сегодня ты выходишь в зал не как самостоятельный официант, а как ассистент наставника🤝. Твоя главная задача — наблюдать, помогать и учиться правильной физике работы. Гости пока общаются с наставником, а ты занимаешься всем остальным.</p>","type":"text"},{"id":"course-114192-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114192-5","html":"<p>Научиться правильно двигаться в зале, держать посуду, убирать со стола и сервировать. Наставник говорит — ты делаешь. И внимательно смотришь, как работает профессионал. 👀</p>","type":"text"},{"id":"course-114192-6","text":"Теория: физика сервиса — то, чему не учат в учебниках 📚","type":"heading","level":2},{"id":"course-114192-7","text":"1. Как правильно держать тарелку 🍽️","type":"heading","level":3},{"id":"course-114192-8","html":"<p>Главное правило: большой палец всегда лежит на бортике, НЕ на поверхности тарелки, куда кладется еда!</p>","type":"text"},{"id":"course-114192-9","text":"Правильный хват:","type":"heading","level":3},{"id":"course-114192-10","type":"list","items":["Тарелка лежит на раскрытой ладони левой руки.","Большой палец — сверху, на краю тарелки (бортике).","Остальные пальцы поддерживают снизу.","Если тарелка горячая — используй салфетку или специальное полотенце."],"ordered":false},{"id":"course-114192-11","text":"Как НЕЛЬЗЯ:","type":"heading","level":3},{"id":"course-114192-12","type":"list","items":["❌ Касаться пальцами еды.","❌ Держать тарелку, как книгу, прижимая к себе.","❌ Класть большой палец на край, где будет лежать еда."],"ordered":false},{"id":"course-114192-13","text":"2. Как правильно брать и переносить бокал 🥂","type":"heading","level":3},{"id":"course-114192-14","html":"<p>Правило: только за ножку!</p><p>Почему?</p><p>Если берешь бокал за чашу — оставляешь отпечатки пальцев (гость это видит, это некрасиво). 🤢</p><p>Тепло твоих рук нагревает напиток (особенно важно для белого вина, шампанского, пива).</p><p>Эстетика: официант, берущий бокал за ножку, выглядит профессионально.</p>","type":"text"},{"id":"course-114192-15","text":"Как переносить несколько бокалов:","type":"heading","level":3},{"id":"course-114192-16","type":"list","items":["Один в руке — за ножку.","Остальные можно нести в другой руке, держа их за донышки (основания), аккуратно, чтобы они не касались друг друга и не звенели."],"ordered":false},{"id":"course-114192-17","text":"3. С какой стороны подходить к столу 🚶‍♀️🚶‍♂️","type":"heading","level":3},{"id":"course-114192-18","text":"Международный стандарт (и стандарт большинства ресторанов):","type":"heading","level":3},{"id":"course-114192-19","text":"4. Как убирать посуду со стола 🧹","type":"heading","level":3},{"id":"course-114192-20","html":"<p>Никогда не складывай грязные тарелки в чистые на глазах у гостя! ❌ Это выглядит ужасно и антисанитарно.</p>","type":"text"},{"id":"course-114192-21","text":"Правильный алгоритм:","type":"heading","level":3},{"id":"course-114192-22","type":"list","items":["Подходишь к столу.","Сначала забираешь самые большие тарелки (они внизу стопки).","Меньшие ставишь сверху.","Остатки еды аккуратно сгребаешь в одну тарелку (лучше делать это уже на кухне или подсобке, а не у стола).","3. Грязные приборы кладешь сверху на тарелку, чтобы они не упали.","4. Бокалы убираешь отдельно, не ставишь их в стопку с тарелками."],"ordered":false},{"id":"course-114192-23","src":"assets/extra-courses/waiter-internship-7-1.jpg","type":"image","caption":""},{"id":"course-114192-24","src":"assets/extra-courses/waiter-internship-7-2.jpg","type":"image","caption":""},{"id":"course-114192-25","src":"assets/extra-courses/waiter-internship-7-3.jpg","type":"image","caption":""},{"id":"course-114192-26","text":"5. Как заменить тарелку 🔄","type":"heading","level":2},{"id":"course-114192-27","text":"Если гость ест блюдо, которое подается в несколько перемен, или просит чистую тарелку:","type":"heading","level":3},{"id":"course-114192-28","type":"list","items":["Приносишь чистую тарелку (правой рукой, справа).","Забираешь грязную (правой рукой, справа).","Делаешь это одним плавным движением: поставил чистую — забрал грязную.","Если меняешь приборы — сначала убери грязные, потом положи чистые."],"ordered":false},{"id":"course-114192-29","text":"Работа в iiko: тренировочные заказы 📱💻","type":"heading","level":2},{"id":"course-114192-30","html":"<p>В свободные минуты (когда нет задачи от наставника) бери планшет и тренируйся. Наставник покажет, где включить тестовый режим, или ты можешь просто создавать учебные заказы, не отправляя их на кухню.</p><p>Задание: 10 тренировочных заказов</p>","type":"text"},{"id":"course-114192-31","text":"Поставь себе цель за смену создать минимум 5-10 учебных заказов. Вот сценарии для тренировки:","type":"heading","level":3},{"id":"course-114192-32","text":"Что проверять в каждом заказе:","type":"heading","level":3},{"id":"course-114192-33","type":"list","items":["Правильно ли выбран стол? 🪑","Введено ли количество гостей? 👥","Все ли модификаторы выбраны (особенно обязательные)? ⚠️","Нет ли опечаток в комментариях? 📝","Если ошибся — не страшно!","Удаляй заказ и начинай заново. Это тренировка, здесь можно и нужно ошибаться. Главное — чтобы пальцы запомнили, где какие кнопки."],"ordered":false},{"id":"course-114192-35","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114192-36","html":"<p>Сегодня ты работаешь в режиме «тень наставника».</p><p>Задание 1. Наблюдение 🔍</p>","type":"text"},{"id":"course-114192-37","text":"Весь вечер ходи за наставником и смотри:","type":"heading","level":3},{"id":"course-114192-38","type":"list","items":["Как он подходит к гостям.","Как принимает заказ (какие вопросы задает, что рекомендует).","Как держит тарелки и бокалы.","С какой стороны подает и убирает.","Задание 2. Помощник 💪"],"ordered":false},{"id":"course-114192-39","text":"Наставник говорит — ты делаешь:","type":"heading","level":3},{"id":"course-114192-40","type":"list","items":["Поднести воду, хлеб или согласованный приветственный комплимент по стандарту точки.","Подать готовые блюда (наставник говорит, кому и что нести).","Убрать пустую посуду (наставник показывает, что уже можно убирать).","Долить воду (следи за бокалами).","Принести салфетки / дополнительный прибор / соус, если просит гость или наставник.","Задание 3. Чистота стола 🧼"],"ordered":false},{"id":"course-114192-41","text":"Твоя главная зона ответственности сегодня:","type":"heading","level":3},{"id":"course-114192-42","type":"list","items":["Стол должен выглядеть опрятно всегда.","Убирай сразу, как только видишь пустую тарелку (не жди, пока накопится гора).","Салфетки — если закончились или испачкались, замени.","Крошки — если видишь, аккуратно убери (специальной щеткой или чистой салфеткой)."],"ordered":false},{"id":"course-114192-43","text":"Чек-лист: чему ты научился сегодня ✅","type":"heading","level":2},{"id":"course-114192-44","html":"<p>Я знаю, как правильно держать тарелку (пальцы только на бортике) 🍽️</p><p>Я знаю, как правильно брать бокал (только за ножку) 🥂</p><p>Я запомнил, с какой стороны подавать и убирать (в основном справа) 👉</p><p>Я умею убирать посуду, не складывая грязное в чистое 🧹</p><p>Я помогал наставнику и не мешался под ногами 🤝</p><p>Я следил за чистотой столов и вовремя реагировал 🧼</p>","type":"text"},{"id":"course-114192-45","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114192-46","html":"<p>...гость обратился к тебе напрямую с вопросом?</p><p>Вежливо улыбнись и скажи: «Сейчас позову [Имя наставника], он вам подробно ответит». Не пытайся отвечать, если не уверен в информации.</p><p>...ты что-то уронил или пролил?</p><p>Не паникуй.</p><p>Сразу убери (позови уборщицу, если нужна помощь).</p><p>Если пострадала одежда гостя или скатерть — срочно зови менеджера.</p><p>...ты не знаешь, куда нести блюдо?</p><p>Никогда не ставь блюдо наугад.</p><p>Спроси наставника: «Это на какой стол?» или «Кому это?».</p><p>...у тебя нет задачи от наставника?</p><p>Не стой столбом! Возьми планшет и тренируйся создавать заказы. Или спроси наставника: «Чем я могу помочь?»</p>","type":"text"},{"id":"course-114192-47","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114192-48","html":"<p>Сегодня ты учишься не говорить, а делать. Физика сервиса — это база, без которой невозможно стать хорошим официантом. Смотри, запоминай, помогай. И не стесняйся задавать наставнику вопросы: «А почему ты так сделал?», «А почему с этой стороны?», «А почему ты так поставил бокал?».</p><p>А в свободные минуты — тренируйся в iiko. Чем быстрее твои пальцы запомнят расположение кнопок, тем легче тебе будет, когда ты начнешь работать самостоятельно.</p><p>Лучший способ научиться — быть полезным и внимательным. 👌</p><p>Ты молодец! Уже завтра эти движения станут для тебя привычными. 😊</p><p>Следующая смена — работа с отзывами и жалобами. Отдыхай и набирайся сил!</p>","type":"text"},{"id":"merged--9","type":"heading","text":"Сценарии для тренировочных заказов","level":2},{"id":"merged--10","type":"text","html":"<p>По разрешению наставника создай учебные заказы: один гость; пара; компания из четырёх; блюдо с модификатором; два одинаковых блюда с разными пожеланиями; дозаказ; исправление до печати; разделение счёта; расчёт с действующей акцией; заказ с программой лояльности.</p><p>Бери позиции и цены из меню своей точки. Условия скидок и бонусов проверь у менеджера. Учебный заказ не должен попасть в реальное производство: работай в согласованном учебном режиме.</p>"}]},{"id":"114193","title":"Смена 8. Всё под контролем","blocks":[{"id":"course-114193-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-8-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 8. Всё под контролем"},{"id":"course-114193-2","text":"Первая самостоятельная работа и новые навыки 🚀","type":"heading","level":2},{"id":"course-114193-3","html":"<p>Поздравляю! Ты переходишь на новый уровень — сегодня ты будешь самостоятельно обслуживать 2–3 стола. Наставник рядом, он контролирует и помогает, но основную работу делаешь ты. Это твой первый шаг к статусу полноценного официанта! 💪</p>","type":"text"},{"id":"course-114193-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114193-5","html":"<p>Взять ответственность за 2–3 стола (под контролем наставника)</p><p>Научиться контролировать время ожидания блюд</p><p>Освоить организацию поздравлений (подача торта со свечой)</p><p>Получить от наставника обратную связь по зонам роста</p>","type":"text"},{"id":"course-114193-6","text":"Самостоятельная работа с 2–3 столами 🪑✨","type":"heading","level":2},{"id":"course-114193-7","html":"<p>Сегодня ты не просто помогаешь, а ведёшь свои столы. Наставник вмешивается только если нужно подстраховать или если гость задает сложный вопрос.</p><p>Что значит \"вести столы\"?</p>","type":"text"},{"id":"course-114193-8","text":"Правила работы сегодня:","type":"heading","level":3},{"id":"course-114193-9","type":"list","items":["Ты главный за своими столами. Наставник — твоя тень и страховка.","Если сомневаешься — спроси шепотом, чтобы гость не слышал.","Если гость задает вопрос, на который не знаешь ответа: «Одну минуту, я уточню» — и идешь к наставнику.","Не беги, не суетись. Гости чувствуют нервозность. Действуй спокойно и уверенно."],"ordered":false},{"id":"course-114193-10","rows":[["Встретить гостей, принять заказ и внести его в iiko","Стажёр, наставник рядом"],["Отправить согласованный заказ, подать блюда и следить за столом","Стажёр"],["Предложить десерт или принести счёт","Стажёр"],["Проверить условия акции, способ оплаты и доступные бонусы","Стажёр уточняет, менеджер помогает при необходимости"],["Оформить скидку, списание и закрыть стол","В пределах полномочий по порядку точки"],["Решить нестандартную ситуацию","Стажёр приглашает наставника или менеджера"]],"type":"table","headers":["Действие","Кто отвечает"]},{"id":"course-114193-11","text":"Контроль времени ожидания ⏱️","type":"heading","level":2},{"id":"course-114193-12","html":"<p>Одна из главных задач официанта — управлять ожиданием гостя. Гость не знает, сколько готовится блюдо, и ему кажется, что \"уже полчаса\", даже если прошло 10 минут.</p>","type":"text"},{"id":"course-114193-13","text":"Что нужно делать:","type":"heading","level":3},{"id":"course-114193-14","text":"1. Предупреждать заранее","type":"heading","level":3},{"id":"course-114193-15","text":"Когда гость заказывает блюдо с долгим приготовлением (горячее 20–40 минут), сразу говори:","type":"heading","level":3},{"id":"course-114193-16","type":"list","items":["«Стейк будет готов примерно 25–30 минут. Хорошо?»","Гость предупрежден — значит, не дергает тебя каждые 5 минут."],"ordered":false},{"id":"course-114193-17","text":"2. Отслеживать время в iiko","type":"heading","level":3},{"id":"course-114193-18","html":"<p>В системе видно, когда блюдо отправили на кухню.</p><p>Если время приготовления вышло, а блюда нет — подойди к раздаче и вежливо спроси: «Когда примерно будет готово?»</p><p>Если задержка большая — подойди к гостю, скажи: «Блюдо готовится чуть дольше, спасибо за терпение».</p>","type":"text"},{"id":"course-114193-19","text":"3. Знать нормативы (повторяем из Смены 5)","type":"heading","level":3},{"id":"course-114193-20","text":"4. Что делать, если гость жалуется на ожидание","type":"heading","level":3},{"id":"course-114193-21","html":"<p>Если кухня заранее сообщает, что блюдо будет готовиться дольше обычного, назови актуальный ориентир до подтверждения заказа. Уточни, удобно ли гостю ждать.</p><p>Если обещанное время прошло, уточни срок на раздаче, предупреди гостя и скажи, когда вернёшься с обновлением.</p><p>При существенной задержке предложи подходящее решение и подключи наставника или менеджера. Комплимент согласуй до того, как предложишь его гостю.</p>","type":"text"},{"id":"course-114193-23","text":"Подача торта / поздравление 🎂🎉","type":"heading","level":2},{"id":"course-114193-24","html":"<p>У нас принято поздравлять именинников. Это важная часть сервиса, которая запоминается гостям.</p>","type":"text"},{"id":"course-114193-25","text":"Алгоритм действий:","type":"heading","level":3},{"id":"course-114193-26","type":"list","items":["Шаг 1. Узнать о поводе","Уточни, кого поздравляем, какое время удобно гостям и какой формат возможен в заведении.","Шаг 2. Согласовать подготовку с наставником или менеджером"],"ordered":false},{"id":"course-114193-27","text":"Ты не делаешь это в одиночку. Тебе нужно:","type":"heading","level":3},{"id":"course-114193-28","type":"list","items":["Согласуй формат, время и ответственного за подготовку с наставником или менеджером.","Если в поздравлении участвует ведущий, передай ему имя именинника и согласованное время.","Собрать коллег — 2–3 официанта, которые подойдут с тобой поздравлять","Шаг 3. Подготовить десерт","Проверь, предусмотрен ли комплимент и какой десерт согласован.","Если менеджер согласовал комплимент, до подачи уточни, как оформить его в iiko по правилам точки и кто отвечает за оформление и подачу.","Шаг 4. Организовать момент","Подай согласованный десерт. Свеча и участие команды зависят от формата поздравления.","Подойдите с коллегами в согласованный момент.","Улыбаемся, поздравляем, поем (хотя бы пару строк)","Если подаёте десерт со свечой, дай имениннику её задуть."],"ordered":false},{"id":"course-114193-29","text":"Важно!","tone":"yellow","type":"callout","title":""},{"id":"course-114193-30","html":"<p>Свеча зажигается перед выходом к гостю (не за 5 минут!)</p><p>Если гость принес свой торт — уточни, нужно ли его нарезать и подавать</p>","type":"text"},{"id":"course-114193-31","text":"Обратная связь от наставника: зоны роста 📝","type":"heading","level":2},{"id":"course-114193-32","html":"<p>В конце смены наставник даст тебе обратную связь. Это не критика, а помощь стать лучше.</p>","type":"text"},{"id":"course-114193-33","text":"Как принимать обратную связь:","type":"heading","level":3},{"id":"course-114193-34","type":"list","items":["Слушай внимательно, не перебивай","Не оправдывайся","Записывай (мысленно или в заметки), что нужно улучшить"],"ordered":false},{"id":"course-114193-35","text":"Что может сказать наставник (примеры):","type":"heading","level":3},{"id":"course-114193-36","text":"Твоя задача:","type":"heading","level":3},{"id":"course-114193-37","type":"list","items":["Спроси у наставника в конце смены: «Что мне нужно улучшить? На что обратить внимание?»","И запиши это. В следующих сменах будешь работать над этими моментами."],"ordered":false},{"id":"course-114193-38","src":"assets/extra-courses/waiter-internship-8-3.jpg","type":"image","caption":""},{"id":"course-114193-39","text":"Чек-лист: что ты сегодня попробовал ✅","type":"heading","level":2},{"id":"course-114193-40","html":"<p>Я сам встретил и усадил гостей 🪑</p><p>Я принял заказ без помощи наставника 📝</p><p>Я следил за временем приготовления и предупреждал гостей ⏱️</p><p>Я вовремя убирал посуду 🧹</p><p>Я предложил десерт и помог с выбором 🍰</p><p>Я участвовал в организации поздравления 🎂</p><p>Я получил обратную связь от наставника и запомнил зоны роста 📝</p>","type":"text"},{"id":"course-114193-41","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114193-42","html":"<p>...гость просит что-то, чего нет в меню?</p><p>Вежливо скажи: «К сожалению, этого нет, но могу порекомендовать...»</p><p>...ты ошибся в заказе?</p><p>Если блюдо еще не ушло на кухню — исправь в iiko. Если уже готовится — позови наставника.</p><p>...гость зовет тебя, а ты с другим заказом?</p><p>Скажи: «Одну минуту, я сейчас вернусь» — и подойди, как только освободишься. Если срочно — попроси помощи у коллеги.</p>","type":"text"},{"id":"course-114193-43","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114193-44","html":"<p>Сегодня ты доказываешь, что готов к самостоятельной работе. Не бойся ошибаться — наставник рядом. Но старайся делать всё сам. Именно так приходит уверенность.</p><p>И помни: гость не знает, что ты стажер. Для него ты — лицо ресторана. Действуй соответственно. 😊👌</p><p>Ты справишься! Уже через пару смен ты будешь работать наравне со всеми. 💪</p>","type":"text"},{"id":"merged--11","type":"text","html":"<p>Ориентиры приготовления изучены в смене 5. В каждой реальной смене время зависит от блюда, очереди и загрузки кухни. Перед обещанием гостю уточни актуальное время на раздаче.</p>"}]},{"id":"114194","title":"Смена 9. Вайб, кэш и харизма","blocks":[{"id":"course-114194-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-9-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 9. Вайб, кэш и харизма"},{"id":"course-114194-2","text":"Работа с отзывами, правила расчетов, конфликты и контроль остатков 🌟","type":"heading","level":2},{"id":"course-114194-3","html":"<p>Сегодня насыщенный день! Ты научишься работать с обратной связью от гостей, узнаешь важные правила расчетов со скидками, освоишь алгоритм действий при конфликтах и будешь контролировать остатки на своей станции. Поехали! 🚀</p>","type":"text"},{"id":"course-114194-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114194-5","html":"<p>Научиться приглашать гостя оставить честный отзыв и показывать ссылку своей точки</p><p>Освоить пошаговый алгоритм работы с конфликтами</p><p>Научиться проверять действующие условия акции, бонусов и оплаты</p><p>Научиться контролировать остатки текстиля и расходников на станции</p>","type":"text"},{"id":"course-114194-6","text":"Как предложить гостю оставить отзыв","type":"heading","level":2},{"id":"course-114194-7","html":"<p>Уточни у наставника, где брать актуальный QR-код или ссылку на карточку именно своего заведения. Проверь название и адрес точки.</p>","type":"text"},{"id":"course-114194-12","type":"list","items":["Выбери спокойный момент в разговоре. «Если захотите поделиться впечатлениями о визите, вот ссылка».","Покажи QR-код или отправь ссылку, если гость попросил. Он может оставить отзыв позже, со своего устройства."],"ordered":true},{"id":"course-114194-18","text":"Важно!","tone":"yellow","type":"callout","title":""},{"id":"course-114194-19","html":"<p>Оставить отзыв или отказаться — выбор гостя. Не проси ставить конкретную оценку или показывать публикацию. Не обещай коктейль, скидку или подарок за отзыв.</p><p>Если гость недоволен, выслушай его и помоги решить вопрос. При необходимости подключи наставника или менеджера.</p>","type":"text"},{"id":"course-114194-20","text":"Поведение при жалобах 🆘","type":"heading","level":2},{"id":"course-114194-21","html":"<p>Главное правило: ТЫ НЕ РЕШАЕШЬ ПРОБЛЕМУ В ОДИНОЧКУ!</p><p>Чего делать НЕЛЬЗЯ ❌</p><p>Забирать блюдо со словами «ой, извините» и уносить</p><p>Спорить с гостем</p><p>Обещать скидку или комплимент без согласования</p><p>Игнорировать жалобу</p><p>Что делать НУЖНО ✅</p><p>Почему это важно?</p><p>Если ты сам унесешь блюдо, повара не узнают об ошибке</p><p>Ты можешь пообещать то, что не положено (и ресторан потеряет деньги)</p><p>Менеджер лучше знает, что предложить: замену, комплимент или скидку</p>","type":"text"},{"id":"course-114194-23","text":"Алгоритм работы с конфликтами – идём глубже 🛠️","type":"heading","level":2},{"id":"course-114194-24","html":"<p>Конфликты неизбежны в работе с людьми. Главное — не бояться, а действовать грамотно. Хорошо обработанная жалоба может превратить недовольного гостя в постоянного.</p><p>Почему важно уметь работать с конфликтами?</p><p>Гость запомнит не саму проблему, а то, как ты её решил.</p><p>Профессиональная работа с жалобой помогает восстановить доверие гостя.</p><p>Твоя спокойная реакция снижает напряжение и предотвращает эскалацию.</p><p>Пошаговый алгоритм действий при конфликте</p><p>Техника активного слушания 👂</p>","type":"text"},{"id":"course-114194-25","text":"Чтобы гость почувствовал, что его слышат, используй:","type":"heading","level":3},{"id":"course-114194-26","type":"list","items":["Перефразирование – повтори суть жалобы своими словами, чтобы убедиться, что ты правильно понял.","«Если я правильно понял, вы заказывали коктейль \"Мальчик хочет в Таиланд\", но он показался вам слишком сладким?»","Уточняющие вопросы – помоги гостю конкретизировать претензию.","«Что именно вам не понравилось во вкусе? Может быть, не хватает кислинки или слишком крепко?»","Эмпатия – покажи, что ты понимаешь чувства гостя.","«Я понимаю, когда ожидания от коктейля не совпадают с реальностью, это обидно. Сейчас приглашу менеджера, и мы подберём вариант, который вам точно понравится»","Чего делать НЕЛЬЗЯ ❌","Перебивать и спорить.","Говорить «Это не моя вина», «Я тут ни при чём».","Обещать то, что не можешь выполнить (скидку, комплимент без менеджера).","Игнорировать проблему, надеясь, что «само рассосётся».","Убирать блюдо со словами «ой, извините» без выяснения причины.","Примеры фраз для разных ситуаций","Когда звать менеджера?","Гость угрожает или переходит на личности.","Проблема касается денег (скидка, возврат, пересчёт).","Ты не уверен в своих действиях.","Гость просит позвать «главного»."],"ordered":false},{"id":"course-114194-27","src":"assets/extra-courses/waiter-internship-9-2.jpg","type":"image","caption":""},{"id":"course-114194-28","rows":[["Коктейль не подошёл по вкусу","«Спасибо, что сказали. Могу уточнить, какой вкус вы предпочитаете, и подобрать другой вариант»."],["Напитки задерживаются","«Прошу прощения за ожидание. Уточню время на баре и вернусь с ответом»."],["Гость считает блюдо пересоленным","«Мне жаль, что блюдо вам не подошло. Приглашу менеджера, чтобы мы могли решить вопрос»."],["Гость заметил ошибку в счёте","«Извините за путаницу. Я проверю счёт и уточню решение у менеджера»."],["Гость недоволен обслуживанием","«Мне жаль, что так вышло. Позвольте пригласить менеджера и разобраться»."]],"type":"table","headers":["Ситуация","Что сказать"]},{"id":"course-114194-29","text":"Акции, расчёт и программа лояльности","type":"heading","level":2},{"id":"course-114194-30","html":"<p>Проверь действующую программу лояльности своей точки и данные гостя в iiko, если условия зависят от его уровня. Назови подтверждённые условия начисления или списания. При сомнении уточни у менеджера.</p>","type":"text"},{"id":"course-114194-33","text":"Как проверить бонусы при расчёте","type":"heading","level":2},{"id":"course-114194-34","text":"1. Если в точке действует программа лояльности, уточни, пользуется ли гость ей.","type":"heading","level":3},{"id":"course-114194-35","type":"list","items":["2. Если гость хочет воспользоваться программой, найди карту или профиль по правилам точки.","3. Сверь в iiko или у менеджера уровень гостя, баланс, условия начисления и доступную сумму списания.","4. Уточни у гостя, хочет ли он списать бонусы и в каком размере в пределах доступной суммы."],"ordered":false},{"id":"course-114194-36","html":"<p>5. Оформи списание по правилам точки в пределах своих полномочий или передай информацию менеджеру.</p>","type":"text"},{"id":"course-114194-37","type":"list","items":["6. Если гость интересуется оформлением, расскажи только о подтверждённых преимуществах действующей программы."],"ordered":false},{"id":"course-114194-39","text":"Проверь условия конкретной акции и назови гостю доступные способы оплаты до расчёта. Если условие непонятно, уточни его у менеджера.","tone":"yellow","type":"callout","title":"Способ оплаты по акции"},{"id":"course-114194-40","html":"<p>Если гость хочет оплатить картой, сначала уточни, действует ли при этом выбранная акция. Объясни подтверждённые условия и, при необходимости, предложи согласованную альтернативу.</p>","type":"text"},{"id":"course-114194-41","text":"Кто работает со скидками и баллами?","type":"heading","level":2},{"id":"course-114194-42","html":"<p>Кто оформляет скидку, начисляет или списывает бонусы, зависит от полномочий на точке. Если операция требует согласования, передай менеджеру данные гостя и условия акции.</p>","type":"text"},{"id":"course-114194-43","text":"Учет остатков на станции официанта 🧼📦","type":"heading","level":2},{"id":"course-114194-44","html":"<p>В конце смены ты должен проверить, всего ли хватит на завтра.</p>","type":"text"},{"id":"course-114194-45","text":"Чек-лист проверки:","type":"heading","level":3},{"id":"course-114194-46","type":"list","items":["Текстиль 🧺","Хватит ли чистых салфеток на завтрашнюю смену?","Хватит ли скатертей (если используем)?","Если нет — дать задание уборщице (или передать сменщику), что нужно постирать","Официанты сами гладят текстиль? Уточни у наставника!","Расходники 📦","Соль, перец — мельницы полные","Салфетки бумажные — достаточно на станции","Салфетки влажные — есть запас (особенно для блюд, которые едят руками)","Зубочистки — есть","Палочки для роллов — если в меню есть азиатские позиции"],"ordered":false},{"id":"course-114194-47","text":"Если чего-то не хватает:","type":"heading","level":3},{"id":"course-114194-48","type":"list","items":["Доложи наставнику","Пополни запасы (или попроси уборщицу / сменщика подготовить)"],"ordered":false},{"id":"course-114194-49","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114194-50","text":"Задание 1. Работа с отзывами","type":"heading","level":2},{"id":"course-114194-51","html":"<p>Проверь с наставником QR-код своей точки. Отработайте нейтральную фразу, затем используй её в подходящий момент, оставляя гостю выбор.</p>","type":"text"},{"id":"course-114194-52","text":"Задание 2. Отработка конфликта","type":"heading","level":2},{"id":"course-114194-53","html":"<p>Наставник разыгрывает ситуацию: гость недоволен блюдом. Твоя задача — пройти по алгоритму (выслушать → поблагодарить → извиниться → позвать менеджера). После этого наставник даёт обратную связь.</p>","type":"text"},{"id":"course-114194-54","text":"Задание 4. Проверка станции","type":"heading","level":2},{"id":"course-114194-55","html":"<p>В конце смены вместе с наставником проверь все по чек-листу. Если чего-то не хватает — пополни.</p>","type":"text"},{"id":"course-114194-56","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114194-57","html":"<p>Я знаю, где найти действующий QR-код или ссылку своей точки.</p><p>Я умею нейтрально пригласить гостя поделиться впечатлениями.</p><p>Я знаю алгоритм работы с жалобой: выслушать, поблагодарить, извиниться и при необходимости позвать менеджера.</p><p>Я умею проверять актуальные условия бонусов и способы оплаты по конкретной акции.</p><p>Я проверил остатки текстиля и расходников в конце смены.</p>","type":"text"},{"id":"course-114194-58","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114194-59","text":"...гость хочет написать отзыв, но у него нет телефона под рукой?","type":"heading","level":2},{"id":"course-114194-60","html":"<p>Предложи визитку с QR-кодом или ссылку, чтобы гость мог оставить отзыв позже со своего устройства.</p>","type":"text"},{"id":"course-114194-61","text":"...гость пишет негативный отзыв прямо при тебе?","type":"heading","level":2},{"id":"course-114194-62","html":"<p>Не спорь. Скажи: «Спасибо за честность, мы обязательно учтем». И передай наставнику.</p>","type":"text"},{"id":"course-114194-63","text":"...ты забыл проверить салфетницы, а утром у коллег не оказалось салфеток?","type":"heading","level":2},{"id":"course-114194-64","html":"<p>Это плохо. Постарайся не забывать. Если забыл — предупреди сменщика, чтобы он проверил сам.</p>","type":"text"},{"id":"course-114194-65","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114194-66","html":"<p>Сегодня ты учишься работать с людьми — и с довольными, и с недовольными. Это важнейший навык. Будь вежлив, внимателен и не бойся звать старших, если ситуация сложная.</p><p>И помни: отзывы — это не про \"галочку\", а про то, как стать лучше. Даже негатив — это подарок, если правильно его использовать. 😊</p><p>Ты справишься! Уже завтра ты будешь чувствовать себя еще увереннее. 💪</p><p>Следующая смена — плотная загрузка и работа в пик. Готовься! 🔥</p>","type":"text"}]},{"id":"114195","title":"Смена 10. Режим штурма","blocks":[{"id":"course-114195-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-10-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 10. Режим штурма"},{"id":"course-114195-2","text":"Плотная загрузка — работаем в команде с наставником 🔥","type":"heading","level":2},{"id":"course-114195-3","html":"<p>Сегодня ты выходишь на новый уровень! Твоя задача — работать в связке с наставником, но уже с гораздо большей ответственностью. Наставник теперь только общается с гостями и принимает заказы, а всё остальное делаешь ты. Поехали! 🚀</p>","type":"text"},{"id":"course-114195-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114195-5","html":"<p>Работать в паре с наставником: он говорит — ты делаешь</p><p>Обслуживать 3–5 столов в режиме «помощник на полную»</p><p>Понять, что такое пиковые часы и как в них работать</p><p>Подготовиться к мини-квизу по винам и алкоголю</p>","type":"text"},{"id":"course-114195-6","text":"Новая роль: почти полноценный официант 💪","type":"heading","level":2},{"id":"course-114195-7","text":"Сегодня схема работы меняется:","type":"heading","level":3},{"id":"course-114195-8","type":"list","items":["Наставник: Общается с гостями, принимает заказы, решает сложные вопросы","Ты: Всё остальное: встречаешь, подаешь, убираешь, доливаешь, носишь, следишь за столом"],"ordered":false},{"id":"course-114195-9","text":"Твои задачи в этой связке:","type":"heading","level":3},{"id":"course-114195-10","type":"list","items":["✅ Встретить гостей (улыбка, приветствие)","✅ Помочь с меню (если нужно)","✅ Подать воду/аперитив","✅ Подавать все блюда (по мере готовности)","✅ Убирать пустую посуду","✅ Следить за чистотой стола","✅ Доливать напитки","✅ Приносить дополнительное (соусы, салфетки, приборы)","✅ Финалить стол перед расчетом"],"ordered":false},{"id":"course-114195-11","text":"Чего ты НЕ делаешь (пока):","type":"heading","level":3},{"id":"course-114195-12","type":"list","items":["❌ Не принимаешь заказ (это делает наставник)","❌ Не решаешь конфликты (зовешь наставника)","❌ Не работаешь со скидками и особыми пожеланиями без наставника"],"ordered":false},{"id":"course-114195-13","text":"Пиковые часы: когда бывает тяжело, но мы справляемся ⏰","type":"heading","level":2},{"id":"course-114195-14","html":"<p>Что такое пиковые часы?</p><p>Это время, когда в баре максимальное количество гостей. Нагрузка растет, все бегают, но мы держим удар! 💪</p>","type":"text"},{"id":"course-114195-15","text":"Как подготовиться к пику","type":"heading","level":3},{"id":"course-114195-16","type":"list","items":["На брифинге уточни ожидаемую загрузку по броням и мероприятиям, а также распределение зон.","Если одновременно сели новые столы, а на раздаче ждут готовые блюда, согласуй с наставником приоритеты. Распределите задачи так, чтобы гостей заметили, а готовое ушло вовремя.","При высокой загрузке уточняй время подачи у кухни и бара."],"ordered":false},{"id":"course-114195-17","text":"Как предупредить гостя до подтверждения заказа","type":"heading","level":3},{"id":"course-114195-18","type":"list","items":["Назови актуальный ориентир, который подтвердили кухня или бар.","Если гость торопится, предложи позицию, которую смогут подать быстрее.","Если срок меняется, предупреди гостя и сообщи, когда вернёшься с обновлением."],"ordered":false},{"id":"course-114195-19","text":"Как работать в пик без стресса:","type":"heading","level":3},{"id":"course-114195-21","src":"assets/extra-courses/waiter-internship-10-2.jpg","type":"image","caption":""},{"id":"course-114195-22","text":"Шпаргалка по вину: готовимся к мини-квизу 🍷","type":"heading","level":2},{"id":"course-114195-23","html":"<p>Сегодня тебя ждёт мини-квиз по винам от наставника или менеджера. Чтобы быть готовым, изучи актуальные карточки вин своего заведения. Здесь собраны все позиции из нашей винной карты с характеристиками и гастрономическими рекомендациями.</p><p>🥂 Игристые вина / Шампанское (11 позиций)</p><p>🍾 Белые вина (9 позиций)</p><p>🍷 Красные вина (9 позиций)</p><p>🌸 Розовые вина (1 позиция)</p><p>СКАЧАЙ ШПАРГАЛКУ</p><p>Что будет в мини-квизе?</p><p>Назвать 3 белых, 3 красных, 3 игристых вина из нашей карты</p><p>Кратко описать вкус (сухое/сладкое, легкое/насыщенное)</p><p>Посоветовать, к какому блюду подойдет</p><p>💡 Совет: Если не уверен — лучше честно сказать «Я пока не очень разбираюсь, но могу позвать наставника». Это лучше, чем советовать ерунду.</p>","type":"text"},{"id":"course-114195-28","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114195-29","html":"<p>Задание 1. Работа в связке</p><p>В начале смены наставник показывает тебе 3–5 столов, за которые вы отвечаете. Он принимает заказ, ты делаешь всё остальное. Постарайся действовать так, чтобы наставнику не приходилось тебя подгонять.</p><p>Задание 2. Контроль времени</p><p>Когда наставник принимает заказ на блюдо с долгим приготовлением, слушай, как он предупреждает гостя. В следующий раз попробуй сам сказать эту фразу (с разрешения наставника).</p><p>Задание 3. Мини-квиз</p><p>В конце смены или в затишье наставник проведет мини-квиз. Постарайся ответить хотя бы на половину. Если ошибешься — не страшно, это тренировка.</p>","type":"text"},{"id":"course-114195-30","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114195-31","html":"<p>Я работал в связке «наставник говорит — я делаю» 🤝</p><p>Я обслуживал 3–5 столов практически самостоятельно 💪</p><p>Я умею уточнять ожидаемую загрузку на брифинге и распределять задачи с наставником.</p><p>Я знаю, что в пик время ожидания увеличивается 🕐</p><p>Я выучил 3 белых, 3 красных и 3 игристых вина 🍷</p><p>Я прошел мини-квиз (или готов к нему) 📝</p>","type":"text"},{"id":"course-114195-32","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114195-33","html":"<p>...ты не успеваешь?</p><p>Попроси помощи у коллег. Это нормально в пиковые часы.</p><p>...гость зовет, а ты с тарелками?</p><p>Скажи: «Одну минуту, я сейчас вернусь» — поставь тарелки и подойди. Или кивни другому официанту, чтобы он помог.</p><p>...наставник занят, а гость требует внимания?</p><p>Сделай что можешь: долить воду, убрать тарелки, принести салфетки. Если вопрос серьезный — скажи: «Я позову наставника».</p><p>...ты устал?</p><p>Пиковые часы выматывают. Держись, пей воду в подсобке, делай глубокие вдохи. Скоро смена кончится! 💪</p>","type":"text"},{"id":"course-114195-34","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114195-35","html":"<p>Сегодня ты доказываешь, что готов к большой нагрузке. Работай четко, не суетись, помогай наставнику и коллегам. Пиковые часы — это проверка на прочность. Пройди её достойно! 🔥</p><p>Ты справишься! Уже скоро ты будешь работать наравне со всеми. 💪</p><p>Следующая смена — сервировка и обслуживание банкетов. Готовься! 🎉</p>","type":"text"},{"id":"merged--12","type":"text","html":"<p>Открой актуальное <a href=\"https://askacademy.ru/#/menu?section=bar\">меню бара своего заведения</a> в академии. Состав, подачу, цену и наличие проверяй по его действующим карточкам и стоп-листу смены.</p><p>Подготовь по три белых, красных и игристых вина из доступной карты, если ассортимент категории это позволяет. Для каждого назови страну, сорт, сахар, стиль, основные вкусы и подходящее блюдо. Если категория меньше — изучи все её позиции. Основы повтори в библиотеке в материале «Вино».</p>"}]},{"id":"114197","title":"Смена 11. Выход на большую сцену","blocks":[{"id":"course-114197-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-11-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 11. Выход на большую сцену"},{"id":"course-114197-2","text":"Банкеты — готовимся к особому формату 🎉🍽️","type":"heading","level":2},{"id":"course-114197-3","html":"<p>Сегодня ты погружаешься в мир банкетного обслуживания. Это совсем другой уровень! Здесь важна не только скорость, но и четкая координация с командой, знание последовательности подач и умение работать с большим количеством гостей одновременно.</p><p>Банкет — это мини-спектакль, и у тебя в нем важная роль! 🎭</p>","type":"text"},{"id":"course-114197-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114197-5","html":"<p>Понять специфику банкетного обслуживания</p><p>Научиться сервировать стол в зависимости от предзаказа</p><p>Освоить порционную раскладку блюд</p><p>Научиться координировать поздравления с ведущим, баром и кухней</p>","type":"text"},{"id":"course-114197-6","text":"Сервировка банкетного стола 🍽️","type":"heading","level":2},{"id":"course-114197-7","html":"<p>Главное правило: сервировка зависит от предзаказа!</p><p>У банкета всегда есть предзаказ — список блюд и напитков, которые гости заказали заранее. Именно от него мы и отталкиваемся.</p>","type":"text"},{"id":"course-114197-8","text":"Что нужно узнать из предзаказа:","type":"heading","level":3},{"id":"course-114197-9","src":"assets/extra-courses/waiter-internship-11-1.jpg","type":"image","caption":""},{"id":"course-114197-10","text":"Бокалы для банкета","type":"heading","level":2},{"id":"course-114197-11","html":"<p>Подбирай бокалы под напитки из предзаказа по посуде своей точки. Полный справочник посуды находится в смене 4; перед банкетом проверь количество и запас, чистоту и отсутствие сколов.</p>","type":"text"},{"id":"course-114197-15","text":"Подготовка к банкету 📋","type":"heading","level":2},{"id":"course-114197-16","text":"За день до банкета (или в начале смены) нужно подготовить:","type":"heading","level":3},{"id":"course-114197-17","text":"1. Сменные тарелки 🍽️","type":"heading","level":3},{"id":"course-114197-18","html":"<p>Для каждого гостя должно быть минимум 2 комплекта тарелок (под закуски и под горячее)</p><p>Лучше подготовить с запасом (+2–3 комплекта)</p>","type":"text"},{"id":"course-114197-19","text":"2. Приборы 🥄🔪","type":"heading","level":3},{"id":"course-114197-20","html":"<p>Ножи, вилки, ложки — по количеству гостей + запас</p><p>Для общих блюд — ложки и вилки для раскладки (отдельно!)</p>","type":"text"},{"id":"course-114197-21","text":"3. Салфетки 🧻","type":"heading","level":3},{"id":"course-114197-22","html":"<p>Бумажные и влажные — с запасом</p><p>Текстильные салфетки для сервировки</p>","type":"text"},{"id":"course-114197-23","text":"Обслуживание банкета 🛎️","type":"heading","level":2},{"id":"course-114197-24","html":"<p>Порционная раскладка (самое важное!)</p><p>Большинство банкетных блюд подаются в общей посуде (большие тарелки, салатники, блюда). Твоя задача — разложить еду по тарелкам гостей.</p>","type":"text"},{"id":"course-114197-25","text":"Как правильно раскладывать:","type":"heading","level":3},{"id":"course-114197-26","type":"list","items":["Подходи к гостю с левой стороны (так удобнее)","Держи общее блюдо в левой руке, ложку и вилку для раскладки — в правой","Аккуратно выкладывай порцию, стараясь, чтобы она выглядела аппетитно","Если блюдо с соусом — полей соусом сверху","Уточни: «Вам добавить еще?» — если гость хочет добавки"],"ordered":false},{"id":"course-114197-27","text":"Важно!","tone":"yellow","type":"callout","title":""},{"id":"course-114197-28","html":"<p>Используй отдельные приборы для раскладки (не те, которыми едят гости!)</p><p>Не касайся еды руками</p><p>Если блюдо горячее — предупреди гостя</p><p>Последовательность подачи на банкете</p><p>Перед началом сверь согласованный предзаказ и тайминг с ответственным за банкет и кухней.</p>","type":"text"},{"id":"course-114197-29","text":"Важные правила подачи:","type":"heading","level":3},{"id":"course-114197-30","type":"list","items":["Подготовь стол и посуду по подтверждённому предзаказу.","Подавай блюда в согласованной последовательности.","Если организатор просит подать блюдо раньше, проверь готовность у кухни и согласуй изменение с ответственным за банкет. Сообщи гостю новое время после подтверждения."],"ordered":false},{"id":"course-114197-31","text":"Что делать между подачами:","type":"heading","level":3},{"id":"course-114197-32","type":"list","items":["Убирать использованную посуду","Менять приборы (если нужно)","Доливать напитки","Следить за чистотой стола","💡 Совет: Если в банкете несколько горячих блюд, они могут подаваться одновременно (все на стол) или по очереди. Уточни это у наставника или организатора банкета заранее."],"ordered":false},{"id":"course-114197-33","text":"Координация с командой 🤝","type":"heading","level":2},{"id":"course-114197-34","html":"<p>Банкет — это командная работа. Ты не один!</p>","type":"text"},{"id":"course-114197-35","text":"С кем координируемся:","type":"heading","level":3},{"id":"course-114197-36","src":"assets/extra-courses/waiter-internship-11-5.jpg","type":"image","caption":""},{"id":"course-114197-37","text":"Поздравление именинника 🎂🎉","type":"heading","level":2},{"id":"course-114197-38","html":"<p>Согласуй формат поздравления и время с организатором и менеджером. Уточни, кто готовит десерт, кто координирует подачу и нужен ли ведущий.</p>","type":"text"},{"id":"course-114197-39","text":"Алгоритм действий:","type":"heading","level":3},{"id":"course-114197-41","html":"<p>Если менеджер согласовал комплимент, до подачи уточни, как оформить его в iiko по правилам точки и кто отвечает за оформление и подачу.</p><p>Свечу и участие коллег подготовь, если они предусмотрены согласованным форматом.</p>","type":"text"},{"id":"course-114197-42","rows":[["Согласование","Уточни удобное время у организатора и формат у менеджера."],["Оформление","Если согласован комплимент, проверь порядок оформления в iiko и ответственного."],["Подготовка","Передай согласованное время кухне и ведущему, если он участвует."],["Подача","Вынеси десерт в согласованный момент вместе с командой, если это входит в формат."]],"type":"table","headers":["Шаг","Действие"]},{"id":"course-114197-43","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114197-44","html":"<p>Задание 1. Изучение предзаказа</p><p>Возьми реальный предзаказ на банкет (или учебный). Посмотри, какие напитки заказаны. Определи, какие бокалы нужно поставить.</p><p>Задание 2. Сервировка</p><p>Под руководством наставника попробуй сервировать стол под конкретный предзаказ.</p><p>Задание 3. Порционная раскладка</p><p>Если будет возможность, попробуй разложить блюдо в общей посуде по тарелкам (под присмотром).</p><p>Задание 4. Координация поздравления</p><p>Если в смене есть банкет с именинником — поучаствуй в подготовке и самом поздравлении.</p>","type":"text"},{"id":"course-114197-45","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114197-46","html":"<p>Я знаю, что сервировка банкета зависит от предзаказа 📋</p><p>Я умею подбирать бокалы под напитки (по файлу посуды) 🥂</p><p>Я знаю, какие тарелки и приборы нужны для банкета 🍽️</p><p>Я понимаю, как делать порционную раскладку 🥄</p><p>Я запомнил последовательность подачи блюд (5 этапов) 🔢</p><p>Я знаю, с кем координироваться (ведущий, бар, кухня) 🤝</p><p>Я умею организовывать поздравление именинника 🎂</p>","type":"text"},{"id":"course-114197-47","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114197-48","html":"<p>...в предзаказе нет информации о напитках?</p><p>Спроси у наставника или менеджера. Возможно, гости будут заказывать на месте.</p><p>...гостей больше, чем мы ожидали?</p><p>Срочно добавляй приборы и тарелки. Если не хватает — бери у коллег или со склада.</p><p>...кто-то из гостей просит добавки, а блюдо закончилось?</p><p>Вежливо скажи: «Сейчас уточню на кухне, возможно, есть еще». Если нет — предложи альтернативу.</p><p>...свеча погасла перед выходом?</p><p>Не паникуй. Зажги новую. Главное — улыбайся.</p>","type":"text"},{"id":"course-114197-49","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114197-50","html":"<p>Банкет — это как дирижировать оркестром. Ты должен чувствовать ритм, вовремя подавать сигналы и работать в команде. Не бойся просить помощи у коллег и координироваться с ведущим.</p><p>И помни: именинник запомнит не только торт, но и твою улыбку. 😊</p><p>Ты справишься! Банкеты — это сложно, но очень интересно. 💪</p><p>Следующая смена — контроль чистоты и заготовок, закрытие смены. Готовься! 🧹</p>","type":"text"}]},{"id":"114198","title":"Смена 12. Чисто, чётко, по стилю","blocks":[{"id":"course-114198-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-12-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 12. Чисто, чётко, по стилю"},{"id":"course-114198-2","text":"Чистота, заготовки, закрытие смены и продажа авторских коктейлей 🧹✨","type":"heading","level":2},{"id":"course-114198-3","html":"<p>Сегодня ты осваиваешь важнейшие навыки, которые отличают профессионала: поддержание чистоты в течение всей смены, правильное закрытие и продажа авторских коктейлей. Поехали! 🚀</p>","type":"text"},{"id":"course-114198-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114198-5","html":"<p>Научиться контролировать чистоту в зале в течение всей смены</p><p>Освоить работу с заготовками (расходниками)</p><p>Изучить алгоритм закрытия смены по чек-листу</p><p>Выучить авторские коктейли и научиться их продавать</p><p>Отработать нейтральное приглашение оставить отзыв.</p>","type":"text"},{"id":"course-114198-6","text":"Режим работы и тайминг ⏰","type":"heading","level":2},{"id":"course-114198-8","text":"Контроль чистоты в течение смены 🧼","type":"heading","level":2},{"id":"course-114198-9","html":"<p>Чистота — это лицо бара. Гость не простит грязный стол или липкие салфетницы.</p>","type":"text"},{"id":"course-114198-10","text":"Что нужно контролировать постоянно:","type":"heading","level":3},{"id":"course-114198-11","text":"Золотое правило:","type":"heading","level":3},{"id":"course-114198-12","type":"list","items":["Лучше убрать сразу, чем потом объяснять гостю, почему грязно."],"ordered":false},{"id":"course-114198-13","src":"assets/extra-courses/waiter-internship-12-2.jpg","type":"image","caption":""},{"id":"course-114198-14","text":"Заготовки (расходники) — твоя зона ответственности 📦","type":"heading","level":2},{"id":"course-114198-15","text":"В течение смены ты должен следить, чтобы на станции всегда было достаточно:","type":"heading","level":3},{"id":"course-114198-16","text":"Основные расходники:","type":"heading","level":3},{"id":"course-114198-17","text":"Как складывать салфетницы:","type":"heading","level":3},{"id":"course-114198-18","type":"list","items":["Мы складываем салфетницы заранее (не в момент, когда гость уже сел). Научись делать это красиво и быстро — это часть сервиса."],"ordered":false},{"id":"course-114198-19","src":"assets/extra-courses/waiter-internship-12-3.jpg","type":"image","caption":""},{"id":"course-114198-20","text":"Закрытие смены (Чек-лист) ✅","type":"heading","level":2},{"id":"course-114198-21","html":"<p>После ухода гостей выполни чек-лист закрытия своей точки. Проверь зал и станцию, подготовь расходники к следующей смене, передай результат ответственному. Смену считают закрытой после выполнения чек-листа и передачи старшему.</p>","type":"text"},{"id":"course-114198-22","text":"Чек-лист закрытия:","type":"heading","level":3},{"id":"course-114198-23","text":"Важно!","tone":"yellow","type":"callout","title":""},{"id":"course-114198-24","html":"<p>Фотоотчет — это доказательство, что зал убран идеально. Фотографируем столы, стулья, стейшены.</p><p>ОС о смене — пишем, что было хорошо, что плохо, какие проблемы возникли.</p>","type":"text"},{"id":"course-114198-25","src":"assets/extra-courses/waiter-internship-12-4.jpg","type":"image","caption":""},{"id":"course-114198-26","text":"Продажа авторских коктейлей 🍸🔥","type":"heading","level":2},{"id":"course-114198-27","html":"<p>У нас есть не только классические коктейли, но и авторские. Их нужно знать в лицо (вернее, в бокал) и уметь продавать.</p>","type":"text"},{"id":"course-114198-28","text":"Что нужно знать о каждом авторском коктейле:","type":"heading","level":3},{"id":"course-114198-29","src":"assets/extra-courses/waiter-internship-12-5.jpg","type":"image","caption":""},{"id":"course-114198-30","text":"Основные авторские коктейли из нашего меню 🍹","type":"heading","level":2},{"id":"course-114198-31","text":"Как продавать авторские коктейли:","type":"heading","level":3},{"id":"course-114198-32","type":"list","items":["Не жди, пока гость спросит. Предлагай сам!"],"ordered":false},{"id":"course-114198-33","text":"Используй \"вкусные\" описания:","type":"heading","level":3},{"id":"course-114198-34","type":"list","items":["«Попробуйте наш авторский коктейль \"Мальчик хочет в Таиланд\" — он на джине, с ананасовым соком и ликёром, очень освежающий!»","3. Если гость сомневается, предложи попробовать (если разрешено политикой бара)."],"ordered":false},{"id":"course-114198-35","text":"4. Расскажи историю — многие авторские коктейли имеют интересное название или","type":"heading","level":3},{"id":"course-114198-36","html":"<p>историю создания.</p>","type":"text"},{"id":"course-114198-37","text":"5. Обращай внимание на подачу — коктейли в больших бокалах (1 л) или необычных","type":"heading","level":3},{"id":"course-114198-38","html":"<p>формах привлекают внимание.</p>","type":"text"},{"id":"course-114198-41","text":"Работа с отзывами (продолжение) 📱💬","type":"heading","level":2},{"id":"course-114198-42","html":"<p>Уточни у наставника, какой QR-код или ссылку используют в твоей точке.</p>","type":"text"},{"id":"course-114198-45","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114198-46","html":"<p>Задание 1. Контроль чистоты</p><p>В течение смены следи за чистой своих столов. Наставник будет проверять, как ты убираешь и замечаешь ли грязь.</p><p>Задание 2. Заготовки</p><p>Проверь станцию в начале и середине смены. Доложи наставнику, если чего-то не хватает.</p><p>Задание 3. Продажа авторских коктейлей</p><p>Попробуй предложить авторский коктейль хотя бы 3 столам. Запиши, сколько раз получилось продать.</p><p>Задание 4. Закрытие смены</p><p>Вместе с наставником пройди весь чек-лист закрытия. Сделай фотоотчет.</p><p>Задание 5. Отзывы</p><p>Проверь действующий QR-код и отработай нейтральное приглашение с наставником.</p>","type":"text"},{"id":"course-114198-47","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114198-48","html":"<p>Я знаю, что контролировать чистоту нужно постоянно, а не только в конце 🧼</p><p>Я умею проверять заготовки и пополнять расходники 📦</p><p>Я уточнил порядок закрытия своей точки и кому передать результат.</p><p>Я знаю чек-лист закрытия смены и выполняю его 📋</p><p>Я умею составлять фотоотчет и писать ОС о смене 📸</p><p>Я знаю авторские коктейли и могу их рекомендовать 🍸</p><p>Я умею предложить ссылку на отзыв и оставить решение за гостем.</p>","type":"text"},{"id":"course-114198-49","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114198-50","html":"<p>...закончились салфетницы, а новых нет?</p><p>Скажи наставнику или менеджеру. Возможно, нужно сходить на склад.</p><p>...гость оставил сильное загрязнение (пролил вино)?</p><p>Убери сразу, используй спецсредства. Если нужно — позови уборщицу.</p><p>...ты устал под утро?</p><p>Держись! Осталось немного. Работа в команде помогает — поддерживай коллег.</p><p>...не знаешь, как продать авторский коктейль?</p><p>Спроси у бармена — он расскажет про каждый коктейль лучше всех!</p>","type":"text"},{"id":"course-114198-51","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114198-52","html":"<p>Чистота, заготовки и знание коктейлей — это то, что делает официанта профессионалом. Гость не видит, как ты моешь ножки стульев при закрытии, но он видит чистый стол и вовремя поданные салфетки.</p><p>И помни: авторские коктейли — это не просто напитки, это наша гордость. Продавай их с душой! ❤️</p><p>Ты справишься! Уже совсем скоро ты будешь закрывать смену как настоящий профи. 💪</p><p>Следующая смена — участок и контроль подачи на время. Готовься! ⏱️</p>","type":"text"},{"id":"merged--13","type":"text","html":"<p>Открой актуальное <a href=\"https://askacademy.ru/#/menu?section=bar\">меню бара своего заведения</a> в академии. Состав, подачу, цену и наличие проверяй по его действующим карточкам и стоп-листу смены.</p><p>Выбери авторские коктейли своей точки. Для каждого выучи ингредиенты по гостевому меню, бокал, вкус и подачу. Предлагай сочетание под запрос гостя, не придумывай историю или состав. Порядок приглашения к честному отзыву изучен в смене 9 — сегодня отработай его на практике.</p><p>Время начала и завершения работы проверь по актуальному графику своей точки. Закрытие согласуй со старшим после выполнения чек-листа.</p>"}]},{"id":"114199","title":"Смена 13. Теперь ты — наставник","blocks":[{"id":"course-114199-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-13-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 13. Теперь ты — наставник"},{"id":"course-114199-2","text":"Участок и контроль подачи на время — обслуживание топ-персонала ⏱️👔","type":"heading","level":2},{"id":"course-114199-3","html":"<p>Сегодня особенный день! Ты будешь обслуживать не обычных гостей, а топ-персонал — менеджеров, управляющих, бар-менеджеров. Это своего рода экзамен: они будут следить за твоей скоростью, точностью и качеством сервиса. А ещё ты попробуешь себя в роли наставника и узнаешь главные техники продаж. Поехали! 🚀</p>","type":"text"},{"id":"course-114199-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114199-5","html":"<p>Научиться контролировать время подачи блюд и напитков</p><p>Обслужить топ-персонал, показав всё, на что ты способен</p><p>Провести мини-инструктаж для стажёра (в роли наставника)</p><p>Освоить базовые техники продаж в ресторане/баре</p>","type":"text"},{"id":"course-114199-6","text":"Работа с топ-персоналом: почему это важно? 🤔","type":"heading","level":2},{"id":"course-114199-7","html":"<p>Сегодня твои гости — свои же коллеги, но в роли требовательных посетителей. Это отличная тренировка, потому что:</p><p>Они точно знают стандарты и заметят каждую мелочь</p><p>Они будут оценивать твою скорость и последовательность</p><p>После смены они дадут честную обратную связь</p>","type":"text"},{"id":"course-114199-8","text":"Что они будут проверять:","type":"heading","level":3},{"id":"course-114199-9","text":"Твоя задача:","type":"heading","level":3},{"id":"course-114199-10","type":"list","items":["Обслужить их так, чтобы они забыли, что они твои коллеги, и почувствовали себя настоящими гостями. Это твой шанс показать, что ты готов к самостоятельной работе! 💪"],"ordered":false},{"id":"course-114199-11","src":"assets/extra-courses/waiter-internship-13-1.jpg","type":"image","caption":""},{"id":"course-114199-12","text":"Контроль времени подачи ⏱️","type":"heading","level":2},{"id":"course-114199-13","html":"<p>Главный навык сегодня — тайминг. Ты должен четко понимать, когда что нести, чтобы гость не ждал, но и не чувствовал, что его торопят.</p>","type":"text"},{"id":"course-114199-14","text":"Идеальный тайминг обслуживания:","type":"heading","level":3},{"id":"course-114199-15","text":"Что важно:","type":"heading","level":3},{"id":"course-114199-16","type":"list","items":["Напитки должны быть на столе быстро — это первое впечатление","Не носи всё сразу — если горячее ещё не готово, не стой у раздачи, займись другими столами","Следи за временем в iiko — система показывает, когда блюдо отправлено на кухню"],"ordered":false},{"id":"course-114199-18","text":"Мини-инструктаж стажёра (в роли наставника) 🎓","type":"heading","level":2},{"id":"course-114199-19","html":"<p>Сегодня тебе предстоит побыть в роли наставника для другого стажёра (или понарошку). Это важное упражнение, потому что:</p><p>Лучший способ понять материал — объяснить его другому.</p>","type":"text"},{"id":"course-114199-20","text":"Что нужно сделать:","type":"heading","level":3},{"id":"course-114199-21","type":"list","items":["Выбери одну тему, в которой ты уже уверен (например, «Как правильно держать тарелку» или «Последовательность подачи блюд»)."],"ordered":false},{"id":"course-114199-22","text":"Объясни стажёру так, как тебе объясняли в первые дни:","type":"heading","level":3},{"id":"course-114199-23","type":"list","items":["Покажи на примере","Дай попробовать","Ответь на вопросы","3. Дай обратную связь: что получилось, что можно улучшить."],"ordered":false},{"id":"course-114199-24","text":"Темы для инструктажа (выбери одну):","type":"heading","level":3},{"id":"course-114199-25","type":"list","items":["Как правильно держать тарелку и бокал","С какой стороны подавать и убирать","Как проверить чек перед оплатой","Как предлагать авторские коктейли","Как нейтрально предложить отзыв и показать действующий QR-код своей точки"],"ordered":false},{"id":"course-114199-26","text":"Почему это полезно:","type":"heading","level":3},{"id":"course-114199-27","type":"list","items":["Ты лучше запоминаешь стандарты","Учишься доносить информацию","Развиваешь лидерские качества"],"ordered":false},{"id":"course-114199-28","text":"Техники продаж💰🗣️","type":"heading","level":2},{"id":"course-114199-29","html":"<p>Умение продавать — это то, что отличает хорошего официанта от отличного. Гости часто не знают, чего хотят, и ждут твоей подсказки.</p>","type":"text"},{"id":"course-114199-30","text":"1. Техника «Золотой треугольник» 🔺","type":"heading","level":3},{"id":"course-114199-31","html":"<p>Это база: когда гость смотрит в меню, его взгляд движется по треугольнику. Размещай самые выгодные позиции в центре внимания.</p><p>Твоя задача: если гость колеблется, предложи блюдо, которое находится в центре меню</p><p>или выделено визуально.</p>","type":"text"},{"id":"course-114199-32","text":"2. Техника «Открытые вопросы» ❓","type":"heading","level":3},{"id":"course-114199-33","text":"Вместо вопросов, на которые можно ответить «да» или «нет», задавай открытые вопросы:","type":"heading","level":3},{"id":"course-114199-34","text":"3. Техника «Аппетитное описание» 🍔🔥","type":"heading","level":3},{"id":"course-114199-35","text":"Не просто называй блюдо, а описывай его так, чтобы у гостя потекли слюнки:","type":"heading","level":3},{"id":"course-114199-36","text":"4. Техника «Дополнительные продажи» (Upsell) ⬆️","type":"heading","level":3},{"id":"course-114199-37","text":"Всегда предлагай что-то к заказу:","type":"heading","level":3},{"id":"course-114199-38","type":"list","items":["К напиткам: «К вашему вину отлично подойдёт сырное плато»","К основному блюду: «Хотите добавить фирменный соус или овощи гриль?»","После еды: «На десерт сегодня потрясающая \"Памела Андерсон\" — сезонные фрукты и ягоды»"],"ordered":false},{"id":"course-114199-39","text":"5. Техника «Ограниченное предложение» ⏳","type":"heading","level":3},{"id":"course-114199-40","text":"Люди боятся упустить возможность:","type":"heading","level":3},{"id":"course-114199-41","type":"list","items":["Если условия подтверждены: «Сегодня последний день акции на этот сет».","«Это блюдо готовится только по выходным»","«У нас осталось всего две порции этого десерта»"],"ordered":false},{"id":"course-114199-42","src":"assets/extra-courses/waiter-internship-13-3.jpg","type":"image","caption":""},{"id":"course-114199-43","src":"assets/extra-courses/waiter-internship-13-4.jpg","type":"image","caption":""},{"id":"course-114199-44","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114199-45","html":"<p>Задание 1. Обслуживание топ-персонала</p><p>К тебе за стол садятся менеджер, управляющий и бар-менеджер. Твоя задача — обслужить их по полной программе, соблюдая тайминг и последовательность.</p><p>Задание 2. Контроль времени</p><p>Засеки время от пробития заказа до подачи каждого блюда. После смены обсуди с наставником, где можно было быстрее.</p><p>Задание 3. Мини-инструктаж</p><p>Проведи для другого стажёра (или наставника в роли стажёра) мини-урок по одной из тем. Получи обратную связь.</p><p>Задание 4. Техники продаж</p><p>Попробуй применить хотя бы 3 техники продаж за смену. Запиши, что сработало, а что нет.</p>","type":"text"},{"id":"course-114199-46","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114199-47","html":"<p>Я обслуживал топ-персонал и показал высокий уровень сервиса 👔</p><p>Я контролировал время подачи и соблюдал последовательность ⏱️</p><p>Я провел мини-инструктаж для стажёра 🎓</p><p>Я использовал технику открытых вопросов ❓</p><p>Я практиковал аппетитные описания блюд 🍔</p><p>Я предлагал дополнительные позиции к заказу ⬆️</p>","type":"text"},{"id":"course-114199-48","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114199-49","html":"<p>...топ-персонал специально пытается тебя запутать?</p><p>Не паникуй. Это проверка. Внимательно слушай, переспрашивай, если нужно. Делай свою работу чётко.</p><p>...ты ошибся с временем подачи?</p><p>Если видишь, что блюдо задерживается, подойди и скажи честно: «Блюдо готовится чуть дольше, спасибо за терпение». Честность ценят больше, чем молчание.</p><p>...стажёр не понимает твоего объяснения?</p><p>Попробуй объяснить по-другому, покажи на примере. Спроси: «Что именно непонятно?».</p><p>...гость сказал «нет» на твоё предложение?</p><p>Не настаивай. Улыбнись и скажи: «Хорошо, если захотите что-то ещё — обращайтесь!»</p>","type":"text"},{"id":"course-114199-50","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114199-51","html":"<p>Сегодня ты не просто официант, а почти полноценный член команды. Топ-персонал будет оценивать тебя строго, но справедливо. Не бойся ошибок — бойся не сделать выводы.</p><p>И помни: продажи — это не про \"впарить\", а про помочь гостю выбрать то, что ему действительно понравится. Если ты искренне рекомендуешь, гость это чувствует.</p><p>Ты справишься! Уже завтра ты будешь готов к финальной аттестации. 💪</p><p>Следующая смена — максимальная загрузка и работа без помощи наставника. Готовься!</p>","type":"text"}]},{"id":"114200","title":"Смена 14. Первый сольник","blocks":[{"id":"course-114200-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-14-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 14. Первый сольник"},{"id":"course-114200-2","text":"Полная самостоятельность и максимальная загрузка","type":"heading","level":2},{"id":"course-114200-3","html":"<p>Поздравляю! Ты дошёл до финишной прямой. Сегодня ты работаешь полностью самостоятельно. Никто не подсказывает, не страхует, не направляет. Ты сам открываешь смену, сервируешь столы, встречаешь гостей, принимаешь заказы, решаешь вопросы. Это твой звёздный час! ⭐</p>","type":"text"},{"id":"course-114200-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114200-5","html":"<p>Самостоятельно открыть смену по чек-листу</p><p>Работать без помощи наставника при максимальной загрузке</p><p>Показать всё, чему научился за время стажировки</p><p>Подготовиться к финальной аттестации</p>","type":"text"},{"id":"course-114200-6","text":"Открытие смены: твой личный чек-лист 📋","type":"heading","level":2},{"id":"course-114200-7","html":"<p>Перед сменой проверь время выхода и сбора в актуальном графике своей точки. Если график и памятка расходятся или предстоит банкет, заранее уточни время у ответственного за смену.</p><p>Перед открытием пройди чек-лист своей зоны, проверь стоп-лист и изменения на смену.</p>","type":"text"},{"id":"course-114200-8","text":"Дополнительные действия при открытии:","type":"heading","level":3},{"id":"course-114200-9","type":"list","items":["Проверить наличие расходников (салфетки бумажные/влажные, соль/перец, палочки)","Убедиться, что на станции достаточно чистых тарелок и приборов","Открыть личную смену в iiko (прокатить карту или ввести PIN)"],"ordered":false},{"id":"course-114200-10","rows":[["До выхода","Время выхода и брифинга по актуальному графику."],["Подготовка","Форма, мебель, чистота столов, посуда, текстиль и расходники."],["Перед открытием","Готовность своей зоны, актуальный стоп-лист и изменения на смену."],["Брифинг","Акции, брони и распределение зон."]],"type":"table","headers":["Этап","Что проверить"]},{"id":"course-114200-11","text":"Работа в течение смены: ты сам за себя 💪","type":"heading","level":2},{"id":"course-114200-12","text":"Сегодня наставник не подходит к твоим столам. Ты сам:","type":"heading","level":3},{"id":"course-114200-13","type":"list","items":["✅ Встречаешь гостей","✅ Принимаешь заказы (используй техники продаж!)","✅ Вносишь заказы в iiko","✅ Отправляешь на кухню","✅ Следишь за временем подачи","✅ Подаёшь блюда и напитки","✅ Убираешь посуду","✅ Предлагаешь десерты и дополнительные позиции","✅ По ситуации предлагаешь гостям оставить отзыв и показываешь ссылку своей точки.","✅ Проверяешь условия акции и способ оплаты. Скидки, бонусы и закрытие стола оформляешь в пределах полномочий по правилам точки.","✅ Решаешь стандартные вопросы (если нестандартное — зовёшь менеджера, но старайся сам)"],"ordered":false},{"id":"course-114200-14","text":"Что важно помнить:","type":"heading","level":3},{"id":"course-114200-15","type":"list","items":["Контроль времени — следи за таймингом, предупреждай о задержках","Чистота столов — убирай сразу, как только гости доели","Коммуникация — улыбайся, будь вежлив, используй открытые вопросы","Стоп-лист — проверяй перед каждым заказом"],"ordered":false},{"id":"course-114200-16","text":"Максимальная загрузка: как выжить и победить 🔥","type":"heading","level":2},{"id":"course-114200-17","text":"Если одновременно много новых гостей и готовых блюд","type":"heading","level":3},{"id":"course-114200-18","text":"Распредели задачи с командой","type":"heading","level":3},{"id":"course-114200-19","type":"list","items":["Ожидаемую загрузку уточни на брифинге. В пик согласуй приоритеты так, чтобы новые гости получили внимание, а готовые блюда ушли вовремя."],"ordered":false},{"id":"course-114200-20","text":"Советы для работы в пик:","type":"heading","level":3},{"id":"course-114200-21","type":"list","items":["Не бегай — ходи быстро, но плавно. Бег создаёт панику и повышает риск ошибок.","Согласуй приоритеты с коллегами. Поприветствуйте новых гостей и распределите задачи, чтобы готовые блюда не ждали на раздаче.","Используй блокнот. Если много заказов — записывай, чтобы не забыть.","Не носи больше трёх тарелок сразу. Лучше сделать два подхода, чем всё уронить.","Помогай коллегам, даже если это не твой стол. Команда — наша сила. Но сегодня ты сам за себя, но взаимовыручка никем не отменялась.","Если не успеваешь — попроси помощи. Это нормально.","Дыши. В пике легко запаниковать. Остановись на секунду, глубокий вдох — и дальше."],"ordered":false},{"id":"course-114200-22","text":"Чек-лист самопроверки в конце смены ✅","type":"heading","level":2},{"id":"course-114200-23","html":"<p>Я открыл смену по чек-листу без напоминаний</p><p>Я обслужил свои столы от начала до конца без помощи наставника</p><p>Я контролировал время подачи и предупреждал о задержках</p><p>Я применял техники продаж (аппетитные описания, доп. продажи)</p><p>Я умею показать ссылку на отзыв своей точки и предложить оставить его без давления.</p><p>Я проверил остатки расходников перед закрытием</p><p>Я закрыл смену по чек-листу (уборка, фотоотчёт, ОС, отчёт старшему)</p>","type":"text"},{"id":"course-114200-24","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114200-25","html":"<p>...гость жалуется, а менеджера рядом нет?</p><p>Выслушай, поблагодари, предложи решение в рамках своих полномочий (позвать менеджера, уточнить на кухне). Не обещай того, в чём не уверен.</p><p>...ты ошибся в заказе, и блюдо уже готовится?</p><p>Если можешь исправить без последствий — исправь. Если нет — предупреди гостя, предложи альтернативу или комплимент (после согласования с менеджером).</p><p>...ты чувствуешь, что выгораешь к концу смены?</p><p>Держись! Ты почти у цели. Пей воду, делай микро-паузы. Помни, что после смены — заслуженный отдых.</p>","type":"text"},{"id":"course-114200-26","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114200-27","html":"<p>Сегодня ты доказываешь самому себе, что готов. Всё, чему ты учился — от правильного хвата тарелки до техник продаж — сегодня работает в полную силу. Доверяй своим знаниям, будь внимателен и профессионален.</p><p>И помни: самостоятельность — это не страшно, это свобода делать свою работу так, как ты умеешь лучше всего.</p><p>Ты справишься! Завтра — финальная аттестация. 💪</p><p>Следующая смена — решение о допуске. Ты готов!</p>","type":"text"}]},{"id":"114201","title":"Смена 15. Финальный трек","blocks":[{"id":"course-114201-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-15-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 15. Финальный трек"},{"id":"course-114201-2","text":"Финальное тестирование и решение о допуске 🎓","type":"heading","level":2},{"id":"course-114201-3","html":"<p>Сегодня проверь теоретическую подготовку по стандартам сервиса, меню, барной карте и iiko. Закрой обязательные тесты и разбери ошибки с наставником. Следующий этап — практическая аттестация в смене 16. Окончательный допуск и подписание чек-листа — после оценки практики руководителем.</p>","type":"text"},{"id":"merged--14","type":"heading","text":"Как пройти проверку в ASK Academy","level":2},{"id":"merged--15","type":"text","html":"<p>Открой раздел «Обучение» и тесты своей программы. Перед началом каждого теста проверь его условия и ограничение времени. Единого обещания «30 секунд на вопрос» или «две попытки» для всей программы нет — действуют настройки конкретного теста.</p><p>После завершения посмотри результат и работу над ошибками, повтори нужные занятия. Общая аттестация учитывает обязательные занятия и зачтённые тесты. Устные аттестации кухни и бара проводятся принимающими своего заведения; их результаты отображаются в профиле.</p><p>Отметка «Материал изучен» отражает изучение занятия. Практические навыки и решение о допуске подтверждает наставник и руководитель.</p>"},{"id":"course-114201-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114201-5","html":"<p>Пройти обязательные проверки своей программы, повторить темы с ошибками и получить обратную связь наставника. Подготовиться к практической аттестации следующей смены.</p>","type":"text"},{"id":"course-114201-12","text":"Что нужно повторить перед тестом 📚","type":"heading","level":2},{"id":"course-114201-13","text":"1. Стандарты сервиса","type":"heading","level":3},{"id":"course-114201-14","html":"<p>Шаги обслуживания (приветствие, приём заказа, подача, чек-бэк, расчёт, проводы)</p><p>Правила подачи и уборки посуды (с какой стороны, как держать)</p><p>Чек-бэк: зачем и как делать</p><p>Поведение при жалобах (не убирать самому, звать старшего)</p>","type":"text"},{"id":"course-114201-15","text":"2. Меню (закуски, салаты, горячие блюда)","type":"heading","level":3},{"id":"course-114201-16","html":"<p>Состав актуальных позиций меню своей точки</p><p>Время приготовления каждой категории</p><p>Блюда на компанию и их особенности</p><p>Акции и спецпредложения</p>","type":"text"},{"id":"course-114201-17","text":"3. Барная карта","type":"heading","level":3},{"id":"course-114201-18","html":"<p>Вина (3 белых, 3 красных, 3 игристых) — названия, характеристики, к чему рекомендовать</p><p>Авторские коктейли — состав, бокал, вкус</p><p>Крепкий алкоголь (базовые позиции)</p>","type":"text"},{"id":"course-114201-19","text":"4. Работа в iiko (POS)","type":"heading","level":3},{"id":"course-114201-20","html":"<p>Как открыть заказ, добавить блюдо, модификаторы</p><p>Как отправить на кухню</p><p>Применение скидок (процентные, бонусы, акционные).</p><p>Поиск гостя по номеру телефона для карты лояльности.</p><p>Проверка доступной суммы списания и оформление бонусов в пределах своих полномочий.</p>","type":"text"},{"id":"course-114201-21","text":"5. Программа лояльности","type":"heading","level":2},{"id":"course-114201-22","html":"<p>Проверь действующую программу лояльности своей точки и данные гостя в iiko, если условия зависят от его уровня. Назови подтверждённые условия начисления или списания. При сомнении уточни у менеджера.</p>","type":"text"},{"id":"course-114201-23","text":"Что проверить перед обещанием гостю","type":"heading","level":3},{"id":"course-114201-24","type":"list","items":["Действует ли программа на этой точке и для этого заказа.","Какой у гостя уровень и какие начисления доступны.","Сколько бонусов можно списать и сочетаются ли они с текущей акцией.","Кто оформляет операцию в iiko."],"ordered":false},{"id":"course-114201-25","text":"6. Открытие и закрытие смены","type":"heading","level":3},{"id":"course-114201-26","html":"<p>Чек-лист открытия (время, действия)</p><p>Контроль чистоты и расходников</p><p>Чек-лист закрытия (уборка, фотоотчёт, ОС)</p>","type":"text"},{"id":"course-114201-27","text":"Полезные советы перед тестом 💡","type":"heading","level":2},{"id":"course-114201-28","html":"<p>Отдохни. Уставший мозг хуже соображает.</p><p>Найти тихое место. Ничто не должно отвлекать.</p><p>Читай вопросы внимательно. Иногда правильный ответ прячется в деталях.</p><p>Не застревай на одном вопросе. Если не уверен — отметь примерно.</p><p>Дыши. Если волнуешься, сделай глубокий вдох.</p>","type":"text"},{"id":"course-114201-29","text":"Оценка знаний и сервиса 📊","type":"heading","level":2},{"id":"course-114201-30","text":"После теста твои результаты увидит менеджер. Он также оценит:","type":"heading","level":3},{"id":"course-114201-31","type":"list","items":["Твою работу в зале за всё время стажировки","Отзывы наставников","Твоё отношение к делу, пунктуальность, чистоту, коммуникабельность","На основе всего этого принимается решение о допуске."],"ordered":false},{"id":"course-114201-32","text":"Решение о допуске и подписание чек-листа ✅","type":"heading","level":2},{"id":"course-114201-33","html":"<p>Если ты успешно прошёл аттестацию и показал себя в работе, тебя допускают к самостоятельной работе. Это значит, что с этого момента ты — полноценный официант нашей команды! 🎉</p><p>Финальный шаг — подписание чек-листа стажёра. Это документ, подтверждающий, что ты прошёл все этапы обучения и готов работать самостоятельно. Чек-лист подписывают:</p><p>Ты (стажёр)</p><p>Твой наставник</p><p>Управляющий</p><p>После завершения практической аттестации и подтверждения руководителем тебя вводят в график и ты начинаешь работать как полноценный сотрудник.</p>","type":"text"},{"id":"course-114201-34","text":"Чек-лист: что ты сегодня сделаешь ✅","type":"heading","level":2},{"id":"course-114201-35","html":"<p>Я прошёл обязательные тесты своей программы в ASK Academy</p><p>Я повторил все ключевые темы (стандарты, меню, бар, iiko) 📚</p><p>Я получил результат теста и узнал свою оценку 📊</p><p>Я согласовал с наставником подготовку к практической аттестации</p><p>Я подготовил чек-лист для финальной оценки и подписания после практической аттестации</p>","type":"text"},{"id":"course-114201-36","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114201-37","html":"<p>Ты проделал огромный путь. Первые дни, когда ты боялся подойти к гостю, — позади. Сегодня ты готов доказать, что достоин быть частью команды. Верь в себя, не суетись, и всё получится.</p><p>А после теоретической аттестации тебя ждёт практическая — Смена 16: обслуживание административного состава. Это твой звёздный час: покажи всё, на что способен, перед руководством! 🔥</p><p>А потом — обязательно отпразднуй это событие! Ты заслужил. 🥳</p><p>Удачи! Мы верим в тебя! 💪</p><p>Следующая смена — твоя практическая аттестация с администрацией. Ждём тебя в команде!</p>","type":"text"}]},{"id":"114202","title":"Смена 16. Выпускной","blocks":[{"id":"course-114202-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-16-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 16. Выпускной"},{"id":"course-114202-2","text":"Практическая аттестация — обслуживание административного состава 🎯👔","type":"heading","level":2},{"id":"course-114202-3","html":"<p>Поздравляю! Это финальный экзамен. Твои гости — административный состав (управляющие, менеджеры, топ‑персонал). Они будут оценивать не только знание стандартов, но и твою уверенность, скорость, умение держаться и продавать. Покажи всё, чему научился за стажировку. Это твой выход на сцену! 🔥</p>","type":"text"},{"id":"course-114202-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114202-5","html":"<p>Продемонстрировать все навыки обслуживания в реальной ситуации</p><p>Подтвердить готовность к самостоятельной работе</p><p>Получить финальное «добро» от руководства</p>","type":"text"},{"id":"course-114202-6","text":"Памятка: что нужно сделать обязательно ✅","type":"heading","level":2},{"id":"course-114202-7","text":"1. Подготовка к смене 🧹","type":"heading","level":3},{"id":"course-114202-8","html":"<p>Перед сменой проверь время выхода и сбора в актуальном графике своей точки. Если график и памятка расходятся или предстоит банкет, заранее уточни время у ответственного за смену.</p><p>Переоденься, проверь внешний вид (чисто, глажено, дресс‑код).</p>","type":"text"},{"id":"course-114202-9","text":"Пройди по чек‑листу открытия:","type":"heading","level":3},{"id":"course-114202-10","type":"list","items":["опустить стулья, протереть столы,","разложить тарелки, приборы, текстиль,","выставить салфетницы, тейбл‑тенты,","проверить стоп‑лист и наличие расходников.","Участвуй в брифинге в согласованное время.","Прокати карту и открой личную смену в iiko."],"ordered":false},{"id":"course-114202-11","text":"2. Встреча гостей (администрации) 😊","type":"heading","level":3},{"id":"course-114202-12","html":"<p>Когда администрация сядет за твой стол, подойди с улыбкой в течение 1–2 минут.</p><p>Приветствие: «Добрый вечер, меня зовут [Имя], сегодня я буду вас обслуживать. Приятно видеть!»</p><p>Подай меню открытой рукой, предложи аперитив/воду.</p>","type":"text"},{"id":"course-114202-13","text":"3. Приём заказа 📝","type":"heading","level":3},{"id":"course-114202-14","html":"<p>Используй открытые вопросы: «Что бы вы хотели попробовать из новинок?»</p><p>Применяй аппетитные описания (например, для стейка из лосося, авторских коктейлей).</p><p>Уточни детали: прожарка мяса, аллергии, пожелания.</p><p>Повтори заказ перед отправкой.</p><p>Зафиксируй в iiko: количество гостей, все позиции, модификаторы.</p><p>Предупреди о времени ожидания, если блюдо готовится долго (стейк, горячее).</p>","type":"text"},{"id":"course-114202-15","text":"4. Подача и сервис 🍽️","type":"heading","level":3},{"id":"course-114202-16","html":"<p>Напитки принеси в течение 3–5 минут.</p><p>Подавай блюда синхронно (сначала закуски, потом горячее, десерт).</p><p>Используй правильную технику: подходи справа, тарелки ставь аккуратно, проговаривай название блюда.</p><p>Следи за чистотой стола: убирай пустые тарелки, доливай воду, меняй пепельницы.</p><p>Проводи чек-бэк через 2–3 минуты после подачи: «Как вам вкус и температура блюда?»</p><p>Если возникла проблема — действуй по алгоритму: выслушай, поблагодари, сообщи менеджеру (но сегодня ты сам должен решить в рамках своих полномочий, а менеджер наблюдает).</p>","type":"text"},{"id":"course-114202-17","text":"5. Работа с допродажами 💰","type":"heading","level":3},{"id":"course-114202-18","text":"Предложи дополнительные позиции:","type":"heading","level":3},{"id":"course-114202-19","type":"list","items":["«К вашему вину отлично подойдёт сырное плато»,","«Хотите добавить фирменный соус или овощи гриль?»,","«К вашему заказу могу предложить десерт из сегодняшнего меню».","Если гость просит рекомендацию по вину или коктейлю, уверенно посоветуй (вспомни мини‑квиз)."],"ordered":false},{"id":"course-114202-20","text":"6. Расчёт 💳","type":"heading","level":3},{"id":"course-114202-21","html":"<p>Когда гость просит счёт, проверь позиции и применимые условия бронирования, в том числе депозит или сервисный сбор, если они были согласованы.</p><p>Если в счёте акция, заранее уточни её условия и доступные способы оплаты. Бонусы сверяй по действующей программе точки и данным гостя.</p><p>Уточни способ оплаты и формат счёта. На экзаменационной смене окончательный расчёт и закрытие стола проводит менеджер.</p>","type":"text"},{"id":"course-114202-22","text":"7. Прощание и уборка 👋","type":"heading","level":3},{"id":"course-114202-23","html":"<p>Поблагодари гостей: «Спасибо, что были у нас! Приходите ещё, будем рады!»</p><p>Убери стол сразу после ухода гостей, подготовь его к следующей посадке.</p>","type":"text"},{"id":"course-114202-24","text":"В конце смены выполни закрытие по чек‑листу:","type":"heading","level":3},{"id":"course-114202-25","type":"list","items":["протереть столы, стейшены,","вымыть ножки стульев,","почистить диваны,","натереть посуду,","нагладить текстиль,","сделать фотоотчёт,","написать ОС о смене,","отчитаться старшему официанту/менеджеру."],"ordered":false},{"id":"course-114202-26","text":"8. Самоанализ 📝","type":"heading","level":3},{"id":"course-114202-27","html":"<p>После обслуживания подойди к менеджеру (экзаменатору) и спроси: «Есть ли замечания? Что я могу улучшить?»</p><p>Выслушай обратную связь спокойно, без оправданий. Запомни зоны роста.</p>","type":"text"},{"id":"course-114202-28","text":"⚠️ Важные моменты, на которые будут смотреть","type":"heading","level":2},{"id":"course-114202-29","html":"<p>Уверенность и спокойствие (не суетись, говори чётко).</p><p>Знание меню и барной карты (состав, вкусы, рекомендации).</p><p>Соблюдение стандартов (правильная подача, уборка, гигиена).</p><p>Скорость реакции (быстрое выполнение просьб).</p><p>Навыки продаж (предложения доп. позиций).</p><p>Чистота и порядок на столе и станции.</p><p>Взаимодействие с командой (если нужна помощь – попроси, но не злоупотребляй).</p>","type":"text"},{"id":"course-114202-30","text":"Чек-лист самопроверки после смены ✅","type":"heading","level":2},{"id":"course-114202-31","html":"<p>Я встретил гостей с улыбкой и представился.</p><p>Я правильно принял заказ, повторил его и внёс в iiko.</p><p>Я контролировал время подачи и предупреждал о задержках.</p><p>Я применил техники продаж (аппетитное описание, доп. продажи).</p><p>Я следил за чистотой стола и вовремя убирал посуду.</p><p>Я провёл чек-бэк и отреагировал на возможные замечания.</p><p>Я проверил счёт и применимые условия, передал окончательный расчёт менеджеру.</p><p>Я попрощался и пригласил приходить снова.</p><p>Я закрыл смену по чек-листу и сдал отчёт.</p>","type":"text"},{"id":"course-114202-32","text":"Напутствие 🌟","type":"heading","level":2},{"id":"course-114202-33","html":"<p>Сегодня ты показываешь всё, чему научился. Не бойся ошибиться — ошибки бывают у всех. Главное — твоё отношение, старание и желание стать лучше. Администрация будет оценивать не идеальность, а твой потенциал.</p><p>Ты готов! Выходи и зажги! 🔥💪</p><p>После этой смены — финальное решение. Мы верим в тебя!</p>","type":"text"}]}],"mergedFromIds":["waiter-standards"],"mergedLessonIds":{"42956":"114183","42957":"114185","42958":"114188","42959":"114188"},"mergeRevision":"waiter-service-20261117","referenceCompletion":{"lessonIds":["114183","114185","114188"],"testIds":["100075","100153","100159"]},"legacyLessonCredits":{"114183":[["42956"]],"114185":[["42957"]],"114188":[["42959","42958"]]},"legacyLessonCourseId":"waiter-standards"}},"expectedUpdatedAt":"2026-11-17T15:01:20.91309+00:00"},{"record":{"id":"100075","kind":"test","title":"Правила и работа в команде","payload":{"id":"100075","brand":"90","title":"Правила и работа в команде","priority":"attestation","passCount":15,"questions":[{"id":"100075-1","text":"К согласованному времени зал готов, но терминал не работает. Что делать?","type":"single","options":["Отметить зал готовым и проверить терминал при первом расчёте","Сообщить старшему и уточнить, как принимать оплату до устранения сбоя","Самостоятельно перенести открытие зала"]},{"id":"100075-2","text":"Какой внешний вид считается нарушением стандартов?","type":"single","options":["Неряшливая форма, неухоженные волосы, грязная обувь","Джинсовка и аксессуары в стиле 90-х","Минимальный макияж"]},{"id":"100075-3","text":"Что считается нарушением дисциплины?","type":"single","options":["Смена без бейджа","Опоздание без предупреждения менеджера","Отсутствие аксессуаров 90-х в образе"]},{"id":"100075-4","text":"На перерыве ты понадобился за одним из своих столов. Как это предусмотреть заранее?","type":"single","options":["Попросить гостей подождать твоего возвращения","Оставить включённым телефон","Передать столы конкретному коллеге и убедиться, что он принял подмену"]},{"id":"100075-5","text":"Ты вышел на пятничную смену в новой точке. Где уточнить время сбора и подготовки зала?","type":"single","options":["В актуальном графике точки и у ответственного за смену","На гостевом сайте","В расписании предыдущей точки"]},{"id":"100075-6","text":"Что делать, если форма испачкалась во время смены?","type":"single","options":["Продолжить работать до конца смены","Спрятать пятно под фартуком","Привести форму в порядок или заменить на чистую"]},{"id":"100075-7","text":"Что необходимо сделать после перекура, прежде чем вернуться к работе?","type":"single","options":["Освежить дыхание и убедиться, что одежда не пахнет дымом","Проверить телефон","Сразу вернуться в зал"]},{"id":"100075-8","text":"Что нужно сделать, если понимаешь, что опаздываешь на смену?","type":"single","options":["Прийти как можно быстрее, не предупреждая","Немедленно сообщить менеджеру и уточнить, требуется ли замена","Написать коллеге, чтобы передал сообщение"]},{"id":"100075-9","text":"Почему внешний вид официанта — часть стандарта обслуживания?","type":"single","options":["Потому что гость оценивает качество заведения по чистоте и опрятности персонала","Потому что так удобнее для фотоотчётов","Потому что это требование менеджера"]},{"id":"100075-10","text":"Почему запрещено ходить курить толпой?","type":"single","options":["Это может не понравиться гостям","Потому что зал должен оставаться под контролем — кто-то обязан быть на месте","Так требует охрана"]},{"id":"92988-5","text":"Гость перестал поддерживать шутки и отвечает коротко. Как продолжить обслуживание?","type":"single","options":["Перейти на спокойный доброжелательный тон и дать гостю пространство","Продолжить шутить, чтобы его разговорить","Свести общение к подаче и расчёту"]},{"id":"92988-7","text":"Как официант должен действовать, если не знает ответа на вопрос гостя?","type":"single","options":["Сказать то, что первое придет в голову, главное - уверенно","Перевести тему","Уточнить у менеджера и вернуться с ответом"]},{"id":"92988-8","text":"Где уточнить, разрешён ли аксессуар для смены в твоём заведении?","type":"single","options":["По фотографиям команды","По памятке другой точки","По действующему стандарту формы своей точки, при сомнении у менеджера"]},{"id":"92988-9","text":"Перед открытием сломалось крепление аксессуара на форме. Что сделать?","type":"single","options":["Снять аксессуар и согласовать замену, если он обязателен","Оставить его до первого перерыва","Закрепить подручным способом и сразу выйти в зал"]},{"id":"92988-10","text":"Ты заметил, что гости за столом коллеги пытаются привлечь внимание. Как поступить?","type":"single","options":["Дождаться, пока коллега сам увидит гостей","Подойти, уточнить просьбу и передать её ответственному официанту","Сразу забрать стол и вести его до расчёта"]}],"trainingBrand":"90","timeLimitSeconds":450,"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"completionCredits":[["92988"]],"mergedFromIds":["92988"],"legacyTestTitles":{"92988":"Тест 1. Правила работы официанта"}},"course_id":"waiter-internship","published":true,"department":null,"updated_at":"2026-11-17T15:01:20.696156+00:00","restaurant_id":null},"keys":{"100075-1":[1],"100075-2":[0],"100075-3":[1],"100075-4":[2],"100075-5":[0],"100075-6":[2],"100075-7":[0],"100075-8":[1],"100075-9":[0],"100075-10":[1],"92988-5":[0],"92988-7":[2],"92988-8":[2],"92988-9":[0],"92988-10":[1]},"expectedUpdatedAt":"2026-11-17T15:01:20.696156+00:00"},{"record":{"id":"100153","kind":"test","title":"Открытие смены","payload":{"id":"100153","brand":"90","title":"Открытие смены","priority":"attestation","passCount":11,"questions":[{"id":"100153-1","text":"Какие действия необходимо выполнить с входной группой?","type":"single","options":["Протереть стекла","Оставить на проверку менеджеру","Проверить параметры: чистота пола, подоконников, коврика, пепельницы, включение вентиляции","Проверить ковёр"]},{"id":"100153-2","text":"Что должно быть в идеальном порядке в гостевом туалете?","type":"single","options":["Только чистота пола","Мыло, полотенца, смыв, чистота","Только сантехника","Только наличие туалетной бумаги"]},{"id":"100153-3","text":"Как должен выглядеть порядок в подсобке?","type":"single","options":["Обувь на полке, вещи на вешалке, ничего не валяется","Всё должно быть разложено","Проверяются только шкафчики","Проверка не требуется"]},{"id":"100153-4","text":"Какой уровень наполнения соли и перца считается правильным?","type":"single","options":["Только если заканчивается","Полный","На ¾ емкости","Наполовину"]},{"id":"100153-5","text":"Как проверяется исправность терминала перед сменой?","type":"single","options":["Проверять только при необходимости","Убедиться, что работает и есть чековая лента","Просто включить","Проверить только наличие ленты"]},{"id":"100153-6","text":"Какой инструмент помогает официанту держать всё под контролем при открытии смены?","type":"single","options":["Чек-лист","График смен","Лист заказов","Инструкция по безопасности"]},{"id":"100153-7","text":"Что входит в обязательную проверку стейшена?","type":"single","options":["Проверка формы персонала","Терминалы и меню","Только салфетки","Полироль, тряпки, салфетки, сахар, зубочистки"]},{"id":"100153-8","text":"После мойки приборы чистые, но на них остались капли воды. Что сделать перед сервировкой?","type":"single","options":["Разложить приборы, чтобы высохли на столе","Просушить и отполировать чистой салфеткой по стандарту точки","Сразу сложить во влажный лоток"]},{"id":"100153-9","text":"Какое должно быть состояние меню при открытии зала?","type":"single","options":["Достаточно просто заменить грязные","Можно использовать даже слегка повреждённые меню","Чистое, без рваных страниц, протёртое влажной тряпкой","Меню не требует проверки"]},{"id":"100153-10","text":"Какие элементы зала необходимо проверить перед открытием?","type":"single","options":["Только стулья","Только столы и салфетки","Только терминалы","Пол, стулья, столы, подоконники"]},{"id":"92998-7","text":"При сервировке ты заметил на приборе следы еды. Что сделать?","type":"single","options":["Отполировать его салфеткой","Отложить до конца подготовки","Отправить прибор на повторную мойку и взять чистый"]}],"trainingBrand":"90","timeLimitSeconds":330,"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"completionCredits":[["92998"]],"mergedFromIds":["92998"],"legacyTestTitles":{"92998":"Тест 2. Открытие смены"}},"course_id":"waiter-internship","published":true,"department":null,"updated_at":"2026-11-17T15:01:20.696373+00:00","restaurant_id":null},"keys":{"100153-1":[2],"100153-2":[1],"100153-3":[0],"100153-4":[2],"100153-5":[1],"100153-6":[0],"100153-7":[3],"100153-8":[1],"100153-9":[2],"100153-10":[3],"92998-7":[2]},"expectedUpdatedAt":"2026-11-17T15:01:20.696373+00:00"},{"record":{"id":"100159","kind":"test","title":"Обслуживание и чек-бэк","payload":{"id":"100159","brand":"90","title":"Обслуживание и чек-бэк","priority":"attestation","passCount":16,"questions":[{"id":"100159-1","text":"Как официант должен сообщать о времени приготовления?","type":"single","options":["Обещать минимальное время","Говорить «скоро будет»","Честно сказать реальное время"]},{"id":"100159-2","text":"Как официант должен заходить к гостю?","type":"single","options":["С улыбкой и на позитиве, создавая атмосферу 90-х","Без эмоций, сразу подавая меню","Спокойно и официально"]},{"id":"100159-3","text":"Как правильно делать чек-бэк?","type":"single","options":["Проявлять искренний интерес, считывать эмоции гостя","Спрашивать только, если гость выглядит недовольным","Спросить «Всё в порядке?»"]},{"id":"100159-4","text":"Что важно сделать при подаче меню?","type":"single","options":["Спросить, хочет ли гость что-то заказать сразу","Оставить на столе без слов","Подавать открытой рукой, предложить освежающий напиток"]},{"id":"100159-5","text":"Как лучше всего задавать вопросы гостю во время чек-бэка?","type":"single","options":["Чётко и официально","Строго по шаблону","С искренним интересом, без шаблонных фраз"]},{"id":"100159-6","text":"Зачем делать контрольный чек-бэк?","type":"single","options":["Уточнить сумму счета","Проверить, понравился ли официант","Закрепить положительное впечатление перед уходом"]},{"id":"100159-7","text":"Гость попробовал блюдо и отодвинул тарелку. Как начать чек-бэк?","type":"single","options":["Сразу спросить, можно ли убрать тарелку","Сразу предложить замену","Спокойно уточнить, как ему блюдо, и выслушать ответ"]},{"id":"100159-8","text":"Когда официант должен делать текущий чек-бэк?","type":"single","options":["Через 2-3 минуты после первой вилки еды","После того, как гость полностью съел блюдо","Сразу после подачи блюда"]},{"id":"100159-9","text":"Что такое Check Back (чек-бэк)?","type":"single","options":["Обратная связь с гостем о качестве еды и сервиса","Проверка счета гостя","Оценка работы персонала"]},{"id":"100159-10","text":"Какой приём помогает увеличить продажу блюд?","type":"single","options":["Просто назвать позиции из меню, гость разберется по ходу заказа","Дать гостю меню и уйти, тогда он сам закажет все, что нужно","Описание блюд с эмоциями и аппетитными деталями"]},{"id":"92995-6","text":"Как правильно проводить расчёт гостя?","type":"single","options":["Только при повторном запросе","Без задержек, уточнив тип оплаты","Подождать, пока гость напомнит"]},{"id":"92993-5","text":"Что делать, если гость не в восторге от твоей рекомендации?","type":"single","options":["Переубедить его","Посоветовать что-то другое","Принять спокойно и учесть для будущих советов","Спросить, почему он выбрал это блюдо"]},{"id":"92993-6","text":"Какой стиль общения рекомендуется при чек-бэке?","type":"single","options":["Формальный и строгий","Минимальный, без эмоций","Дружеский, искренний, ненавязчивый","Только при необходимости"]},{"id":"92993-7","text":"Что делать, если гость недоволен блюдом?","type":"single","options":["Выяснить причину и сообщить менеджеру","Сказать, что так и должно быть","Извиниться и уйти","Заменить блюдо без уведомления"]},{"id":"92993-9","text":"Когда официант делает поэтапный чек-бэк?","type":"single","options":["После выдачи чека","До подачи блюда","Когда убирает тарелку у гостя","В начале смены"]},{"id":"92993-10","text":"Что делать, если гость не доел блюдо?","type":"single","options":["Немедленно предложить другое блюдо","Спросить причину ненавязчиво","Просто забрать тарелку","Ничего не делать"]}],"trainingBrand":"90","timeLimitSeconds":480,"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"completionCredits":[["92995","92993"]],"mergedFromIds":["92995","92993"],"legacyTestTitles":{"92993":"Тест 4. Чек бэк","92995":"Тест 3. Обслуживание гостей"}},"course_id":"waiter-internship","published":true,"department":null,"updated_at":"2026-11-17T15:01:20.704891+00:00","restaurant_id":null},"keys":{"100159-1":[2],"100159-2":[0],"100159-3":[0],"100159-4":[2],"100159-5":[2],"100159-6":[2],"100159-7":[2],"100159-8":[0],"100159-9":[0],"100159-10":[2],"92995-6":[1],"92993-5":[2],"92993-6":[2],"92993-7":[0],"92993-9":[2],"92993-10":[1]},"expectedUpdatedAt":"2026-11-17T15:01:20.704891+00:00"},{"record":{"id":"waiter-standards","kind":"course","title":"Стандарты работы официанта","course_id":null,"published":false,"department":null,"updated_at":"2026-11-17T15:01:20.925864+00:00","restaurant_id":null,"payload":{"id":"waiter-standards","pass":80,"brand":"90","title":"Стандарты работы официанта","outline":[{"type":"lesson","title":"Урок 1. Правила работы официанта","lessonIndex":0},{"id":"92988","type":"test","title":"Тест 1. Правила работы официанта"},{"type":"lesson","title":"Урок 2. Стандарты открытия смены","lessonIndex":1},{"id":"92998","type":"test","title":"Тест 2. Открытие смены"},{"type":"lesson","title":"Урок 3. Обслуживание гостей","lessonIndex":2},{"id":"92995","type":"test","title":"Тест 3. Обслуживание гостей"},{"type":"lesson","title":"Урок 4. Чек-бэк и его важность","lessonIndex":3},{"id":"92993","type":"test","title":"Тест 4. Чек бэк"}],"testIds":["92988","92998","92995","92993"],"priority":"start","sequence":[{"id":"42956","type":"lesson"},{"id":"92988","type":"test"},{"id":"42957","type":"lesson"},{"id":"92998","type":"test"},{"id":"42959","type":"lesson"},{"id":"92995","type":"test"},{"id":"42958","type":"lesson"},{"id":"92993","type":"test"}],"positions":["Официант","Администратор зала","Хостес"],"questions":[],"departments":["Зал"],"description":"Правила работы, открытие смены, обслуживание гостей и чек-бэк. Исходные материалы вашей команды «90-е».","restaurantIds":["pushkino","khimki","mytishchi"],"trainingBrand":"90","audienceLevels":["trainee","certified"],"audiencePositions":["Официант","Администратор зала"],"audiencePriorities":{},"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"lessons":[{"id":"42956","text":"Кто такой официант?\n\nТы стал частью реально клёвой команды официантов \"Бара 90-е\". Это не просто работа – это тусовка, где ты не только разносишь заказы, но и создаёшь атмосферу 90-х! Гость должен чувствовать себя как на вечеринке у старых друзей, и ты – главный ведущий этого движа.\nДелай так, чтобы гость запомнил этот вечер, захотел вернуться и притащил с собой друзей! Для этого важно знать основные правила, выглядеть как надо и владеть всеми нужными навыками.\n\nКакие правила?\n\nПриход на работу 🏃‍♂️\nПеред сменой проверь время выхода и сбора в актуальном графике своей точки. Если график и памятка расходятся или предстоит банкет, заранее уточни время у ответственного за смену. Готовность зала проверь к сроку, который согласовали на смену.\nОпаздываешь? Проблема! Заранее предупреди менеджера, если не успеваешь. Опоздания портят атмосферу и работу всей команды. Здесь важен командный дух, поэтому подводить своих не вариант.\nЕсли заранее нашел себе замену – молодец, но все равно предупреди.\nПерекуры 🚬\nСогласуй короткий перерыв со старшим. Передай столы конкретному коллеге и убедись, что он принял подмену. Сообщи, что уже заказано, чего ждут гости и о чём они просили.\nНе ходи курить группой, ты же не на перемене в школе!\nПосле перекура – жвачка или спрей для свежести\nОбщение с гостями 🗣\nВсегда улыбаемся! Даже если день не задался – твоя улыбка делает атмосферу.\nИспользуем лёгкий сленг 90-х – так гости сразу понимают, что здесь их ждёт ностальгия\nЕсли что-то не знаешь, уточни у менеджера, а если это происходит в разговоре с Гостями - предупреди, что уточнишь и вернешься с ответом.\nДержим лицо в любой ситуации – даже если гость капризный, решаем всё с позитивом и юмором\nЭто еще не все правила, которые ты должен соблюдать. Чтобы изучить их, переходи в Библиотеку , там есть Правила сотрудника на смене\n\nКак должен выглядеть официант \"Бара 90-е\"?\n\nФизическая форма – Симпатяга\nЧистая кожа (желательно наличие штукатурки), уложенные волосы, ухоженные ногти\nСвежий аромат – без перегибов с резким парфюмом.\nСтильный прикид в духе 90-х: джинсовки, яркие цвета, модные аксессуары.\nФорма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.\nФорма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.\n\nДля нас официант – это:\n\nГлавный моторчик движа, без которого не будет улетной атмосферы.\nВеселый друг, которому не фиолетово, что происходит в зале – он понимает, что всё зависит от него.\nЧеловек, который сам тащится от заведения и заряжает этой любовью гостей. Они возвращаются снова и снова, потому что здесь кайф!\n\nДля наших гостей официант – это:\n\nЭмоции: Лучший друг\nСвой в доску, всегда на позитиве, улыбается и создаёт уютную атмосферу домашнего праздника.\nЛичностные качества: Радушный хозяин\nВнимательный – сразу видит, что нужно гостю, и приносит это моментально.\nЧестный – никаких мутных тем, репутация заведения на кону.\nДержит лицо – даже если устал или день не задался, гостю этого видеть не положено.\nНе сыплет негативом – бар должен быть местом кайфа, а не разборок.\nРазруливает конфликты ещё до того, как они завелись.\nОткрытый – сам заводит разговор, легко общается, помогает выбрать блюдо.\nПрофнавыки: Знает и умеет\nРазбирается в меню как настоящий профи: знает, что вкусное, как готовят, за сколько минут принесут.\nМастер подачи: напитки и блюда на столе всегда быстро, красиво и в правильном порядке.\nЧек закроет в два счёта, а стол поддержит в идеальной чистоте","title":"Урок 1. Правила работы официанта","blocks":[{"id":"course-42956-1","tone":"sky","type":"hero","image":"assets/waiter/lesson-1-0.jpg","label":"Стандарты работы официанта","title":"Урок 1. Правила работы официанта"},{"id":"course-42956-2","text":"Кто такой официант?","type":"heading","level":2},{"id":"course-42956-3","html":"<p>Ты стал частью реально клёвой команды официантов \"Бара 90-е\". Это не просто работа – это тусовка, где ты не только разносишь заказы, но и создаёшь атмосферу 90-х! Гость должен чувствовать себя как на вечеринке у старых друзей, и ты – главный ведущий этого движа.</p><p>Делай так, чтобы гость запомнил этот вечер, захотел вернуться и притащил с собой друзей! Для этого важно знать основные правила, выглядеть как надо и владеть всеми нужными навыками.</p>","type":"text"},{"id":"course-42956-4","text":"Какие правила?","type":"heading","level":2},{"id":"course-42956-5","html":"<p>Приход на работу 🏃‍♂️</p><p>Перед сменой проверь время выхода и сбора в актуальном графике своей точки. Если график и памятка расходятся или предстоит банкет, заранее уточни время у ответственного за смену. Готовность зала проверь к сроку, который согласовали на смену.</p><p>Опаздываешь? Проблема! Заранее предупреди менеджера, если не успеваешь. Опоздания портят атмосферу и работу всей команды. Здесь важен командный дух, поэтому подводить своих не вариант.</p><p>Если заранее нашел себе замену – молодец, но все равно предупреди.</p><p>Перекуры 🚬</p><p>Согласуй короткий перерыв со старшим. Передай столы конкретному коллеге и убедись, что он принял подмену. Сообщи, что уже заказано, чего ждут гости и о чём они просили.</p><p>Не ходи курить группой, ты же не на перемене в школе!</p><p>После перекура – жвачка или спрей для свежести</p><p>Общение с гостями 🗣</p><p>Всегда улыбаемся! Даже если день не задался – твоя улыбка делает атмосферу.</p><p>Используем лёгкий сленг 90-х – так гости сразу понимают, что здесь их ждёт ностальгия</p><p>Если что-то не знаешь, уточни у менеджера, а если это происходит в разговоре с Гостями - предупреди, что уточнишь и вернешься с ответом.</p><p>Держим лицо в любой ситуации – даже если гость капризный, решаем всё с позитивом и юмором</p><p>Это еще не все правила, которые ты должен соблюдать. Чтобы изучить их, переходи в Библиотеку , там есть Правила сотрудника на смене</p>","type":"text"},{"id":"course-42956-6","text":"Как должен выглядеть официант \"Бара 90-е\"?","type":"heading","level":2},{"id":"course-42956-7","html":"<p>Физическая форма – Симпатяга</p><p>Чистая кожа (желательно наличие штукатурки), уложенные волосы, ухоженные ногти</p><p>Свежий аромат – без перегибов с резким парфюмом.</p><p>Стильный прикид в духе 90-х: джинсовки, яркие цвета, модные аксессуары.</p><p>Форма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.</p><p>Форма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.</p>","type":"text"},{"id":"course-42956-8","src":"assets/waiter/lesson-1-1.jpg","type":"image","caption":""},{"id":"course-42956-9","src":"assets/waiter/lesson-1-2.jpg","type":"image","caption":""},{"id":"course-42956-10","src":"assets/waiter/lesson-1-3.jpg","type":"image","caption":""},{"id":"course-42956-11","text":"Для нас официант – это:","type":"heading","level":2},{"id":"course-42956-12","type":"list","items":["Главный моторчик движа, без которого не будет улетной атмосферы.","Веселый друг, которому не фиолетово, что происходит в зале – он понимает, что всё зависит от него.","Человек, который сам тащится от заведения и заряжает этой любовью гостей. Они возвращаются снова и снова, потому что здесь кайф!"],"ordered":false},{"id":"course-42956-13","src":"assets/waiter/lesson-1-4.jpg","type":"image","caption":""},{"id":"course-42956-14","text":"Для наших гостей официант – это:","type":"heading","level":2},{"id":"course-42956-15","type":"list","items":["Эмоции: Лучший друг","Свой в доску, всегда на позитиве, улыбается и создаёт уютную атмосферу домашнего праздника.","Личностные качества: Радушный хозяин","Внимательный – сразу видит, что нужно гостю, и приносит это моментально.","Честный – никаких мутных тем, репутация заведения на кону.","Держит лицо – даже если устал или день не задался, гостю этого видеть не положено.","Не сыплет негативом – бар должен быть местом кайфа, а не разборок.","Разруливает конфликты ещё до того, как они завелись.","Открытый – сам заводит разговор, легко общается, помогает выбрать блюдо.","Профнавыки: Знает и умеет","Разбирается в меню как настоящий профи: знает, что вкусное, как готовят, за сколько минут принесут.","Мастер подачи: напитки и блюда на столе всегда быстро, красиво и в правильном порядке.","Чек закроет в два счёта, а стол поддержит в идеальной чистоте"],"ordered":false}],"images":["assets/waiter/lesson-1-0.jpg","assets/waiter/lesson-1-1.jpg","assets/waiter/lesson-1-2.jpg","assets/waiter/lesson-1-3.jpg","assets/waiter/lesson-1-4.jpg"]},{"id":"42957","text":"Открытие зала\n\nЧек-лист – твой лучший инструмент, чтобы держать всё под контролем! Это список вещей, которые нельзя пропустить при открытии смены.\n\nМебель. Опустить стулья, выровнять мебель, почистить ее средством, протереть подножья столов и стульев \nСтолы. Протереть их чистой влажной тряпкой \nЗасервировать столы. Постановочная тарелка, столовые приборы (нож, вилка), хайбол, тейблтенты с актуальной информацией, салфетница, текстильная салфетка. Приборы ополаскиваем в кипятке либо брызгаем разведенным уксусом\nПроверить и заполнить расходники в стейшене, также в стейшенах всегда должна быть чистая вода в ведре для уборки столов\nПривести в порядок декор зала, протереть пыль \nРасставить таблички с надписями на барный стол \nВсё в порядке? Значит, ты готов к улётной смене! 🚀","title":"Урок 2. Стандарты открытия смены","blocks":[{"id":"course-42957-1","tone":"sky","type":"hero","image":"assets/waiter/lesson-2-0.jpg","label":"Стандарты работы официанта","title":"Урок 2. Стандарты открытия смены"},{"id":"course-42957-2","text":"Открытие зала","type":"heading","level":2},{"id":"course-42957-3","html":"<p>Чек-лист – твой лучший инструмент, чтобы держать всё под контролем! Это список вещей, которые нельзя пропустить при открытии смены.</p><p>Мебель. Опустить стулья, выровнять мебель, почистить ее средством, протереть подножья столов и стульев</p><p>Столы. Протереть их чистой влажной тряпкой</p><p>Засервировать столы. Постановочная тарелка, столовые приборы (нож, вилка), хайбол, тейблтенты с актуальной информацией, салфетница, текстильная салфетка. Приборы ополаскиваем в кипятке либо брызгаем разведенным уксусом</p><p>Проверить и заполнить расходники в стейшене, также в стейшенах всегда должна быть чистая вода в ведре для уборки столов</p><p>Привести в порядок декор зала, протереть пыль</p><p>Расставить таблички с надписями на барный стол</p>","type":"text"},{"id":"course-42957-4","text":"Всё в порядке? Значит, ты готов к улётной смене! 🚀","type":"heading","level":2}],"images":["assets/waiter/lesson-2-0.jpg"]},{"id":"42959","text":"Как сделать так, чтобы гость вернулся? 🎤🔥\n\nЛистай шаги обслуживания и запоминай\n\nВрываемся с улыбкой! 😃\nЗаходим на позитиве – дарим гостю хорошее настроение с порога и представляемся!\nМеню подаём открытой рукой\nБонус: пока гость листает меню, предлагай что-нибудь освежающее – сразу +1 к продажам!\nВыясняем, чего душа хочет, помогаем выбрать блюда\nРаскачиваем эмоции – аппетитные описания блюд, от которых слюнки потекут.\nБонус: «Хотите крутой гарнир или эксклюзивный соус к этому?» – больше вкуса, больше кайфа, больше продаж!\nВремя приготовления – если задержка, сразу говорим реальное время, гость будет благодарен за честность.\nПовторяем заказ – чтобы не испортить впечатления от возможной ошибки!\nБлюда подаём открытой рукой, как профессионалы.\nВсё приносим синхронно – никто не ждёт, все довольны!\nПервыми – закуски, потом горячее, потом десерты – чистый ритм сервиса!\n«Ну как? Огонь? 🔥» – не просто спрашиваем, а реально чувствуем эмоции гостя!\nЕсли что-то не так – сразу решаем вопрос.\nГасим возможные конфликты ещё до их появления.\nПодробнее о чек бэке - в следующем уроке\nГость попросил счёт? Не стоим, несём моментально!\nЕсли в точке действует программа лояльности, уточни у гостя, пользуется ли он ей. Перед расчётом проверь условия акции и назови доступные способы оплаты.\n«Наличные или карта, общий или раздельный?» – всё чётко, без лишних вопросов.\n«Спасибо, что заглянули, ждём снова!» – главное, чтобы звучало искренне.\nФинальный аккорд: Улыбка, кивок, возможно даже стильный жест рукой – гость должен уходить с ощущением, что его реально ждали!\nПересервируем стол за 2-3 минуты – новые гости уже на подходе!","title":"Урок 3. Обслуживание гостей","blocks":[{"id":"course-42959-1","tone":"sky","type":"hero","image":"assets/waiter/lesson-3-0.jpg","label":"Стандарты работы официанта","title":"Урок 3. Обслуживание гостей"},{"id":"course-42959-2","text":"Как сделать так, чтобы гость вернулся? 🎤🔥","type":"heading","level":2},{"id":"course-42959-3","text":"Листай шаги обслуживания и запоминай","type":"heading","level":2},{"id":"course-42959-4","html":"<p>Врываемся с улыбкой! 😃</p><p>Заходим на позитиве – дарим гостю хорошее настроение с порога и представляемся!</p><p>Меню подаём открытой рукой</p><p>Бонус: пока гость листает меню, предлагай что-нибудь освежающее – сразу +1 к продажам!</p><p>Выясняем, чего душа хочет, помогаем выбрать блюда</p><p>Раскачиваем эмоции – аппетитные описания блюд, от которых слюнки потекут.</p><p>Бонус: «Хотите крутой гарнир или эксклюзивный соус к этому?» – больше вкуса, больше кайфа, больше продаж!</p><p>Время приготовления – если задержка, сразу говорим реальное время, гость будет благодарен за честность.</p><p>Повторяем заказ – чтобы не испортить впечатления от возможной ошибки!</p><p>Блюда подаём открытой рукой, как профессионалы.</p><p>Всё приносим синхронно – никто не ждёт, все довольны!</p><p>Первыми – закуски, потом горячее, потом десерты – чистый ритм сервиса!</p><p>«Ну как? Огонь? 🔥» – не просто спрашиваем, а реально чувствуем эмоции гостя!</p><p>Если что-то не так – сразу решаем вопрос.</p><p>Гасим возможные конфликты ещё до их появления.</p><p>Подробнее о чек бэке - в следующем уроке</p><p>Гость попросил счёт? Не стоим, несём моментально!</p><p>Если в точке действует программа лояльности, уточни у гостя, пользуется ли он ей. Перед расчётом проверь условия акции и назови доступные способы оплаты.</p><p>«Наличные или карта, общий или раздельный?» – всё чётко, без лишних вопросов.</p><p>«Спасибо, что заглянули, ждём снова!» – главное, чтобы звучало искренне.</p><p>Финальный аккорд: Улыбка, кивок, возможно даже стильный жест рукой – гость должен уходить с ощущением, что его реально ждали!</p><p>Пересервируем стол за 2-3 минуты – новые гости уже на подходе!</p>","type":"text"},{"id":"course-42959-5","src":"assets/waiter/lesson-3-1.jpg","type":"image","caption":""},{"id":"course-42959-6","src":"assets/waiter/lesson-3-2.jpg","type":"image","caption":""},{"id":"course-42959-7","src":"assets/waiter/lesson-3-3.jpg","type":"image","caption":""},{"id":"course-42959-8","src":"assets/waiter/lesson-3-4.jpg","type":"image","caption":""},{"id":"course-42959-9","src":"assets/waiter/lesson-3-5.jpg","type":"image","caption":""},{"id":"course-42959-10","src":"assets/waiter/lesson-3-6.jpg","type":"image","caption":""}],"images":["assets/waiter/lesson-3-0.jpg","assets/waiter/lesson-3-1.jpg","assets/waiter/lesson-3-2.jpg","assets/waiter/lesson-3-3.jpg","assets/waiter/lesson-3-4.jpg","assets/waiter/lesson-3-5.jpg","assets/waiter/lesson-3-6.jpg"]},{"id":"42958","text":"Для начала: что такое чек-бэк?\n\nCheck Back (чек-бэк) – это твой инструмент, чтобы понять, насколько гость доволен. Вкусно ли ему? Всё ли ок с качеством блюд и напитков? Не нужно ли ему что-то еще (салфетки, соус, пепельница)? А ещё чек-бэк – это твой шанс предотвратить конфликт на ранней стадии!\n\nКак его делать?\nПосле подачи блюд ждём немного времени, чтобы гость успел попробовать.\nПодходим, спрашиваем, как ему еда.\nЕсли гость недоволен – выясняем, в чём дело.\nЕсли проблема из-за качества блюда (неправильно приготовлено, остывшее и т.д.), сообщаем менеджеру.\nМенеджер решает, включать ли блюдо в счёт.\nВиды чек-бэка:\n\nТекущий – быстрый фидбэк\n\nЖдёшь 2-3 минуты после первой вилки еды.\nПодходишь, если гость заказал твою рекомендацию или новинку.\nВажно! Не перебиваем важную беседу, ждём удачного момента.\n\nПоэтапный – шаг за шагом\n\nСпрашиваем мнение, когда убираем тарелку.\nЕсли гость не доел – обязательно выясняем, почему.\nЕсли гость не в восторге от твоей рекомендации – не паримся: «Да, вкусы у всех разные, зато теперь я знаю, что советовать вам в следующий раз!»\n\nКонтрольный – закрепляем успех\n\nСпрашиваем о впечатлениях, когда гость просит счёт.\nОн ещё раз вспоминает, как классно провёл время.\nПроговаривая впечатления, фиксирует их в памяти, а значит, захочет вернуться!\n\nВажный момент!\n\nНе спрашиваем скучные «Всё ли в порядке?» или «Вам что-то не нравится?» – такие вопросы не цепляют. Подходи к гостю с искренним интересом!\n\nКакой чек-бэк использовать? ﻿﻿﻿﻿Решай сам, пробуй разные варианты и найди тот, который работает для тебя лучше всего! 🚀","title":"Урок 4. Чек-бэк и его важность","blocks":[{"id":"course-42958-1","tone":"sky","type":"hero","image":"assets/waiter/lesson-4-0.jpg","label":"Стандарты работы официанта","title":"Урок 4. Чек-бэк и его важность"},{"id":"course-42958-2","text":"Для начала: что такое чек-бэк?","type":"heading","level":2},{"id":"course-42958-3","html":"<p>Check Back (чек-бэк) – это твой инструмент, чтобы понять, насколько гость доволен. Вкусно ли ему? Всё ли ок с качеством блюд и напитков? Не нужно ли ему что-то еще (салфетки, соус, пепельница)? А ещё чек-бэк – это твой шанс предотвратить конфликт на ранней стадии!</p>","type":"text"},{"id":"course-42958-4","src":"assets/waiter/lesson-4-1.jpg","type":"image","caption":""},{"id":"course-42958-5","text":"Как его делать?","type":"heading","level":2},{"id":"course-42958-6","html":"<p>После подачи блюд ждём немного времени, чтобы гость успел попробовать.</p><p>Подходим, спрашиваем, как ему еда.</p><p>Если гость недоволен – выясняем, в чём дело.</p><p>Если проблема из-за качества блюда (неправильно приготовлено, остывшее и т.д.), сообщаем менеджеру.</p><p>Менеджер решает, включать ли блюдо в счёт.</p>","type":"text"},{"id":"course-42958-7","text":"Виды чек-бэка:","type":"heading","level":2},{"id":"course-42958-8","type":"list","items":["Текущий – быстрый фидбэк","Ждёшь 2-3 минуты после первой вилки еды.","Подходишь, если гость заказал твою рекомендацию или новинку."],"ordered":false},{"id":"course-42958-9","text":"Важно! Не перебиваем важную беседу, ждём удачного момента.","tone":"yellow","type":"callout","title":""},{"id":"course-42958-10","html":"<p>Поэтапный – шаг за шагом</p><p>Спрашиваем мнение, когда убираем тарелку.</p><p>Если гость не доел – обязательно выясняем, почему.</p><p>Если гость не в восторге от твоей рекомендации – не паримся: «Да, вкусы у всех разные, зато теперь я знаю, что советовать вам в следующий раз!»</p><p>Контрольный – закрепляем успех</p><p>Спрашиваем о впечатлениях, когда гость просит счёт.</p><p>Он ещё раз вспоминает, как классно провёл время.</p><p>Проговаривая впечатления, фиксирует их в памяти, а значит, захочет вернуться!</p><p>Важный момент!</p><p>Не спрашиваем скучные «Всё ли в порядке?» или «Вам что-то не нравится?» – такие вопросы не цепляют. Подходи к гостю с искренним интересом!</p><p>Какой чек-бэк использовать? Решай сам, пробуй разные варианты и найди тот, который работает для тебя лучше всего! 🚀</p>","type":"text"}],"images":["assets/waiter/lesson-4-0.jpg","assets/waiter/lesson-4-1.jpg"]}],"mergedIntoId":"waiter-internship"}},"expectedUpdatedAt":"2026-11-17T15:01:20.925864+00:00"},{"record":{"id":"92988","kind":"test","title":"Тест 1. Правила работы официанта","payload":{"id":"92988","brand":"90","title":"Тест 1. Правила работы официанта","priority":"attestation","passCount":10,"questions":[{"id":"92988-1","text":"Коллега подменит тебя на перерыве. Что ему передать?","type":"single","options":["Только номера столов","Что уже заказано, чего ждут гости и о чём они просили","Только список столов, которые ждут счёт"]},{"id":"92988-2","text":"В графике и памятке указано разное время сбора. Как определить, когда прийти?","type":"single","options":["Ориентироваться на время открытия для гостей","Прийти к тому же времени, что и в прошлую смену","Заранее уточнить время сбора у ответственного за смену"]},{"id":"92988-3","text":"Что делать, если официант опаздывает?","type":"single","options":["Предупредить менеджера","Просто приехать в бар и начать работу","Опоздать и извиниться"]},{"id":"92988-4","text":"Как официант должен подавать блюда и напитки?","type":"single","options":["В любом порядке","Быстро, красиво и в правильной последовательности","Гость сам забирает с бара"]},{"id":"92988-5","text":"Гость перестал поддерживать шутки и отвечает коротко. Как продолжить обслуживание?","type":"single","options":["Перейти на спокойный доброжелательный тон и дать гостю пространство","Продолжить шутить, чтобы его разговорить","Свести общение к подаче и расчёту"]},{"id":"92988-6","text":"Что проверить в своём внешнем виде перед выходом в зал?","type":"single","options":["Только наличие бейджа и фартука","Чистоту и опрятность формы, обуви и соответствие стандарту заведения","Только наличие элементов в стиле бара"]},{"id":"92988-7","text":"Как официант должен действовать, если не знает ответа на вопрос гостя?","type":"single","options":["Сказать то, что первое придет в голову, главное - уверенно","Перевести тему","Уточнить у менеджера и вернуться с ответом"]},{"id":"92988-8","text":"Где уточнить, разрешён ли аксессуар для смены в твоём заведении?","type":"single","options":["По фотографиям команды","По памятке другой точки","По действующему стандарту формы своей точки, при сомнении у менеджера"]},{"id":"92988-9","text":"Перед открытием сломалось крепление аксессуара на форме. Что сделать?","type":"single","options":["Снять аксессуар и согласовать замену, если он обязателен","Оставить его до первого перерыва","Закрепить подручным способом и сразу выйти в зал"]},{"id":"92988-10","text":"Ты заметил, что гости за столом коллеги пытаются привлечь внимание. Как поступить?","type":"single","options":["Дождаться, пока коллега сам увидит гостей","Подойти, уточнить просьбу и передать её ответственному официанту","Сразу забрать стол и вести его до расчёта"]}],"trainingBrand":"90","timeLimitSeconds":300,"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"mergedIntoId":"100075"},"course_id":"waiter-standards","published":false,"department":null,"updated_at":"2026-11-17T15:01:20.703312+00:00","restaurant_id":null},"expectedUpdatedAt":"2026-11-17T15:01:20.703312+00:00"},{"record":{"id":"92993","kind":"test","title":"Тест 4. Чек бэк","payload":{"id":"92993","brand":"90","title":"Тест 4. Чек бэк","priority":"attestation","passCount":10,"questions":[{"id":"92993-1","text":"Зачем делать контрольный чек-бэк?","type":"single","options":["Сообщить об акциях","Закрепить положительное впечатление перед уходом","Уточнить сумму счета","Проверить, понравился ли официант"]},{"id":"92993-2","text":"Что такое Check Back (чек-бэк)?","type":"single","options":["Контроль за работой кухни","Проверка счета гостя","Обратная связь с гостем о качестве еды и сервиса","Оценка работы персонала"]},{"id":"92993-3","text":"Когда официант должен делать текущий чек-бэк?","type":"single","options":["Через 2-3 минуты после первой вилки еды","Перед оплатой счета","После того, как гость полностью съел блюдо","Сразу после подачи блюда"]},{"id":"92993-4","text":"Как лучше всего задавать вопросы гостю во время чек-бэка?","type":"single","options":["Ограничиваться «Всё ок?»","С искренним интересом, без шаблонных фраз","Чётко и официально","Быстро и без эмоций"]},{"id":"92993-5","text":"Что делать, если гость не в восторге от твоей рекомендации?","type":"single","options":["Переубедить его","Посоветовать что-то другое","Принять спокойно и учесть для будущих советов","Спросить, почему он выбрал это блюдо"]},{"id":"92993-6","text":"Какой стиль общения рекомендуется при чек-бэке?","type":"single","options":["Формальный и строгий","Минимальный, без эмоций","Дружеский, искренний, ненавязчивый","Только при необходимости"]},{"id":"92993-7","text":"Что делать, если гость недоволен блюдом?","type":"single","options":["Выяснить причину и сообщить менеджеру","Сказать, что так и должно быть","Извиниться и уйти","Заменить блюдо без уведомления"]},{"id":"92993-8","text":"Гость уже попробовал блюдо. Какая реплика поможет получить конкретную обратную связь?","type":"single","options":["«Как вам прожарка и температура блюда?»","«Всё в порядке?»","«Вы ведь довольны блюдом?»"]},{"id":"92993-9","text":"Когда официант делает поэтапный чек-бэк?","type":"single","options":["После выдачи чека","До подачи блюда","Когда убирает тарелку у гостя","В начале смены"]},{"id":"92993-10","text":"Что делать, если гость не доел блюдо?","type":"single","options":["Немедленно предложить другое блюдо","Спросить причину ненавязчиво","Просто забрать тарелку","Ничего не делать"]}],"trainingBrand":"90","timeLimitSeconds":300,"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"mergedIntoId":"100159"},"course_id":"waiter-standards","published":false,"department":null,"updated_at":"2026-11-17T15:01:20.706364+00:00","restaurant_id":null},"expectedUpdatedAt":"2026-11-17T15:01:20.706364+00:00"},{"record":{"id":"92995","kind":"test","title":"Тест 3. Обслуживание гостей","payload":{"id":"92995","brand":"90","title":"Тест 3. Обслуживание гостей","priority":"attestation","passCount":7,"questions":[{"id":"92995-1","text":"Как официант должен заходить к гостю?","type":"single","options":["Молча, ожидая, пока гость заговорит","Без эмоций, сразу подавая меню","С улыбкой и на позитиве, создавая атмосферу 90-х","Спокойно и официально"]},{"id":"92995-2","text":"Какой приём помогает увеличить продажу блюд?","type":"single","options":["Дать гостю меню и уйти, тогда он сам закажет все, что нужно","Описание блюд с эмоциями и аппетитными деталями","Просто назвать позиции из меню, гость разберется по ходу заказа"]},{"id":"92995-3","text":"Как официант должен сообщать о времени приготовления?","type":"single","options":["Обещать минимальное время","Говорить «скоро будет»","Сообщать только если спросят","Честно сказать реальное время"]},{"id":"92995-4","text":"Что делать, если гость остался недоволен блюдом?","type":"single","options":["Ничего, гость сам разберётся","Сказать, что так и должно быть","Извиниться и уйти","Выяснить причину и предложить решение"]},{"id":"92995-5","text":"Что важно сделать при подаче меню?","type":"single","options":["Подавать открытой рукой, предложить освежающий напиток","Спросить, хочет ли гость что-то заказать сразу","Оставить на столе без слов","Подать закрытым и уйти"]},{"id":"92995-6","text":"Как правильно проводить расчёт гостя?","type":"single","options":["Только при повторном запросе","Без задержек, уточнив тип оплаты","Подождать, пока гость напомнит"]},{"id":"92995-7","text":"Как правильно делать чек-бэк?","type":"single","options":["Делать чек-бэк только в конце вечера","Спросить «Всё в порядке?» и уйти","Проявлять искренний интерес, считывать эмоции гостя","Спрашивать только, если гость выглядит недовольным"]}],"trainingBrand":"90","timeLimitSeconds":210,"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"mergedIntoId":"100159"},"course_id":"waiter-standards","published":false,"department":null,"updated_at":"2026-11-17T15:01:20.697048+00:00","restaurant_id":null},"expectedUpdatedAt":"2026-11-17T15:01:20.697048+00:00"},{"record":{"id":"92998","kind":"test","title":"Тест 2. Открытие смены","payload":{"id":"92998","brand":"90","title":"Тест 2. Открытие смены","priority":"attestation","passCount":10,"questions":[{"id":"92998-1","text":"Как проверяется исправность терминала перед сменой?","type":"single","options":["Проверить только наличие ленты","Убедиться, что работает и есть чековая лента","Просто включить","Проверять только при необходимости"]},{"id":"92998-2","text":"Как должен выглядеть порядок в подсобке?","type":"single","options":["Проверяются только шкафчики","Обувь на полке, вещи на вешалке, ничего не валяется","Всё должно быть разложено","Проверка не требуется"]},{"id":"92998-3","text":"Что входит в обязательную проверку стейшена?","type":"single","options":["Проверка формы персонала","Терминалы и меню","Только салфетки","Полироль, тряпки, салфетки, сахар, зубочистки"]},{"id":"92998-4","text":"Какой инструмент помогает официанту держать всё под контролем при открытии смены?","type":"single","options":["Лист заказов","Чек-лист","Инструкция по безопасности","График смен"]},{"id":"92998-5","text":"Какие действия необходимо выполнить с входной группой?","type":"single","options":["Проверить ковёр","Оставить на проверку менеджеру","Проверить параметры: Чистота пола, подоконников, коврика, пепельницы, включение вентиляции","Протереть стекла"]},{"id":"92998-6","text":"Какое должно быть состояние меню при открытии зала?","type":"single","options":["Достаточно просто заменить грязные","Можно использовать даже слегка повреждённые меню","Меню не требует проверки","Чистое, без рваных страниц, протёртое влажной тряпкой"]},{"id":"92998-7","text":"При сервировке ты заметил на приборе следы еды. Что сделать?","type":"single","options":["Отполировать его салфеткой","Отложить до конца подготовки","Отправить прибор на повторную мойку и взять чистый"]},{"id":"92998-8","text":"Какой уровень наполнения соли и перца считается правильным?","type":"single","options":["Только если заканчивается","Полный","Наполовину","На ¾ емкости"]},{"id":"92998-9","text":"Какие элементы зала необходимо проверить перед открытием?","type":"single","options":["Пол, стулья, столы, подоконники","Только столы и салфетки","Только стулья","Только терминалы"]},{"id":"92998-10","text":"Что должно быть в идеальном порядке в гостевом туалете?","type":"single","options":["Мыло, полотенца, смыв, чистота","Только сантехника","Только чистота пола","Только наличие туалетной бумаги"]}],"trainingBrand":"90","timeLimitSeconds":300,"requiredRestaurantIds":["pushkino","khimki","mytishchi"],"mergedIntoId":"100153"},"course_id":"waiter-standards","published":false,"department":null,"updated_at":"2026-11-17T15:01:20.697307+00:00","restaurant_id":null},"expectedUpdatedAt":"2026-11-17T15:01:20.697307+00:00"},{"record":{"id":"rvb--waiter-internship","kind":"course","title":"Руки ВВерх! Бар · Стандарты и стажировка официанта","course_id":null,"published":true,"department":null,"updated_at":"2026-11-17T15:01:19.443047+00:00","restaurant_id":"minsk","payload":{"id":"rvb--waiter-internship","kind":"internship","pass":80,"brand":"rvb","title":"Руки ВВерх! Бар · Стандарты и стажировка официанта","outline":[{"type":"lesson","id":"122794","title":"Критерии оценки официанта: на что смотрят наставники и менеджеры 📋"},{"type":"lesson","id":"114183","title":"Смена 1. Погружение в атмосферу"},{"id":"rvb--100075","type":"test"},{"type":"lesson","id":"114185","title":"Смена 2. Врываемся в движ"},{"id":"rvb--100153","type":"test"},{"type":"lesson","id":"114188","title":"Смена 3. Первый выход в зал — наблюдаем и учимся у наставника 🎭"},{"id":"rvb--100159","type":"test"},{"type":"lesson","id":"114189","title":"Смена 4. Теперь ты в теме"},{"id":"rvb--100172","type":"test"},{"type":"lesson","id":"114190","title":"Смена 5. Совместный трек с кухней"},{"id":"rvb--104138","type":"test"},{"type":"lesson","id":"114191","title":"Смена 6. Включай iiko"},{"id":"rvb--104142","type":"test"},{"type":"lesson","id":"114192","title":"Смена 7. Практика в действии"},{"id":"rvb--104144","type":"test"},{"id":"rvb-waiter-diary-kitchen","type":"test"},{"id":"rvb-waiter-diary-bar","type":"test"},{"type":"lesson","id":"114193","title":"Смена 8. Всё под контролем"},{"id":"rvb--104160","type":"test"},{"type":"lesson","id":"114194","title":"Смена 9. Вайб, кэш и харизма"},{"id":"rvb--104161","type":"test"},{"type":"lesson","id":"114195","title":"Смена 10. Режим штурма"},{"id":"rvb--104181","type":"test"},{"id":"rvb-waiter-diary-wine","type":"test"},{"type":"lesson","id":"114197","title":"Смена 11. Выход на большую сцену"},{"id":"rvb--104187","type":"test"},{"type":"lesson","id":"114198","title":"Смена 12. Чисто, чётко, по стилю"},{"id":"rvb--104335","type":"test"},{"id":"rvb-waiter-diary-cocktails","type":"test"},{"type":"lesson","id":"114199","title":"Смена 13. Теперь ты — наставник"},{"id":"rvb--104337","type":"test"},{"type":"lesson","id":"114200","title":"Смена 14. Первый сольник"},{"id":"rvb--104338","type":"test"},{"type":"lesson","id":"114201","title":"Смена 15. Финальный трек"},{"type":"lesson","id":"114202","title":"Смена 16. Выпускной"}],"testIds":["rvb--100075","rvb--100153","rvb--100159","rvb--100172","rvb--104138","rvb--104142","rvb--104144","rvb--104160","rvb--104161","rvb--104181","rvb--104187","rvb--104335","rvb--104337","rvb--104338","rvb-waiter-diary-bar","rvb-waiter-diary-cocktails","rvb-waiter-diary-kitchen","rvb-waiter-diary-wine"],"priority":"start","sequence":[{"type":"lesson","id":"122794","title":"Критерии оценки официанта: на что смотрят наставники и менеджеры 📋"},{"type":"lesson","id":"114183","title":"Смена 1. Погружение в атмосферу"},{"id":"rvb--100075","type":"test"},{"type":"lesson","id":"114185","title":"Смена 2. Врываемся в движ"},{"id":"rvb--100153","type":"test"},{"type":"lesson","id":"114188","title":"Смена 3. Первый выход в зал — наблюдаем и учимся у наставника 🎭"},{"id":"rvb--100159","type":"test"},{"type":"lesson","id":"114189","title":"Смена 4. Теперь ты в теме"},{"id":"rvb--100172","type":"test"},{"type":"lesson","id":"114190","title":"Смена 5. Совместный трек с кухней"},{"id":"rvb--104138","type":"test"},{"type":"lesson","id":"114191","title":"Смена 6. Включай iiko"},{"id":"rvb--104142","type":"test"},{"type":"lesson","id":"114192","title":"Смена 7. Практика в действии"},{"id":"rvb--104144","type":"test"},{"id":"rvb-waiter-diary-kitchen","type":"test"},{"id":"rvb-waiter-diary-bar","type":"test"},{"type":"lesson","id":"114193","title":"Смена 8. Всё под контролем"},{"id":"rvb--104160","type":"test"},{"type":"lesson","id":"114194","title":"Смена 9. Вайб, кэш и харизма"},{"id":"rvb--104161","type":"test"},{"type":"lesson","id":"114195","title":"Смена 10. Режим штурма"},{"id":"rvb--104181","type":"test"},{"id":"rvb-waiter-diary-wine","type":"test"},{"type":"lesson","id":"114197","title":"Смена 11. Выход на большую сцену"},{"id":"rvb--104187","type":"test"},{"type":"lesson","id":"114198","title":"Смена 12. Чисто, чётко, по стилю"},{"id":"rvb--104335","type":"test"},{"id":"rvb-waiter-diary-cocktails","type":"test"},{"type":"lesson","id":"114199","title":"Смена 13. Теперь ты — наставник"},{"id":"rvb--104337","type":"test"},{"type":"lesson","id":"114200","title":"Смена 14. Первый сольник"},{"id":"rvb--104338","type":"test"},{"type":"lesson","id":"114201","title":"Смена 15. Финальный трек"},{"type":"lesson","id":"114202","title":"Смена 16. Выпускной"}],"positions":["Официант","Администратор зала","Хостес"],"questions":[],"coverLabel":"Стандарты и стажировка официанта","shortTitle":"Стандарты и стажировка","departments":["Зал"],"description":"Единая база сервиса и 16 практических смен с наставником. Открытие зала, обслуживание, iiko, продажи и подготовка к аттестации.","restaurantIds":["minsk"],"trainingBrand":"rvb","audienceLevels":["trainee","certified"],"trainingSourceId":"waiter-internship","audiencePositions":["Официант","Администратор зала"],"audiencePriorities":{},"requiredRestaurantIds":["minsk"],"lessons":[{"id":"122794","title":"Критерии оценки официанта: на что смотрят наставники и менеджеры 📋","blocks":[{"id":"course-122794-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-0-0.jpg","label":"Стандарты и стажировка официанта","title":"Критерии оценки официанта: на что смотрят наставники и менеджеры 📋"},{"id":"course-122794-2","html":"<p>Привет, стажёр! 👋</p><p>Чтобы ты чётко понимал, к чему стремиться и как оценивают твою работу, мы создали Контрольный лист наблюдения (КЛН). Это свод стандартов, по которым каждый официант проверяется в течение смены и на финальной аттестации.</p><p>Ознакомься с ним в самом начале стажировки и возвращайся к нему после каждой смены, чтобы видеть свой прогресс. Твоя цель – к 16‑й смене набрать не менее 85% от максимального балла. Поехали! 🚀</p>","type":"text"},{"id":"course-122794-3","text":"Как оцениваются критерии?","type":"heading","level":2},{"id":"course-122794-4","text":"Каждый пункт оценивается по простой шкале:","type":"heading","level":3},{"id":"course-122794-5","type":"list","items":["1 балл – выполнено идеально, соответствует стандарту","0,5 балла – выполнено частично, есть мелкие недочёты","0 баллов – не выполнено или выполнено с грубыми ошибками"],"ordered":false},{"id":"course-122794-6","text":"После проверки все баллы суммируются и переводятся в проценты по формуле:","type":"heading","level":3},{"id":"course-122794-7","type":"list","items":["Итоговый результат = (сумма набранных баллов ÷ 29) × 100%","Максимум – 29 баллов (100%). Минимальный проходной порог – 85%."],"ordered":false},{"id":"course-122794-8","text":"Полный список критериев КЛН","type":"heading","level":2},{"id":"course-122794-9","text":"1. Общие стандарты","type":"heading","level":3},{"id":"course-122794-10","text":"2. Шаг 1 – Приветствие","type":"heading","level":3},{"id":"course-122794-11","text":"3. Шаг 2 – Принятие заказа","type":"heading","level":3},{"id":"course-122794-12","text":"4. Шаг 3 – Сервировка, подача блюд и напитков","type":"heading","level":3},{"id":"course-122794-13","text":"5. Шаг 4 – Check-back и дополнительный сервис","type":"heading","level":3},{"id":"course-122794-14","text":"6. Шаг 5 – Расчёт и прощание","type":"heading","level":3},{"id":"course-122794-15","src":"assets/extra-courses/waiter-internship-0-1.jpg","type":"image","caption":""},{"id":"course-122794-16","src":"assets/extra-courses/waiter-internship-0-2.jpg","type":"image","caption":""},{"id":"course-122794-17","src":"assets/extra-courses/waiter-internship-0-3.jpg","type":"image","caption":""},{"id":"course-122794-18","src":"assets/extra-courses/waiter-internship-0-4.jpg","type":"image","caption":""},{"id":"course-122794-19","src":"assets/extra-courses/waiter-internship-0-5.jpg","type":"image","caption":""},{"id":"course-122794-20","src":"assets/extra-courses/waiter-internship-0-6.jpg","type":"image","caption":""},{"id":"course-122794-21","text":"Как использовать этот лист в стажировке","type":"heading","level":2},{"id":"course-122794-22","type":"list","items":["1. В начале курса – прочитай все пункты, чтобы понимать, к чему мы идём."],"ordered":false},{"id":"course-122794-23","text":"2. В каждой смене – мы будем давать небольшие отсылки к КЛН, например:","type":"heading","level":3},{"id":"course-122794-24","type":"list","items":["«Сегодня тренируем критерии 14.0, 18.0, 21.0»","Это поможет тебе фокусироваться на конкретных навыках.","3. Наблюдай за наставником – отмечай, как он выполняет те или иные пункты. Учись на его примере.","4. В конце смены можешь попросить наставника предварительно оценить тебя по 2–3 пунктам, чтобы понимать свой прогресс.","5. Перед 16‑й сменой (обслуживание администрации) повтори все пункты – это будет твой финальный экзамен."],"ordered":false},{"id":"course-122794-25","text":"Что означают баллы в реальной работе","type":"heading","level":2},{"id":"course-122794-26","html":"<p>29 баллов – идеальный официант, гордость команды. Стремись к этому, но помни, что идеал недостижим, можно всегда расти.</p><p>25–28 баллов – отличный результат, ты уверенно держишь стандарты.</p><p>20–24 балла – хорошая база, есть над чем работать. Обрати внимание на пункты с низкими оценками.</p><p>Ниже 20 – нужно серьёзно подтянуть знания и навыки, не стесняйся просить помощи у наставника.</p><p>Успехов! Этот лист – твой навигатор в мире профессионального сервиса. Держи его в голове, и ты быстро станешь настоящим профи. 🔥</p>","type":"text"},{"id":"course-122794-27","url":"https://golnk.ru/J0xy0","text":"Контрольный лист наблюдения (КЛН).","type":"link"}]},{"id":"114183","title":"Смена 1. Погружение в атмосферу","blocks":[{"id":"course-114183-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-1-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 1. Погружение в атмосферу"},{"id":"course-114183-2","text":"Привет, новичок! 👋","type":"heading","level":2},{"id":"course-114183-3","html":"<p>Сегодня твой первый день в нашем баре — месте, где живёт дух 90-х💿, играет настоящая музыка🎶 и гости приходят не просто выпить, а отмотать время назад✨</p><p>Не спеши бежать за подносом — сегодня тебе важно впитать атмосферу, понять, как тут всё устроено, и познакомиться с командой 💪👯‍♀️</p><p>Добро пожаловать в семью — теперь ты часть настоящей эпохи!😉</p>","type":"text"},{"id":"course-114183-4","text":"Экскурсия по бару 🍸","type":"heading","level":2},{"id":"course-114183-5","html":"<p>Начни с прогулки по территории — ведь теперь это твой второй дом. 🏠✨</p>","type":"text"},{"id":"course-114183-6","text":"Загляни в каждое место, куда обычно гости не попадают:","type":"heading","level":3},{"id":"course-114183-7","type":"list","items":["🍸 Барная стойка — сердце нашего заведения.","👨‍🍳 Кухня — тут творится настоящая магия.","📦 Склады и раздевалка — без них бар бы не жил.","🚻 Санузлы — чистота и порядок важны даже там.","Присмотрись, как всё устроено!"],"ordered":false},{"id":"course-114183-8","text":"Правила игры 🎮","type":"heading","level":2},{"id":"course-114183-9","html":"<p>Каждое заведение живёт по своим законам — и у нас тоже есть свои.</p>","type":"text"},{"id":"course-114183-10","text":"⬇️Сегодня ты узнаешь про:","type":"heading","level":3},{"id":"course-114183-11","type":"list","items":["Внешний вид — у нас не скучно, но аккуратно. Опрятность — часть стиля.","Распорядок дня — когда приходить, где отмечаться и когда можно перекусить.","Регламенты — как носить униформу, как здороваться с гостями и что делать, если что-то пошло не по плану.","В 90-х каждый хотел выделиться. Главное — делай это со вкусом😉"],"ordered":false},{"id":"course-114183-12","text":"Внешний вид 😎","type":"heading","level":2},{"id":"course-114183-13","html":"<p>Наш официант — не просто человек с подносом. Он — часть шоу, моторчик движа и главный носитель атмосферы💫</p><p>Разберёмся, как именно должен выглядеть и чувствовать себя человек, который встречает гостей под хиты 90-х. Ты не должен быть моделью с обложки📖, но выглядеть свежо, бодро и уверенно💪 — обязательно.</p>","type":"text"},{"id":"course-114183-14","text":"✅ Вот чек-лист внешнего вида:","type":"heading","level":3},{"id":"course-114183-15","type":"list","items":["Чистая кожа (а если где-то «неидеал» — \"штукатурка\" в помощь 😎).","Уложенные волосы — никаких \"я только проснулся\".","Ухоженные руки и ногти — они в кадре чаще, чем ты думаешь.","Лёгкий аромат, без передоза парфюмом — гости пришли наслаждаться коктейлями, а не духами.","У нас не просто форма — у нас стиль эпохи.","Джинсовки, яркие цвета, цепочки, браслеты, резинки, чокеры — всё, что отсылает к 90-м, приветствуется❗","Главное — чисто, аккуратно и со вкусом. Если вид неопрятный, гость подумает, что и коктейль у нас такой же — «вчерашний». А нам такое не надо 😉"],"ordered":false},{"id":"course-114183-16","text":"🎉 Для нас ты — вайб:","type":"heading","level":3},{"id":"course-114183-17","type":"list","items":["⚡ Главный моторчик движа. Без тебя вечеринка не взлетит.","😄 Весёлый друг, которому не по барабану, что происходит в зале.","💖 Фанат заведения, который сам кайфует от атмосферы и заражает ею гостей.","Когда гость чувствует, что ты в потоке, он возвращается. Не потому что скидка, а потому что тут кайф!🥳","Будь симпатягой, стильным и уверенным.","Смотри в зеркало и спрашивай себя: «Я бы заказал у себя коктейль?».","Если ответ «да» — ты готов к смене💫"],"ordered":false},{"id":"course-114183-18","text":"Распорядок дня ⌚","type":"heading","level":2},{"id":"course-114183-19","html":"<p>Приход на работу</p>","type":"text"},{"id":"course-114183-20","text":"Время выхода и готовность зала","type":"heading","level":3},{"id":"course-114183-21","type":"list","items":["В РВБ Минск с воскресенья по четверг приходи к 16:00, в пятницу и субботу — к 15:30. Зал должен быть готов к 16:45.","Если на конкретную смену согласован особый график, уточни его у менеджера.","Если к согласованному времени зал готов, но терминал не работает, сообщи старшему и уточни порядок расчётов до устранения сбоя.","⏰ Опаздываешь? Проблема!","Заранее предупреди менеджера, если не успеваешь. Опоздания сбивают ритм и портят атмосферу💫","Здесь важен командный дух, поэтому подводить своих — не вариант👎","Если заранее нашёл себе замену — молодец 👍","Но всё равно сообщи менеджеру.","Короткий перерыв","Время перерыва зависит от загрузки и правил точки.","Согласуй короткий перерыв со старшим. Передай столы конкретному коллеге и убедись, что он принял подмену. Сообщи, что уже заказано, чего ждут гости и о чём они просили.","🚫 Не ходи курить толпой — ты же не на перемене в школе!","🌿 После перекура — жвачка или спрей для свежести.","Общение с гостями","Всегда улыбаемся!😊 Даже если день не задался — твоя улыбка делает атмосферу.","Используй лёгкий сленг 90-х💬 — гости сразу чувствуют вайб ностальгии.","Если что-то не знаешь❓ — уточни у менеджера. Если возник вопрос в разговоре с гостем — скажи, что уточнишь и вернёшься с ответом.","Держим лицо в любой ситуации😎 : даже если гость капризный — решаем всё с позитивом и юмором.","📚 Это ещё не все правила, которые тебе нужно знать.","❗ Загляни в Библиотеку — там тебя ждут «Правила сотрудника на смене»."],"ordered":false},{"id":"course-114183-22","text":"Структура зала 🗺️","type":"heading","level":2},{"id":"course-114183-23","text":"Каждый официант должен знать свой зал как свои пять ✋ пальцев:","type":"heading","level":3},{"id":"course-114183-24","type":"list","items":["изучи структуру и планировку💭 — где служебные зоны и основные проходы.","запомни нумерацию столов 🔢 — это поможет быстро ориентироваться и обслуживать без суеты.","разберись, какие зоны и столы закреплены за тобой🪑 — чтобы всегда быть на своём месте и держать ситуацию под контролем."],"ordered":false},{"id":"course-114183-25","src":"https://rvbarminsk.by/content/img/plan-s.jpg","type":"image","caption":"План зала РВБ Минск"},{"id":"course-114183-28","text":"Концепция и вайб 💫","type":"heading","level":2},{"id":"course-114183-29","html":"<p>💿Наш бар — не просто место с коктейлями. Это машина времени в 90-е✨</p><p>😎Музыка, напитки, выражения — всё из той эпохи. Гости приходят сюда не просто отдохнуть — они погружаются в ностальгию, чтобы снова почувствовать тот драйв⚡</p><p>❗Твоя задача — не только принести заказ, но и поддержать атмосферу: 😊 улыбка, 😏 лёгкая шутка,🕶️ свой стиль общения — всё это делает вечер по-настоящему улётным.</p><p>🎶 Почувствуй ритм бара, улови настроение — от этого зависит, как тебя воспримут гости.</p>","type":"text"},{"id":"course-114183-30","text":"Учись у старших 👀","type":"heading","level":2},{"id":"course-114183-31","text":"Сегодня твой главный инструмент — глаза и уши. Смотри внимательно, как работает твой наставник:","type":"heading","level":3},{"id":"course-114183-32","type":"list","items":["👋 Как он встречает гостей","👐 Как держит поднос и двигается по залу","⚡ Как реагирует, если что-то идёт не по плану","❗Не бойся задавать вопросы — даже самые простые.","Здесь никто не родился с подносом в руке, но каждый может стать гуру сервиса💪"],"ordered":false},{"id":"merged-rvb---1","type":"heading","text":"Правила общения и работы в команде","level":2},{"id":"merged-rvb---2","type":"text","html":"<p>Создавай атмосферу заведения и подстраивай тон под гостя. Если он не поддерживает шутки, общайся спокойно и доброжелательно. Если не знаешь ответа, уточни у менеджера и обязательно вернись к гостю.</p><p>Перед перерывом согласуй уход со старшим и передай столы конкретному коллеге. Сообщи, что заказано, чего ждут гости и какие у них просьбы. Убедись, что подмену приняли. Не уходите всей командой одновременно. О задержке или замене заранее сообщи менеджеру.</p><p>Проверь форму, обувь, волосы и руки перед выходом. Форма должна быть чистой и опрятной. Во время смены замени испачканный элемент, а сломанный аксессуар сними и согласуй замену, если он обязателен. Допустимые аксессуары уточняй по стандарту своей точки. Парфюм не должен быть резким.</p><p>Замечай просьбы гостей за соседними столами: уточни просьбу и передай ответственному официанту. Гость должен чувствовать внимание всей команды.</p>"},{"id":"merged-roles-rvb--0","type":"list","items":["Главный моторчик движа, без которого не будет улетной атмосферы.","Веселый друг, которому не фиолетово, что происходит в зале – он понимает, что всё зависит от него.","Человек, который сам тащится от заведения и заряжает этой любовью гостей. Они возвращаются снова и снова, потому что здесь кайф!"],"ordered":false},{"id":"merged-roles-rvb--1","type":"list","items":["Эмоции: Лучший друг","Свой в доску, всегда на позитиве, улыбается и создаёт уютную атмосферу домашнего праздника.","Личностные качества: Радушный хозяин","Внимательный – сразу видит, что нужно гостю, и приносит это моментально.","Честный – никаких мутных тем, репутация заведения на кону.","Держит лицо – даже если устал или день не задался, гостю этого видеть не положено.","Не сыплет негативом – бар должен быть местом кайфа, а не разборок.","Разруливает конфликты ещё до того, как они завелись.","Открытый – сам заводит разговор, легко общается, помогает выбрать блюдо.","Профнавыки: Знает и умеет","Разбирается в меню как настоящий профи: знает, что вкусное, как готовят, за сколько минут принесут.","Мастер подачи: напитки и блюда на столе всегда быстро, красиво и в правильном порядке.","Чек закроет в два счёта, а стол поддержит в идеальной чистоте"],"ordered":false}]},{"id":"114185","title":"Смена 2. Врываемся в движ","blocks":[{"id":"course-114185-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-2-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 2. Врываемся в движ"},{"id":"course-114185-2","text":"Расстановка столов и сервировка 🍽️","type":"heading","level":2},{"id":"course-114185-3","html":"<p>Вчера ты познакомился с атмосферой💫 и командой, а сегодня — врываемся в работу с головой🚀</p><p>Изучи схему зала — где какие столы, какие виды, какие гости любят сидеть где.</p><p>Сегодня наставник покажет, как правильно расставить приборы, салфетки, бокалы и специи😉</p><p>❗Обязательно загляни в раздел Библиотека, найдешь там важные файлы: \"Правила сотрудника на смене\", \"Распределение чаевых\".</p><p>✅Изучи их.</p>","type":"text"},{"id":"course-114185-4","text":"Открытие смены ⏰","type":"heading","level":2},{"id":"course-114185-5","html":"<p>❗Открытие зала</p><p>🧾Чек-лист – твой лучший инструмент, чтобы держать всё под контролем! Это список вещей, которые нельзя пропустить при открытии смены.</p><p>Мебель. Опустить стулья, выровнять мебель, почистить ее средством, протереть подножья столов и стульев</p><p>Столы. Протереть их чистой влажной тряпкой</p><p>Засервировать столы. Постановочная тарелка, столовые приборы (нож, вилка), хайбол, тейблтенты с актуальной информацией, салфетница, текстильная салфетка. Чистые вымытые приборы высушиваем и полируем чистой предназначенной для этого салфеткой</p><p>Проверить и заполнить расходники в стейшене, также в стейшенах всегда должна быть чистая вода в ведре для уборки столов</p><p>Привести в порядок декор зала, протереть пыль</p><p>Расставить таблички с надписями на барный стол</p><p>Всё в порядке? Значит, ты готов к улётной смене! 🚀</p>","type":"text"},{"id":"course-114185-6","text":"Акции 💥","type":"heading","level":2},{"id":"course-114185-7","html":"<p>Перед сменой уточни у менеджера, какие предложения действуют сегодня в твоей точке. Перед обещанием гостю проверь сроки, ограничения, совместимость со скидками и доступные способы оплаты.</p><p>На брифинге уточни, как применить предложение в iiko и к кому обратиться, если условия непонятны.</p>","type":"text"},{"id":"course-114185-8","text":"Меню и барная карта 📖","type":"heading","level":2},{"id":"course-114185-9","html":"<p>📖 Меню — это твой главный инструмент и визитка бара. Гость может простить долгую подачу, но не простит, если официант не знает, что у него в меню 😉</p><p>📚 Чтобы разбираться в блюдах и напитках, зайди в раздел “Меню” и внимательно изучи его. Там собраны Основное меню и Барная карта — с описаниями, составом и подачей.</p><p>⚡ Помни: меню периодически обновляется, и все новости об изменениях выходят прямо на платформе. Следи за обновлениями, чтобы не оказаться в ситуации, когда гость знает больше, чем ты.</p><p>🧠 И ещё: периодически проходи тесты на знание меню. Это не формальность, а способ держать себя в тонусе и быть профи, которому доверяют и коллеги, и гости.</p>","type":"text"},{"id":"course-114185-10","text":"Закрытие смены 🌙","type":"heading","level":2},{"id":"course-114185-11","html":"<p>Когда музыка стихает, начинается магия🔮 — закрытие смены.</p><p>Тут каждый должен быть в теме: убрать зал, собрать посуду, протереть столы, привести бар в порядок.</p><p>🧼 Делай так, чтобы утром всё выглядело как после клипа MTV — чисто, блестяще, готово к новому дню.</p><p>✅Наставник покажет все шаги — от кассы до последнего бокала.</p><p>❗Главное — не халтурь, это уважение к команде и к себе.</p>","type":"text"},{"id":"merged-rvb---3","type":"heading","text":"Контроль перед открытием","level":2},{"id":"merged-rvb---4","type":"text","html":"<p>Проверь входную группу, пол, подоконники, коврик, пепельницы и вентиляцию; в зале — столы, стулья, декор и чистоту поверхностей. В гостевом туалете проверь чистоту, смыв, мыло и полотенца. В подсобке обувь стоит на полках, вещи висят на вешалках.</p><p>Проверь исправность терминала и наличие чековой ленты. Меню должно быть чистым, целым и актуальным. В стейшене должны быть тряпки, полироль, салфетки, сахар и зубочистки. Соль и перец пополняй до ¾ ёмкости.</p><p>Чистые приборы после мойки вытри и отполируй предназначенной для этого чистой салфеткой. Прибор со следами еды отправь на повторную мойку. Не заменяй мойку полировкой.</p><p>Подробный порядок закрытия смены — в смене 12. Сегодня ознакомься с ним вместе с наставником.</p>"}]},{"id":"114188","title":"Смена 3. Первый выход в зал — наблюдаем и учимся у наставника 🎭","blocks":[{"id":"course-114188-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-3-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 3. Первый выход в зал — наблюдаем и учимся у наставника 🎭"},{"id":"course-114188-2","text":"Обслуживание гостей 👥","type":"heading","level":2},{"id":"course-114188-3","html":"<p>Ты прошёл первые 2️⃣ дня и уже чувствуешь ритм бара. Сегодня — первый выход в зал! Но не переживай, ты не один. Твоя задача — наблюдать за наставником, учиться и помогать. Никакой самостоятельности — только работа в паре. 🤝</p><p>Учиться шагам обслуживания, наблюдая за наставником</p><p>Разобраться, что такое стоп-лист и как с ним работать</p><p>Под присмотром наставника/менеджера подавать и убирать блюда</p><p>К концу смены управляющий решит, готов ли ты двигаться дальше 💪</p>","type":"text"},{"id":"course-114188-4","text":"Как ты работаешь сегодня","type":"heading","level":2},{"id":"course-114188-5","src":"assets/extra-courses/waiter-internship-3-1.jpg","type":"image","caption":""},{"id":"course-114188-6","text":"Шаги обслуживания — наблюдаем и запоминаем 👀","type":"heading","level":2},{"id":"course-114188-7","html":"<p>Сегодня ты проходишь все шаги обслуживания, но в роли наблюдателя. Наставник показывает — ты смотришь, запоминаешь, задаешь вопросы.</p><p>ШАГ 1️⃣ — Приветствие</p><p>Врываемся с улыбкой! 😃</p><p>Заходим на позитиве – дарим гостю хорошее настроение с порога и представляемся!</p><p>Меню подаём открытой рукой</p><p>Бонус: пока гость листает меню, предлагай что-нибудь освежающее – сразу +1 к продажам!</p>","type":"text"},{"id":"course-114188-8","text":"❗Важно! Наблюдай:","type":"heading","level":3},{"id":"course-114188-9","type":"list","items":["Как наставник заходит с улыбкой","Как представляется гостям","Как подает меню (открытой рукой)","Предлагает ли что-то освежающее, пока гость изучает меню","Твоя задача: запомнить эти движения и фразы. В следующих сменах будешь делать сам.","ШАГ 2️⃣ — Прием заказа","Выясняем, чего душа хочет, помогаем выбрать блюда","Раскачиваем эмоции – аппетитные описания блюд, от которых слюнки потекут.","Бонус: «Хотите крутой гарнир или эксклюзивный соус к этому?» – больше вкуса, больше кайфа, больше продаж!","Время приготовления – если задержка, сразу говорим реальное время, гость будет благодарен за честность.","Повторяем заказ – чтобы не испортить впечатления от возможной ошибки!"],"ordered":false},{"id":"course-114188-10","text":"❗Важно! Сегодня ты НЕ принимаешь заказ. Ты просто стоишь рядом (чуть поодаль) и слушаешь, как это делает наставник.","tone":"yellow","type":"callout","title":""},{"id":"course-114188-11","text":"На что обратить внимание:","type":"heading","level":3},{"id":"course-114188-12","type":"list","items":["Какие вопросы задает наставник?","Как описывает блюда, чтобы гостю захотелось заказать?","Как уточняет детали (прожарка, соус, аллергии)?","Как повторяет заказ перед отправкой на кухню?","Бонус: Если наставник разрешит, можешь записывать заказ в блокнот для тренировки — но в систему вносит только наставник.","ШАГ 3️⃣ — Подача","Блюда подаём открытой рукой, как профессионалы.","Всё приносим синхронно – никто не ждёт, все довольны!","Первыми – закуски, потом горячее, затем десерты – чистый ритм сервиса!"],"ordered":false},{"id":"course-114188-13","text":"❗Важно:","type":"heading","level":3},{"id":"course-114188-14","text":"Под присмотром наставника ты можешь:","type":"heading","level":3},{"id":"course-114188-15","type":"list","items":["Помочь нести блюда к столу (но только если уверен, что не уронишь!)","Подать тарелку гостю (наставник показывает, с какой стороны, а ты пробуешь)","Следить, чтобы блюда подавались синхронно (холодное, горячее, десерты)"],"ordered":false},{"id":"course-114188-16","text":"Важно: Не берись за сложные подачи (например, горячие тарелки или несколько блюд сразу), пока наставник не скажет, что ты готов.","tone":"yellow","type":"callout","title":""},{"id":"course-114188-17","html":"<p>ШАГ 4️⃣ — Чек-бэк</p><p>«Ну как? Огонь?» – не просто спрашиваем, а реально чувствуем эмоции гостя!🔥</p><p>❗Если что-то не так – сразу решаем вопрос. Гасим возможные конфликты ещё до их появления.</p><p>Подробнее о чек бэке - ниже.</p>","type":"text"},{"id":"course-114188-18","text":"❗Важно! Наблюдай: Наставник подходит к гостям через 2–3 минуты после подачи и спрашивает, всё ли нравится. Слушай, как он это делает — не скучное «Всё ли в порядке?», а искренний интерес.","tone":"yellow","type":"callout","title":""},{"id":"course-114188-19","html":"<p>ШАГ 5️⃣ — Расчет</p><p>Гость попросил счёт? Не стоим, несём моментально!</p><p>Если в точке действует программа лояльности, уточни у гостя, пользуется ли он ей. Перед расчётом проверь условия акции и доступные способы оплаты.</p><p>«Наличные или карта, общий или раздельный?» – всё чётко, без лишних вопросов.</p>","type":"text"},{"id":"course-114188-20","text":"❗Важно! Наблюдай: Как наставник реагирует на просьбу о счете, как уточняет способ оплаты, как благодарит и прощается","tone":"yellow","type":"callout","title":""},{"id":"course-114188-21","html":"<p>ШАГ 6️⃣ — Прощание</p><p>«Спасибо, что заглянули, ждём снова!» – главное, чтобы звучало искренне.</p>","type":"text"},{"id":"course-114188-22","text":"Финальный аккорд:","type":"heading","level":3},{"id":"course-114188-23","type":"list","items":["Улыбка😊, кивок, возможно даже стильный жест рукой✋ – гость должен уходить с ощущением, что его реально ждали!","Пересервируем стол🍽️ за 2-3 минуты – новые гости уже на подходе!🔥"],"ordered":false},{"id":"course-114188-25","html":"<p>Уборка посуды 🧹</p>","type":"text"},{"id":"course-114188-26","text":"Под контролем наставника:","type":"heading","level":3},{"id":"course-114188-27","type":"list","items":["Учишься забирать пустые тарелки (с какой стороны, как не мешать)","Учишься правильно держать стопку тарелок (грязное не смешивать с чистым)","Учишься убирать бокалы (только за ножку!)"],"ordered":false},{"id":"course-114188-28","text":"Чек-бэк и его важность 💭","type":"heading","level":2},{"id":"course-114188-29","html":"<p>Check Back (чек-бэк) – это твой инструмент, чтобы понять, насколько гость доволен.</p><p>Вкусно ли ему❓</p><p>Всё ли ок с качеством блюд и напитков❓</p><p>Не нужно ли ему что-то еще (салфетки, соус, пепельница)❓</p><p>❗А ещё чек-бэк – это твой шанс предотвратить конфликт на ранней стадии!</p><p>💭 Как его делать?</p><p>После подачи блюд ждём немного времени, чтобы гость успел попробовать.</p><p>Подходим, спрашиваем, как ему еда.</p><p>Если гость недоволен – выясняем, в чём дело.</p><p>Если проблема из-за качества блюда (неправильно приготовлено, остывшее и т.д.), сообщаем менеджеру.</p><p>Менеджер решает, включать ли блюдо в счёт.</p>","type":"text"},{"id":"course-114188-30","text":"✨Виды чек-бэка:","type":"heading","level":3},{"id":"course-114188-31","type":"list","items":["✅ Текущий – быстрый фидбэк","Ждёшь 2-3 минуты после первой вилки еды.","Подходишь, если гость заказал твою рекомендацию или новинку."],"ordered":false},{"id":"course-114188-32","text":"Важно! Не перебиваем важную беседу, ждём удачного момента.","tone":"yellow","type":"callout","title":""},{"id":"course-114188-33","html":"<p>✅ Поэтапный – шаг за шагом</p><p>Спрашиваем мнение, когда убираем тарелку.</p><p>Если гость не доел – обязательно выясняем, почему.</p><p>Если гость не в восторге от твоей рекомендации – не паримся: «Да, вкусы у всех разные, зато теперь я знаю, что советовать вам в следующий раз!»</p><p>✅ Контрольный – закрепляем успех</p><p>Спрашиваем о впечатлениях, когда гость просит счёт.</p><p>Он ещё раз вспоминает, как классно провёл время.</p><p>Проговаривая впечатления, фиксирует их в памяти, а значит, захочет вернуться!</p>","type":"text"},{"id":"course-114188-34","text":"❗Важный момент:","type":"heading","level":3},{"id":"course-114188-35","type":"list","items":["Не спрашиваем скучные «Всё ли в порядке?» или «Вам что-то не нравится?» – такие вопросы не цепляют. Подходи к гостю с искренним интересом!","Какой чек-бэк использовать? Решай сам, пробуй разные варианты и найди тот, который работает для тебя лучше всего! 🚀"],"ordered":false},{"id":"course-114188-36","text":"Что такое стоп-лист? 📋🚫","type":"heading","level":2},{"id":"course-114188-37","html":"<p>Стоп-лист — это список блюд, которые временно недоступны (закончились ингредиенты, не успевают готовить и т.д.).</p><p>Где смотреть стоп-лист?</p><p>В iiko на главном экране (обычно есть кнопка или значок)</p><p>На кухне на специальном стенде</p><p>В рабочем чате (если повара пишут туда)</p><p>Что делать, если гость заказал блюдо из стоп-листа?</p>","type":"text"},{"id":"course-114188-38","text":"Наставник покажет, как правильно предложить альтернативу. Например:","type":"heading","level":3},{"id":"course-114188-39","type":"list","items":["«К сожалению, этого блюда сегодня нет, но могу порекомендовать...»"],"ordered":false},{"id":"course-114188-40","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114188-41","html":"<p>Задание 1. Тень наставника</p><p>Весь вечер ходи за наставником (не мешая ему). Наблюдай за каждым его действием. В голове прокручивай: «Почему он так сделал?», «Что бы я сделал по-другому?».</p><p>Задание 2. Помощь в простых задачах</p>","type":"text"},{"id":"course-114188-42","text":"Когда наставник дает добро:","type":"heading","level":3},{"id":"course-114188-43","type":"list","items":["Поднеси стаканы с водой","Убери пустую тарелку (под контролем)","Принеси салфетки, если просят","Задание 3. Изучение стоп-листа","В начале смены попроси наставника показать, где смотреть стоп-лист. В середине смены подойди и проверь, не появились ли новые позиции.","Задание 4. Вопросы наставнику"],"ordered":false},{"id":"course-114188-44","text":"В конце смены спроси:","type":"heading","level":3},{"id":"course-114188-45","type":"list","items":["«Что у меня сегодня получилось хорошо?»","«На что мне обратить внимание в следующий раз?»"],"ordered":false},{"id":"course-114188-46","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114188-47","html":"<p>Я видел, как наставник приветствует гостей 😃</p><p>Я слышал, как правильно принимать заказ 📝</p><p>Я помогал подавать блюда под контролем 🍽️</p><p>Я помогал убирать посуду 🧹</p><p>Я узнал, где смотреть стоп-лист 📋</p><p>Я получил обратную связь от наставника 📝</p>","type":"text"},{"id":"course-114188-48","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114188-49","html":"<p>...гость обратился напрямую к тебе?</p><p>Улыбнись и скажи: «Я пока стажер, сейчас позову [Имя наставника], он вам поможет». Не пытайся отвечать на сложные вопросы.</p><p>...ты чуть не уронил тарелку?</p><p>Не паникуй. Если удержал — выдохни. Если уронил — сразу позови наставника или уборщицу.</p><p>...тебе кажется, что наставник делает что-то не так?</p><p>Не критикуй вслух. Просто запомни и позже, в подходящий момент, спроси: «А почему ты так сделал?» — возможно, у этого есть причина.</p><p>...наставник занят, а гость зовет?</p><p>Скажи: «Одну минуту, я позову коллегу» — и иди за наставником.</p>","type":"text"},{"id":"course-114188-50","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114188-51","html":"<p>Сегодня ты не звезда, ты — тень звезды. И это нормально! Лучший способ научиться — смотреть на профессионала и делать как он. Не стесняйся задавать вопросы, будь полезным и внимательным.</p><p>К концу смены управляющий скажет, готов ли ты идти дальше. Не переживай, если не всё получилось сразу — мы все через это проходили. 😊</p><p>Ты справишься! Уже через пару смен ты будешь работать увереннее. 💪</p><p>Следующая смена — знакомство с баром и посудой. Готовься! 🍸</p>","type":"text"},{"id":"merged-rvb---5","type":"heading","text":"Границы полномочий при жалобе","level":2},{"id":"merged-rvb---6","type":"text","html":"<p>Выясни, что именно не понравилось, поблагодари за обратную связь и сообщи менеджеру. Не обещай скидку, замену или исключение блюда из счёта самостоятельно. Решение по счёту принимает менеджер. Подробный алгоритм работы с жалобой отработаешь в смене 9.</p>"}]},{"id":"114189","title":"Смена 4. Теперь ты в теме","blocks":[{"id":"course-114189-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-4-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 4. Теперь ты в теме"},{"id":"course-114189-2","text":"Бар — сердце движа 🍸","type":"heading","level":2},{"id":"course-114189-3","html":"<p>✨Сегодня ты переходишь на новый уровень — знакомишься с баром, оргструктурой команды и внутренней коммуникацией.</p><p>🥂Бар — это не просто место, где наливают. Это сцена, где рождаются эмоции и стиль заведения.</p><p>Старший бармен или бармен проведёт для тебя мини-тренинг. Ты узнаешь, какие напитки считаются “фирменными” и как бар работает в пиковые часы⌛</p><p>Ниже⬇️ ты познакомишься с посудой, которую используют наши бармены.</p><p>Запомни не только внешний вид бокалов, но и их назначение — это поможет уверенно принимать заказы и выглядеть профи в глазах гостей.</p>","type":"text"},{"id":"course-114189-4","text":"Бокалы и их назначение 🍷","type":"heading","level":2},{"id":"course-114189-5","html":"<p>Штоф 0.5 л.</p><p>Штоф - сосуд для крепких спиртных напитков например: водка, виски, ром, текила, джин, бренди.</p><p>Хайбол 295 мл.</p><p>Хайбол — Для холодных безалкогольных напитков и напитков из кувшина.</p><p>Дабл хайбол 450 мл.</p><p>Дабл хайбол — Для высоких коктейлей и лимонадов.</p><p>Кувшин 1 л.</p><p>Кувшин — Для подачи напитков на компанию.</p><p>Олд фэшн 345 мл.</p><p>Олд фэшн — Для подачи коктейлей со льдом.</p><p>Рокс 269 мл.</p><p>Рокс - бокал для подачи недорогого крепкого алкоголя (виски, ром), кроме водки, а также вермуты в чистом виде (бьянко, фиеро и т.д.).</p><p>Флютте 155 мл.</p><p>Флютте — Для подачи игристого вина.</p><p>Эклипс 470 мл.</p><p>Эклипс — Коктейльный бокал.</p><p>Винный бокал 385 мл.</p><p>Винный бокал - для вина, коктейлей.</p><p>Ревел Ап 500 мл.</p><p>Ревел Ап - форма бокала поможет напитку насытиться кислородом, что раскроет его вкус и аромат. Подходит для отдачи красного, белого и игристого вина, также подается к шампанскому.</p><p>Шалле 300 мл.</p><p>Шалле — Коктейльный бокал на ножке.</p><p>Тики бокалы 450 мл.</p><p>Тики бокалы — Керамические бокалы для тропических напитков.</p><p>Снифтер 398 мл.</p><p>Снифтер - для подачи бренди, коньяка, арманьяка и кальвадоса в чистом виде.</p><p>Коктейльная рюмка 190 мл.</p><p>Коктейльная рюмка - для охлажденных коктейлей среднего объема, но без льда. Не используется для подачи напитков со льдом и в чистом виде (в т.ч. и вермута Мартини, несмотря на название).</p><p>Маргаритка 250 мл.</p><p>Маргаритка — Коктейльный бокал с широкой чашей.</p><p>Кубок 300 мл.</p><p>Кубок - для горячих напитков (глинтвейна), т.к. у него толстые стенки.</p><p>Медная Кружка</p><p>Медная Кружка — Для подачи коктейлей в медной кружке.</p><p>Блюдца</p><p>Блюдца - большое под американо и капучино, маленькое под эспрессо.</p><p>Молочник</p><p>Молочник - предназначен для подачи сливок, молока, меда.</p><p>Чашка</p><p>Чашка - предназначена для американо, капучино и чая. Чашка маленького размера предназначена для эспрессо.</p><p>Шот 40 мл.</p><p>Шот - для крепких напитков (водка, ягермейтер) или коктейлей-шотов.</p><p>Френч-пресс</p><p>Френч-пресс - для заваривания чая или аналогичных напитков.</p><p>Подстаканник</p><p>Подстаканник — Для подачи напитка в стакане с подстаканником.</p>","type":"text"},{"id":"course-114189-6","src":"assets/extra-courses/waiter-internship-4-1.jpg","type":"image","caption":""},{"id":"course-114189-7","src":"assets/extra-courses/waiter-internship-4-2.jpg","type":"image","caption":""},{"id":"course-114189-8","src":"assets/extra-courses/waiter-internship-4-3.jpg","type":"image","caption":""},{"id":"course-114189-9","src":"assets/extra-courses/waiter-internship-4-4.jpg","type":"image","caption":""},{"id":"course-114189-10","src":"assets/extra-courses/waiter-internship-4-5.jpg","type":"image","caption":""},{"id":"course-114189-11","src":"assets/extra-courses/waiter-internship-4-6.jpg","type":"image","caption":""},{"id":"course-114189-13","src":"assets/extra-courses/waiter-internship-4-8.jpg","type":"image","caption":""},{"id":"course-114189-14","src":"assets/extra-courses/waiter-internship-4-9.jpg","type":"image","caption":""},{"id":"course-114189-15","src":"assets/extra-courses/waiter-internship-4-10.jpg","type":"image","caption":""},{"id":"course-114189-16","src":"assets/extra-courses/waiter-internship-4-11.jpg","type":"image","caption":""},{"id":"course-114189-17","src":"assets/extra-courses/waiter-internship-4-12.jpg","type":"image","caption":""},{"id":"course-114189-18","src":"assets/extra-courses/waiter-internship-4-13.jpg","type":"image","caption":""},{"id":"course-114189-19","src":"assets/extra-courses/waiter-internship-4-14.jpg","type":"image","caption":""},{"id":"course-114189-20","src":"assets/extra-courses/waiter-internship-4-15.jpg","type":"image","caption":""},{"id":"course-114189-21","src":"assets/extra-courses/waiter-internship-4-16.jpg","type":"image","caption":""},{"id":"course-114189-22","src":"assets/extra-courses/waiter-internship-4-17.jpg","type":"image","caption":""},{"id":"course-114189-23","src":"assets/extra-courses/waiter-internship-4-18.jpg","type":"image","caption":""},{"id":"course-114189-24","src":"assets/extra-courses/waiter-internship-4-19.jpg","type":"image","caption":""},{"id":"course-114189-25","src":"assets/extra-courses/waiter-internship-4-20.jpg","type":"image","caption":""},{"id":"course-114189-26","src":"assets/extra-courses/waiter-internship-4-21.jpg","type":"image","caption":""},{"id":"course-114189-27","src":"assets/extra-courses/waiter-internship-4-22.jpg","type":"image","caption":""},{"id":"course-114189-28","src":"assets/extra-courses/waiter-internship-4-23.jpg","type":"image","caption":""},{"id":"course-114189-29","src":"assets/extra-courses/waiter-internship-4-24.jpg","type":"image","caption":""},{"id":"course-114189-30","text":"Коммуникации и чаты 💬","type":"heading","level":2},{"id":"course-114189-31","text":"📱Сегодня тебя добавят в рабочие чаты, тебе нужно:","type":"heading","level":3},{"id":"course-114189-32","type":"list","items":["подписаться на ASK и внутренние группы,","ознакомиться с Правилами общения в чатах — там важно сохранять уважение, юмор и позитив, как и в реальной жизни.","💡Совет: будь корректен в сообщениях — это тоже часть твоего профессионализма."],"ordered":false}]},{"id":"114190","title":"Смена 5. Совместный трек с кухней","blocks":[{"id":"course-114190-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-5-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 5. Совместный трек с кухней"},{"id":"course-114190-2","text":"Меню, кухня и работа на раздаче","type":"heading","level":2},{"id":"course-114190-3","html":"<p>Сегодня ты выходишь на новый уровень — начинаешь разбираться в том, чем живет наша кухня и как устроена работа на раздаче. 🍳🔥</p><p>Кухня — это сердце ресторана ❤️. Именно здесь рождаются блюда, ради которых гости возвращаются снова и снова. А раздача — твой главный штаб в зале. 🏆</p><p>Ниже — всё, что нужно знать, чтобы уверенно ориентироваться в меню, контролировать качество блюд и всегда быть готовым к вопросам гостей. 👇</p>","type":"text"},{"id":"course-114190-4","text":"Акции","type":"heading","level":2},{"id":"course-114190-5","html":"<p>Перед сменой проверь актуальные условия у менеджера.</p><ul><li>«Днюха на хате у Жукова» — скидка до 50% на праздничные сеты, за семь дней до и семь дней после дня рождения.</li><li>«Караоке за счёт Жукова» — бесплатно ежедневно при бронировании стола.</li><li>«Дешевле чем дома» — блюда по 25 BYN. Список позиций смотри в действующем меню кухни.</li><li>«Банкет под ключ» — меню и программу подбирают по заявке.</li></ul><p><a href=\"https://rvbarminsk.by/akcii\">Акции РВБ Минск</a></p>","type":"text"},{"id":"course-114190-6","text":"Что уточнить на брифинге","type":"heading","level":3},{"id":"course-114190-7","type":"list","items":["Какие акции действуют сегодня и для каких гостей.","На какие позиции и в какое время они распространяются.","Можно ли сочетать их с бонусами и как их оформить в iiko."],"ordered":false},{"id":"course-114190-9","text":"Блюда на компанию","type":"heading","level":2},{"id":"course-114190-10","html":"<p>Уточни число гостей и их предпочтения. В действующем меню РВБ Минск посмотри «Памела Андерсон» (фруктовое ассорти), «Молчание ягнят» (мясное ассорти) и «Пивное плато „Бригада“» (горячие закуски). Перед рекомендацией проверь наличие, состав, выход и цену.</p><p>Если позиции нет, предложи гостям доступную альтернативу.</p>","type":"text"},{"id":"course-114190-12","text":"👀 Работа на раздаче. Как проверять внешний вид блюд","type":"heading","level":2},{"id":"course-114190-13","html":"<p>Ты — последний, кто видит блюдо перед тем, как оно попадет к гостю. Если что-то не так — верни поварам. Гость оценивает глазами в первую очередь. 👁️👁️</p><p>✅ Чек-лист перед подачей</p><p>Блюдо выглядит как на фото в меню 📸</p><p>Всё выложено аккуратно, без «каши» на тарелке ✨</p><p>Края тарелки чистые (нет соусов и крошек) 🧼</p><p>Гарниры и соусы на своих местах 🥗</p><p>Украшение свежее и уместное 🌿</p><p>Тарелка чистая снаружи (никаких отпечатков) 👆</p><p>⚠️ По этому же принципу проверяй все блюда. Если сомневаешься — позови наставника. 30 секунд задержки лучше, чем испорченное впечатление гостя. 👌</p>","type":"text"},{"id":"course-114190-15","text":"⏱️ Время приготовления","type":"heading","level":2},{"id":"course-114190-16","html":"<p>При высокой загрузке уточни актуальный ориентир на раздаче и сообщи его гостю до подтверждения заказа. Время в таблице — пример для тренировки.</p>","type":"text"},{"id":"course-114190-17","src":"assets/extra-courses/waiter-internship-5-4.jpg","type":"image","caption":""},{"id":"course-114190-18","text":"🧹 Расходники на раздаче. Твоя зона ответственности","type":"heading","level":2},{"id":"course-114190-19","html":"<p>Раздача — твой штаб. Здесь всегда должен быть порядок. 🧘</p>","type":"text"},{"id":"course-114190-20","text":"✅ Перед сменой и в течение вечера проверяй:","type":"heading","level":3},{"id":"course-114190-21","type":"list","items":["Бумажные салфетки — полные салфетницы + запас 📄","Влажные салфетки — обязательно, если в меню есть блюда для еды руками 💧","Соль и перец — мельницы полные и чистые 🧂","Зубочистки","Приборы (ножи, вилки, ложки) — в достатке 🍴","Чистые тарелки — разных размеров 🍽️","💡 Если салфетки закончились — доложи сразу. Не жди, пока гость попросит. ⏰"],"ordered":false},{"id":"course-114190-22","text":"🤝 Практика с наставником","type":"heading","level":2},{"id":"course-114190-23","html":"<p>🎯 Задание 1. Разбор меню</p>","type":"text"},{"id":"course-114190-24","text":"Подойди к наставнику и расскажи:","type":"heading","level":3},{"id":"course-114190-25","type":"list","items":["— Какие акции работают сегодня? 🎁","— Назови 3 блюда на компанию, состав и цену. 📋","— Сколько готовятся холодные закуски? А горячее? ⏱️","🎯 Задание 2. Раздача","Вместе подойдите к раздаче, когда готовится заказ. Найди 3 любых блюда из списка и проверь по чек-листу. Если найдешь косяк — попроси наставника показать, как правильно вернуть блюдо поварам. 👨‍🍳","🎯 Задание 3. Расходники"],"ordered":false},{"id":"course-114190-26","text":"Проверь станцию:","type":"heading","level":3},{"id":"course-114190-27","type":"list","items":["— Всё ли на месте? 🔍","— Чего не хватает? ❓","— Доложи наставнику, пополните запасы вместе. 🤲"],"ordered":false},{"id":"course-114190-28","text":"✅ Чек-лист: что ты забираешь с собой после этой смены","type":"heading","level":2},{"id":"course-114190-29","html":"<p>Я знаю все текущие акции 🎯</p><p>Могу назвать 5 топ-позиций из раздела «Блюда на компанию» 🏆</p><p>Помню время приготовления всех категорий ⏰</p><p>Умею проверять блюда перед подачей 👁️</p><p>Знаю, какие расходники должны быть на станции всегда 🧼</p><p>Прошел практику с наставником на раздаче 🤝</p><p>🎉 Отлично! Ты в теме.</p><p>Следующая смена — знакомимся с Iiko. Там будет интересно! 💻🔥</p>","type":"text"},{"id":"merged-rvb---7","type":"heading","text":"Состав и внешний вид блюд","level":2},{"id":"merged-rvb---8","type":"text","html":"<p>Открой актуальное <a href=\"https://askacademy.ru/#/menu?section=kitchen\">меню кухни своего заведения</a> в академии. Состав, подачу, цену и наличие проверяй по его действующим карточкам и стоп-листу смены.</p><p>Перед выдачей сверь блюдо, стол, модификаторы, комплектацию, внешний вид и температуру подачи. Если подача не соответствует карточке, сообщи на раздаче и не подавай блюдо до исправления.</p>"}]},{"id":"114191","title":"Смена 6. Включай iiko","blocks":[{"id":"course-114191-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-6-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 6. Включай iiko"},{"id":"course-114191-2","html":"<p>Привет! 👋 Сегодня ты осваиваешь главный рабочий инструмент — систему iiko. Ниже — понятная пошаговая инструкция: от входа в систему до расчета гостя. 📱💻</p>","type":"text"},{"id":"course-114191-3","text":"1. Вход в систему 🔑","type":"heading","level":2},{"id":"course-114191-4","html":"<p>На терминале (планшете или сенсорном мониторе) нажми на экран, чтобы выйти из режима ожидания. 👆</p><p>Перед тобой появится окно авторизации.</p><p>Прокати свою личную карту 🎫 (или введи PIN-код, если карта не считывается).</p><p>Ты попадаешь на главный экран iikoFront — обычно это схема зала или список столов. 🗺️</p><p>💡 Если карта не работает — позови наставника или менеджера. 🆘</p>","type":"text"},{"id":"course-114191-5","text":"2. Открытие заказа (новый гость) 🪑👥","type":"heading","level":2},{"id":"course-114191-6","html":"<p>На схеме зала нажми на номер стола, за который сели гости. 👆</p>","type":"text"},{"id":"course-114191-7","text":"Проверка занятости стола:","type":"heading","level":3},{"id":"course-114191-8","type":"list","items":["Если стол свободен, открой новый заказ и введи количество гостей. Нажми на поле с числом и выбери значение или введи его вручную.","Если заказ уже открыт, проверь, относится ли он к этим гостям. При сомнении обратись к менеджеру.","Если гость пользуется программой лояльности, проверь карту или профиль в iiko."],"ordered":false},{"id":"course-114191-13","text":"3. Добавление блюд в заказ","type":"heading","level":2},{"id":"course-114191-14","html":"<p>В левой части экрана — меню (поделено на группы: «Закуски», «Салаты», «Горячее», «Бар» и т.д.).</p><p>Нажимай на группы, чтобы найти нужное блюдо.</p><p>Нажми на название блюда — оно добавится в заказ.</p>","type":"text"},{"id":"course-114191-15","text":"Если нужно изменить количество:","type":"heading","level":3},{"id":"course-114191-16","type":"list","items":["Нажми на блюдо в правой части экрана (в списке заказа).","Появятся кнопки «+» (увеличить) и «−» (уменьшить)."],"ordered":false},{"id":"course-114191-17","text":"Если у блюда есть модификаторы","type":"heading","level":3},{"id":"course-114191-18","type":"list","items":["После добавления блюда автоматически откроется окно выбора.","Выбери нужный вариант и нажми ОК.","🔥 Важно: если не выбрал модификатор, а он обязательный — заказ не сохранится."],"ordered":false},{"id":"course-114191-19","text":"4. Отправка заказа на кухню (печать)","type":"heading","level":2},{"id":"course-114191-20","html":"<p>Когда все блюда добавлены, нажми кнопку «Печать» (обычно внизу экрана).</p><p>Блюда уходят на кухню, а на экране появится сообщение об успешной отправке.</p><p>После печати заказ становится «открытым» — ты можешь добавлять новые блюда (дозаказ).</p><p>⚠️ Если ошибочно добавил блюдо и оно еще не напечатано — просто нажми на него в заказе и выбери «Удалить». Если блюдо уже напечатано — зови наставника.</p>","type":"text"},{"id":"course-114191-21","text":"5. Просмотр заказа и добавление новых позиций 🔍➕","type":"heading","level":2},{"id":"course-114191-22","html":"<p>В любой момент ты можешь вернуться к столу, нажав на него на схеме зала. 👆</p><p>Чтобы добавить новые блюда — просто выбери их из меню и снова нажми «Печать» 🖨️</p><p>Система отправит на кухню только новые позиции. ✅</p>","type":"text"},{"id":"course-114191-23","text":"6. Расчет гостя (закрытие заказа) 💰🧾","type":"heading","level":2},{"id":"course-114191-24","text":"Когда гость просит счет:","type":"heading","level":3},{"id":"course-114191-27","type":"list","items":["Открой заказ на нужном столе.","Проверь позиции, количество и учёт депозита, если он предусмотрен условиями бронирования.","Нажми «Пречек» и покажи его гостю для проверки.","Уточни, как гость планирует оплатить счёт.","Позови менеджера для проведения оплаты и закрытия стола."],"ordered":true},{"id":"course-114191-30","text":"7. Накопительная система и скидки 🏷️✨","type":"heading","level":2},{"id":"course-114191-31","html":"<p>Проверь действующую программу лояльности своей точки и данные гостя в iiko, если условия зависят от его уровня. Назови подтверждённые условия начисления или списания. При сомнении уточни у менеджера.</p><p>Начисляй и списывай бонусы только в пределах своих полномочий. Если оформление требует согласования, передай данные менеджеру.</p>","type":"text"},{"id":"course-114191-32","text":"8. Возврат или удаление после оплаты ↩️❌","type":"heading","level":2},{"id":"course-114191-33","text":"Если ошибка обнаружилась уже после оплаты:","type":"heading","level":3},{"id":"course-114191-34","type":"list","items":["Не делай ничего самостоятельно. 🛑","Позови наставника или менеджера. 🆘","Они проведут операцию возврата или сторнирования. 🔄"],"ordered":false},{"id":"course-114191-35","text":"9. Закрытие стола 🔓","type":"heading","level":2},{"id":"course-114191-36","html":"<p>Закрытие стола выполняет менеджер. После того как менеджер завершит расчёт и гость уйдёт, стол на схеме зала освободится. Твоя задача — подготовить стол к следующей посадке (убрать, пересервировать).</p>","type":"text"},{"id":"course-114191-37","text":"❗️ Важно запомнить 🧠","type":"heading","level":2},{"id":"course-114191-38","html":"<p>Пречек — предварительный счёт для проверки гостем перед оплатой. Заказ на кухню и бар отправляется кнопкой «Печать».</p><p>Гостевой чек 🧾 — фискальный чек для гостя. 👤</p><p>Удалить блюдо после печати 🗑️ — только с разрешения наставника (и с причиной). 🆘</p><p>Скидки 🏷️ — применяются строго по правилам заведения. 📜</p><p>Если не знаешь, что делать — спроси наставника. 🙋‍♂️🙋‍♀️</p>","type":"text"},{"id":"course-114191-39","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114191-40","html":"<p>Вместе создайте тренировочный заказ. 🧪</p><p>Добавь 2–3 блюда, отправь на печать. 🍔🍟🥤</p><p>Попробуй сделать дозаказ. 🔄</p><p>Ты справишься! Уже через пару дней будешь работать в iiko уверенно. 💪🚀✨</p>","type":"text"}]},{"id":"114192","title":"Смена 7. Практика в действии","blocks":[{"id":"course-114192-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-7-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 7. Практика в действии"},{"id":"course-114192-2","text":"Работа в паре с наставником — наблюдаем и помогаем 🤝","type":"heading","level":2},{"id":"course-114192-3","html":"<p>Сегодня ты выходишь в зал не как самостоятельный официант, а как ассистент наставника🤝. Твоя главная задача — наблюдать, помогать и учиться правильной физике работы. Гости пока общаются с наставником, а ты занимаешься всем остальным.</p>","type":"text"},{"id":"course-114192-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114192-5","html":"<p>Научиться правильно двигаться в зале, держать посуду, убирать со стола и сервировать. Наставник говорит — ты делаешь. И внимательно смотришь, как работает профессионал. 👀</p>","type":"text"},{"id":"course-114192-6","text":"Теория: физика сервиса — то, чему не учат в учебниках 📚","type":"heading","level":2},{"id":"course-114192-7","text":"1. Как правильно держать тарелку 🍽️","type":"heading","level":3},{"id":"course-114192-8","html":"<p>Главное правило: большой палец всегда лежит на бортике, НЕ на поверхности тарелки, куда кладется еда!</p>","type":"text"},{"id":"course-114192-9","text":"Правильный хват:","type":"heading","level":3},{"id":"course-114192-10","type":"list","items":["Тарелка лежит на раскрытой ладони левой руки.","Большой палец — сверху, на краю тарелки (бортике).","Остальные пальцы поддерживают снизу.","Если тарелка горячая — используй салфетку или специальное полотенце."],"ordered":false},{"id":"course-114192-11","text":"Как НЕЛЬЗЯ:","type":"heading","level":3},{"id":"course-114192-12","type":"list","items":["❌ Касаться пальцами еды.","❌ Держать тарелку, как книгу, прижимая к себе.","❌ Класть большой палец на край, где будет лежать еда."],"ordered":false},{"id":"course-114192-13","text":"2. Как правильно брать и переносить бокал 🥂","type":"heading","level":3},{"id":"course-114192-14","html":"<p>Правило: только за ножку!</p><p>Почему?</p><p>Если берешь бокал за чашу — оставляешь отпечатки пальцев (гость это видит, это некрасиво). 🤢</p><p>Тепло твоих рук нагревает напиток (особенно важно для белого вина, шампанского, пива).</p><p>Эстетика: официант, берущий бокал за ножку, выглядит профессионально.</p>","type":"text"},{"id":"course-114192-15","text":"Как переносить несколько бокалов:","type":"heading","level":3},{"id":"course-114192-16","type":"list","items":["Один в руке — за ножку.","Остальные можно нести в другой руке, держа их за донышки (основания), аккуратно, чтобы они не касались друг друга и не звенели."],"ordered":false},{"id":"course-114192-17","text":"3. С какой стороны подходить к столу 🚶‍♀️🚶‍♂️","type":"heading","level":3},{"id":"course-114192-18","text":"Посмотри иллюстрации ниже. На практике наставник покажет, как подойти к столу и выполнить подачу.","type":"heading","level":4},{"id":"course-114192-19","text":"4. Как убирать посуду со стола 🧹","type":"heading","level":3},{"id":"course-114192-20","html":"<p>Никогда не складывай грязные тарелки в чистые на глазах у гостя! ❌ Это выглядит ужасно и антисанитарно.</p>","type":"text"},{"id":"course-114192-21","text":"Правильный алгоритм:","type":"heading","level":3},{"id":"course-114192-22","type":"list","items":["Подходишь к столу.","Сначала забираешь самые большие тарелки (они внизу стопки).","Меньшие ставишь сверху.","Остатки еды аккуратно сгребаешь в одну тарелку (лучше делать это уже на кухне или подсобке, а не у стола).","3. Грязные приборы кладешь сверху на тарелку, чтобы они не упали.","4. Бокалы убираешь отдельно, не ставишь их в стопку с тарелками."],"ordered":false},{"id":"course-114192-23","src":"assets/extra-courses/waiter-internship-7-1.jpg","type":"image","caption":""},{"id":"course-114192-24","src":"assets/extra-courses/waiter-internship-7-2.jpg","type":"image","caption":""},{"id":"course-114192-25","src":"assets/extra-courses/waiter-internship-7-3.jpg","type":"image","caption":""},{"id":"course-114192-26","text":"5. Как заменить тарелку 🔄","type":"heading","level":2},{"id":"course-114192-27","text":"Если гость ест блюдо, которое подается в несколько перемен, или просит чистую тарелку:","type":"heading","level":3},{"id":"course-114192-28","type":"list","items":["Приносишь чистую тарелку (правой рукой, справа).","Забираешь грязную (правой рукой, справа).","Делаешь это одним плавным движением: поставил чистую — забрал грязную.","Если меняешь приборы — сначала убери грязные, потом положи чистые."],"ordered":false},{"id":"course-114192-29","text":"Работа в iiko: тренировочные заказы 📱💻","type":"heading","level":2},{"id":"course-114192-30","html":"<p>В свободные минуты (когда нет задачи от наставника) бери планшет и тренируйся. Наставник покажет, где включить тестовый режим, или ты можешь просто создавать учебные заказы, не отправляя их на кухню.</p><p>Задание: 10 тренировочных заказов</p>","type":"text"},{"id":"course-114192-31","text":"Поставь себе цель за смену создать минимум 5-10 учебных заказов. Вот сценарии для тренировки:","type":"heading","level":3},{"id":"course-114192-32","text":"Что проверять в каждом заказе:","type":"heading","level":3},{"id":"course-114192-33","type":"list","items":["Правильно ли выбран стол? 🪑","Введено ли количество гостей? 👥","Все ли модификаторы выбраны (особенно обязательные)? ⚠️","Нет ли опечаток в комментариях? 📝","Если ошибся — не страшно!","Удаляй заказ и начинай заново. Это тренировка, здесь можно и нужно ошибаться. Главное — чтобы пальцы запомнили, где какие кнопки."],"ordered":false},{"id":"course-114192-35","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114192-36","html":"<p>Сегодня ты работаешь в режиме «тень наставника».</p><p>Задание 1. Наблюдение 🔍</p>","type":"text"},{"id":"course-114192-37","text":"Весь вечер ходи за наставником и смотри:","type":"heading","level":3},{"id":"course-114192-38","type":"list","items":["Как он подходит к гостям.","Как принимает заказ (какие вопросы задает, что рекомендует).","Как держит тарелки и бокалы.","С какой стороны подает и убирает.","Задание 2. Помощник 💪"],"ordered":false},{"id":"course-114192-39","text":"Наставник говорит — ты делаешь:","type":"heading","level":3},{"id":"course-114192-40","type":"list","items":["Поднести воду, хлеб или согласованный приветственный комплимент по стандарту точки.","Подать готовые блюда (наставник говорит, кому и что нести).","Убрать пустую посуду (наставник показывает, что уже можно убирать).","Долить воду (следи за бокалами).","Принести салфетки / дополнительный прибор / соус, если просит гость или наставник.","Задание 3. Чистота стола 🧼"],"ordered":false},{"id":"course-114192-41","text":"Твоя главная зона ответственности сегодня:","type":"heading","level":3},{"id":"course-114192-42","type":"list","items":["Стол должен выглядеть опрятно всегда.","Убирай сразу, как только видишь пустую тарелку (не жди, пока накопится гора).","Салфетки — если закончились или испачкались, замени.","Крошки — если видишь, аккуратно убери (специальной щеткой или чистой салфеткой)."],"ordered":false},{"id":"course-114192-43","text":"Чек-лист: чему ты научился сегодня ✅","type":"heading","level":2},{"id":"course-114192-44","html":"<p>Я знаю, как правильно держать тарелку (пальцы только на бортике) 🍽️</p><p>Я знаю, как правильно брать бокал (только за ножку) 🥂</p><p>Я запомнил, с какой стороны подавать и убирать (в основном справа) 👉</p><p>Я умею убирать посуду, не складывая грязное в чистое 🧹</p><p>Я помогал наставнику и не мешался под ногами 🤝</p><p>Я следил за чистотой столов и вовремя реагировал 🧼</p>","type":"text"},{"id":"course-114192-45","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114192-46","html":"<p>...гость обратился к тебе напрямую с вопросом?</p><p>Вежливо улыбнись и скажи: «Сейчас позову [Имя наставника], он вам подробно ответит». Не пытайся отвечать, если не уверен в информации.</p><p>...ты что-то уронил или пролил?</p><p>Не паникуй.</p><p>Сразу убери (позови уборщицу, если нужна помощь).</p><p>Если пострадала одежда гостя или скатерть — срочно зови менеджера.</p><p>...ты не знаешь, куда нести блюдо?</p><p>Никогда не ставь блюдо наугад.</p><p>Спроси наставника: «Это на какой стол?» или «Кому это?».</p><p>...у тебя нет задачи от наставника?</p><p>Не стой столбом! Возьми планшет и тренируйся создавать заказы. Или спроси наставника: «Чем я могу помочь?»</p>","type":"text"},{"id":"course-114192-47","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114192-48","html":"<p>Сегодня ты учишься не говорить, а делать. Физика сервиса — это база, без которой невозможно стать хорошим официантом. Смотри, запоминай, помогай. И не стесняйся задавать наставнику вопросы: «А почему ты так сделал?», «А почему с этой стороны?», «А почему ты так поставил бокал?».</p><p>А в свободные минуты — тренируйся в iiko. Чем быстрее твои пальцы запомнят расположение кнопок, тем легче тебе будет, когда ты начнешь работать самостоятельно.</p><p>Лучший способ научиться — быть полезным и внимательным. 👌</p><p>Ты молодец! Уже завтра эти движения станут для тебя привычными. 😊</p><p>Следующая смена — работа с отзывами и жалобами. Отдыхай и набирайся сил!</p>","type":"text"},{"id":"merged-rvb---9","type":"heading","text":"Сценарии для тренировочных заказов","level":2},{"id":"merged-rvb---10","type":"text","html":"<p>По разрешению наставника создай учебные заказы: один гость; пара; компания из четырёх; блюдо с модификатором; два одинаковых блюда с разными пожеланиями; дозаказ; исправление до печати; разделение счёта; расчёт с действующей акцией; заказ с программой лояльности.</p><p>Бери позиции и цены из меню своей точки. Условия скидок и бонусов проверь у менеджера. Учебный заказ не должен попасть в реальное производство: работай в согласованном учебном режиме.</p>"}]},{"id":"114193","title":"Смена 8. Всё под контролем","blocks":[{"id":"course-114193-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-8-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 8. Всё под контролем"},{"id":"course-114193-2","text":"Первая самостоятельная работа и новые навыки 🚀","type":"heading","level":2},{"id":"course-114193-3","html":"<p>Поздравляю! Ты переходишь на новый уровень — сегодня ты будешь самостоятельно обслуживать 2–3 стола. Наставник рядом, он контролирует и помогает, но основную работу делаешь ты. Это твой первый шаг к статусу полноценного официанта! 💪</p>","type":"text"},{"id":"course-114193-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114193-5","html":"<p>Взять ответственность за 2–3 стола (под контролем наставника)</p><p>Научиться контролировать время ожидания блюд</p><p>Освоить организацию поздравлений (подача торта со свечой)</p><p>Получить от наставника обратную связь по зонам роста</p>","type":"text"},{"id":"course-114193-6","text":"Самостоятельная работа с 2–3 столами 🪑✨","type":"heading","level":2},{"id":"course-114193-7","html":"<p>Сегодня ты не просто помогаешь, а ведёшь свои столы. Наставник вмешивается только если нужно подстраховать или если гость задает сложный вопрос.</p><p>Что значит \"вести столы\"?</p>","type":"text"},{"id":"course-114193-8","text":"Правила работы сегодня:","type":"heading","level":3},{"id":"course-114193-9","type":"list","items":["Ты главный за своими столами. Наставник — твоя тень и страховка.","Если сомневаешься — спроси шепотом, чтобы гость не слышал.","Если гость задает вопрос, на который не знаешь ответа: «Одну минуту, я уточню» — и идешь к наставнику.","Не беги, не суетись. Гости чувствуют нервозность. Действуй спокойно и уверенно."],"ordered":false},{"id":"course-114193-10","rows":[["Встретить гостей, принять заказ и внести его в iiko","Стажёр, наставник рядом"],["Отправить согласованный заказ, подать блюда и следить за столом","Стажёр"],["Предложить десерт или принести счёт","Стажёр"],["Проверить условия акции, способ оплаты и доступные бонусы","Стажёр уточняет, менеджер помогает при необходимости"],["Оформить скидку, списание и закрыть стол","В пределах полномочий по порядку точки"],["Решить нестандартную ситуацию","Стажёр приглашает наставника или менеджера"]],"type":"table","headers":["Действие","Кто отвечает"]},{"id":"course-114193-11","text":"Контроль времени ожидания ⏱️","type":"heading","level":2},{"id":"course-114193-12","html":"<p>Одна из главных задач официанта — управлять ожиданием гостя. Гость не знает, сколько готовится блюдо, и ему кажется, что \"уже полчаса\", даже если прошло 10 минут.</p>","type":"text"},{"id":"course-114193-13","text":"Что нужно делать:","type":"heading","level":3},{"id":"course-114193-14","text":"1. Предупреждать заранее","type":"heading","level":3},{"id":"course-114193-15","text":"Когда гость заказывает блюдо с долгим приготовлением (горячее 20–40 минут), сразу говори:","type":"heading","level":3},{"id":"course-114193-16","type":"list","items":["«Стейк будет готов примерно 25–30 минут. Хорошо?»","Гость предупрежден — значит, не дергает тебя каждые 5 минут."],"ordered":false},{"id":"course-114193-17","text":"2. Отслеживать время в iiko","type":"heading","level":3},{"id":"course-114193-18","html":"<p>В системе видно, когда блюдо отправили на кухню.</p><p>Если время приготовления вышло, а блюда нет — подойди к раздаче и вежливо спроси: «Когда примерно будет готово?»</p><p>Если задержка большая — подойди к гостю, скажи: «Блюдо готовится чуть дольше, спасибо за терпение».</p>","type":"text"},{"id":"course-114193-19","text":"3. Знать нормативы (повторяем из Смены 5)","type":"heading","level":3},{"id":"course-114193-20","text":"4. Что делать, если гость жалуется на ожидание","type":"heading","level":3},{"id":"course-114193-21","html":"<p>Если кухня заранее сообщает, что блюдо будет готовиться дольше обычного, назови актуальный ориентир до подтверждения заказа. Уточни, удобно ли гостю ждать.</p><p>Если обещанное время прошло, уточни срок на раздаче, предупреди гостя и скажи, когда вернёшься с обновлением.</p><p>При существенной задержке предложи подходящее решение и подключи наставника или менеджера. Комплимент согласуй до того, как предложишь его гостю.</p>","type":"text"},{"id":"course-114193-23","text":"Подача торта / поздравление 🎂🎉","type":"heading","level":2},{"id":"course-114193-24","html":"<p>У нас принято поздравлять именинников. Это важная часть сервиса, которая запоминается гостям.</p>","type":"text"},{"id":"course-114193-25","text":"Алгоритм действий:","type":"heading","level":3},{"id":"course-114193-26","type":"list","items":["Шаг 1. Узнать о поводе","Уточни, кого поздравляем, какое время удобно гостям и какой формат возможен в заведении.","Шаг 2. Согласовать подготовку с наставником или менеджером"],"ordered":false},{"id":"course-114193-27","text":"Ты не делаешь это в одиночку. Тебе нужно:","type":"heading","level":3},{"id":"course-114193-28","type":"list","items":["Согласуй формат, время и ответственного за подготовку с наставником или менеджером.","Если в поздравлении участвует ведущий, передай ему имя именинника и согласованное время.","Собрать коллег — 2–3 официанта, которые подойдут с тобой поздравлять","Шаг 3. Подготовить десерт","Проверь, предусмотрен ли комплимент и какой десерт согласован.","Если менеджер согласовал комплимент, до подачи уточни, как оформить его в iiko по правилам точки и кто отвечает за оформление и подачу.","Шаг 4. Организовать момент","Подай согласованный десерт. Свеча и участие команды зависят от формата поздравления.","Подойдите с коллегами в согласованный момент.","Улыбаемся, поздравляем, поем (хотя бы пару строк)","Если подаёте десерт со свечой, дай имениннику её задуть."],"ordered":false},{"id":"course-114193-29","text":"Важно!","tone":"yellow","type":"callout","title":""},{"id":"course-114193-30","html":"<p>Свеча зажигается перед выходом к гостю (не за 5 минут!)</p><p>Если гость принес свой торт — уточни, нужно ли его нарезать и подавать</p>","type":"text"},{"id":"course-114193-31","text":"Обратная связь от наставника: зоны роста 📝","type":"heading","level":2},{"id":"course-114193-32","html":"<p>В конце смены наставник даст тебе обратную связь. Это не критика, а помощь стать лучше.</p>","type":"text"},{"id":"course-114193-33","text":"Как принимать обратную связь:","type":"heading","level":3},{"id":"course-114193-34","type":"list","items":["Слушай внимательно, не перебивай","Не оправдывайся","Записывай (мысленно или в заметки), что нужно улучшить"],"ordered":false},{"id":"course-114193-35","text":"Что может сказать наставник (примеры):","type":"heading","level":3},{"id":"course-114193-36","text":"Твоя задача:","type":"heading","level":3},{"id":"course-114193-37","type":"list","items":["Спроси у наставника в конце смены: «Что мне нужно улучшить? На что обратить внимание?»","И запиши это. В следующих сменах будешь работать над этими моментами."],"ordered":false},{"id":"course-114193-38","src":"assets/extra-courses/waiter-internship-8-3.jpg","type":"image","caption":""},{"id":"course-114193-39","text":"Чек-лист: что ты сегодня попробовал ✅","type":"heading","level":2},{"id":"course-114193-40","html":"<p>Я сам встретил и усадил гостей 🪑</p><p>Я принял заказ без помощи наставника 📝</p><p>Я следил за временем приготовления и предупреждал гостей ⏱️</p><p>Я вовремя убирал посуду 🧹</p><p>Я предложил десерт и помог с выбором 🍰</p><p>Я участвовал в организации поздравления 🎂</p><p>Я получил обратную связь от наставника и запомнил зоны роста 📝</p>","type":"text"},{"id":"course-114193-41","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114193-42","html":"<p>...гость просит что-то, чего нет в меню?</p><p>Вежливо скажи: «К сожалению, этого нет, но могу порекомендовать...»</p><p>...ты ошибся в заказе?</p><p>Если блюдо еще не ушло на кухню — исправь в iiko. Если уже готовится — позови наставника.</p><p>...гость зовет тебя, а ты с другим заказом?</p><p>Скажи: «Одну минуту, я сейчас вернусь» — и подойди, как только освободишься. Если срочно — попроси помощи у коллеги.</p>","type":"text"},{"id":"course-114193-43","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114193-44","html":"<p>Сегодня ты доказываешь, что готов к самостоятельной работе. Не бойся ошибаться — наставник рядом. Но старайся делать всё сам. Именно так приходит уверенность.</p><p>И помни: гость не знает, что ты стажер. Для него ты — лицо ресторана. Действуй соответственно. 😊👌</p><p>Ты справишься! Уже через пару смен ты будешь работать наравне со всеми. 💪</p>","type":"text"},{"id":"merged-rvb---11","type":"text","html":"<p>Ориентиры приготовления изучены в смене 5. В каждой реальной смене время зависит от блюда, очереди и загрузки кухни. Перед обещанием гостю уточни актуальное время на раздаче.</p>"}]},{"id":"114194","title":"Смена 9. Вайб, кэш и харизма","blocks":[{"id":"course-114194-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-9-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 9. Вайб, кэш и харизма"},{"id":"course-114194-2","text":"Работа с отзывами, правила расчетов, конфликты и контроль остатков 🌟","type":"heading","level":2},{"id":"course-114194-3","html":"<p>Сегодня насыщенный день! Ты научишься работать с обратной связью от гостей, узнаешь важные правила расчетов со скидками, освоишь алгоритм действий при конфликтах и будешь контролировать остатки на своей станции. Поехали! 🚀</p>","type":"text"},{"id":"course-114194-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114194-5","html":"<p>Научиться приглашать гостя оставить честный отзыв и показывать ссылку своей точки</p><p>Освоить пошаговый алгоритм работы с конфликтами</p><p>Научиться проверять действующие условия акции, бонусов и оплаты</p><p>Научиться контролировать остатки текстиля и расходников на станции</p>","type":"text"},{"id":"course-114194-6","text":"Как предложить гостю оставить отзыв","type":"heading","level":2},{"id":"course-114194-7","html":"<p>Уточни у наставника, где брать актуальный QR-код или ссылку на карточку именно своего заведения. Проверь название и адрес точки.</p>","type":"text"},{"id":"course-114194-12","type":"list","items":["Выбери спокойный момент в разговоре. «Если захотите поделиться впечатлениями о визите, вот ссылка».","Покажи QR-код или отправь ссылку, если гость попросил. Он может оставить отзыв позже, со своего устройства."],"ordered":true},{"id":"course-114194-18","text":"Важно!","tone":"yellow","type":"callout","title":""},{"id":"course-114194-19","html":"<p>Оставить отзыв или отказаться — выбор гостя. Не проси ставить конкретную оценку или показывать публикацию. Не обещай коктейль, скидку или подарок за отзыв.</p><p>Если гость недоволен, выслушай его и помоги решить вопрос. При необходимости подключи наставника или менеджера.</p>","type":"text"},{"id":"course-114194-20","text":"Поведение при жалобах 🆘","type":"heading","level":2},{"id":"course-114194-21","html":"<p>Главное правило: ТЫ НЕ РЕШАЕШЬ ПРОБЛЕМУ В ОДИНОЧКУ!</p><p>Чего делать НЕЛЬЗЯ ❌</p><p>Забирать блюдо со словами «ой, извините» и уносить</p><p>Спорить с гостем</p><p>Обещать скидку или комплимент без согласования</p><p>Игнорировать жалобу</p><p>Что делать НУЖНО ✅</p><p>Почему это важно?</p><p>Если ты сам унесешь блюдо, повара не узнают об ошибке</p><p>Ты можешь пообещать то, что не положено (и ресторан потеряет деньги)</p><p>Менеджер лучше знает, что предложить: замену, комплимент или скидку</p>","type":"text"},{"id":"course-114194-23","text":"Алгоритм работы с конфликтами – идём глубже 🛠️","type":"heading","level":2},{"id":"course-114194-24","html":"<p>Конфликты неизбежны в работе с людьми. Главное — не бояться, а действовать грамотно. Хорошо обработанная жалоба может превратить недовольного гостя в постоянного.</p><p>Почему важно уметь работать с конфликтами?</p><p>Гость запомнит не саму проблему, а то, как ты её решил.</p><p>Профессиональная работа с жалобой помогает восстановить доверие гостя.</p><p>Твоя спокойная реакция снижает напряжение и предотвращает эскалацию.</p><p>Пошаговый алгоритм действий при конфликте</p><p>Техника активного слушания 👂</p>","type":"text"},{"id":"course-114194-25","text":"Чтобы гость почувствовал, что его слышат, используй:","type":"heading","level":3},{"id":"course-114194-26","type":"list","items":["Перефразирование – повтори суть жалобы своими словами, чтобы убедиться, что ты правильно понял.","«Если я правильно понял, вы заказывали коктейль \"Мальчик хочет в Таиланд\", но он показался вам слишком сладким?»","Уточняющие вопросы – помоги гостю конкретизировать претензию.","«Что именно вам не понравилось во вкусе? Может быть, не хватает кислинки или слишком крепко?»","Эмпатия – покажи, что ты понимаешь чувства гостя.","«Я понимаю, когда ожидания от коктейля не совпадают с реальностью, это обидно. Сейчас приглашу менеджера, и мы подберём вариант, который вам точно понравится»","Чего делать НЕЛЬЗЯ ❌","Перебивать и спорить.","Говорить «Это не моя вина», «Я тут ни при чём».","Обещать то, что не можешь выполнить (скидку, комплимент без менеджера).","Игнорировать проблему, надеясь, что «само рассосётся».","Убирать блюдо со словами «ой, извините» без выяснения причины.","Примеры фраз для разных ситуаций","Когда звать менеджера?","Гость угрожает или переходит на личности.","Проблема касается денег (скидка, возврат, пересчёт).","Ты не уверен в своих действиях.","Гость просит позвать «главного»."],"ordered":false},{"id":"course-114194-27","src":"assets/extra-courses/waiter-internship-9-2.jpg","type":"image","caption":""},{"id":"course-114194-28","rows":[["Коктейль не подошёл по вкусу","«Спасибо, что сказали. Могу уточнить, какой вкус вы предпочитаете, и подобрать другой вариант»."],["Напитки задерживаются","«Прошу прощения за ожидание. Уточню время на баре и вернусь с ответом»."],["Гость считает блюдо пересоленным","«Мне жаль, что блюдо вам не подошло. Приглашу менеджера, чтобы мы могли решить вопрос»."],["Гость заметил ошибку в счёте","«Извините за путаницу. Я проверю счёт и уточню решение у менеджера»."],["Гость недоволен обслуживанием","«Мне жаль, что так вышло. Позвольте пригласить менеджера и разобраться»."]],"type":"table","headers":["Ситуация","Что сказать"]},{"id":"course-114194-29","text":"Акции, расчёт и программа лояльности","type":"heading","level":2},{"id":"course-114194-30","html":"<p>Проверь действующую программу лояльности своей точки и данные гостя в iiko, если условия зависят от его уровня. Назови подтверждённые условия начисления или списания. При сомнении уточни у менеджера.</p>","type":"text"},{"id":"course-114194-33","text":"Как проверить бонусы при расчёте","type":"heading","level":2},{"id":"course-114194-34","text":"1. Если в точке действует программа лояльности, уточни, пользуется ли гость ей.","type":"heading","level":3},{"id":"course-114194-35","type":"list","items":["2. Если гость хочет воспользоваться программой, найди карту или профиль по правилам точки.","3. Сверь в iiko или у менеджера уровень гостя, баланс, условия начисления и доступную сумму списания.","4. Уточни у гостя, хочет ли он списать бонусы и в каком размере в пределах доступной суммы."],"ordered":false},{"id":"course-114194-36","html":"<p>5. Оформи списание по правилам точки в пределах своих полномочий или передай информацию менеджеру.</p>","type":"text"},{"id":"course-114194-37","type":"list","items":["6. Если гость интересуется оформлением, расскажи только о подтверждённых преимуществах действующей программы."],"ordered":false},{"id":"course-114194-39","text":"Проверь условия конкретной акции и назови гостю доступные способы оплаты до расчёта. Если условие непонятно, уточни его у менеджера.","tone":"yellow","type":"callout","title":"Способ оплаты по акции"},{"id":"course-114194-40","html":"<p>Если гость хочет оплатить картой, сначала уточни, действует ли при этом выбранная акция. Объясни подтверждённые условия и, при необходимости, предложи согласованную альтернативу.</p>","type":"text"},{"id":"course-114194-41","text":"Кто работает со скидками и баллами?","type":"heading","level":2},{"id":"course-114194-42","html":"<p>Кто оформляет скидку, начисляет или списывает бонусы, зависит от полномочий на точке. Если операция требует согласования, передай менеджеру данные гостя и условия акции.</p>","type":"text"},{"id":"course-114194-43","text":"Учет остатков на станции официанта 🧼📦","type":"heading","level":2},{"id":"course-114194-44","html":"<p>В конце смены ты должен проверить, всего ли хватит на завтра.</p>","type":"text"},{"id":"course-114194-45","text":"Чек-лист проверки:","type":"heading","level":3},{"id":"course-114194-46","type":"list","items":["Текстиль 🧺","Хватит ли чистых салфеток на завтрашнюю смену?","Хватит ли скатертей (если используем)?","Если нет — дать задание уборщице (или передать сменщику), что нужно постирать","Официанты сами гладят текстиль? Уточни у наставника!","Расходники 📦","Соль, перец — мельницы полные","Салфетки бумажные — достаточно на станции","Салфетки влажные — есть запас (особенно для блюд, которые едят руками)","Зубочистки — есть","Палочки для роллов — если в меню есть азиатские позиции"],"ordered":false},{"id":"course-114194-47","text":"Если чего-то не хватает:","type":"heading","level":3},{"id":"course-114194-48","type":"list","items":["Доложи наставнику","Пополни запасы (или попроси уборщицу / сменщика подготовить)"],"ordered":false},{"id":"course-114194-49","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114194-50","text":"Задание 1. Работа с отзывами","type":"heading","level":2},{"id":"course-114194-51","html":"<p>Проверь с наставником QR-код своей точки. Отработайте нейтральную фразу, затем используй её в подходящий момент, оставляя гостю выбор.</p>","type":"text"},{"id":"course-114194-52","text":"Задание 2. Отработка конфликта","type":"heading","level":2},{"id":"course-114194-53","html":"<p>Наставник разыгрывает ситуацию: гость недоволен блюдом. Твоя задача — пройти по алгоритму (выслушать → поблагодарить → извиниться → позвать менеджера). После этого наставник даёт обратную связь.</p>","type":"text"},{"id":"course-114194-54","text":"Задание 4. Проверка станции","type":"heading","level":2},{"id":"course-114194-55","html":"<p>В конце смены вместе с наставником проверь все по чек-листу. Если чего-то не хватает — пополни.</p>","type":"text"},{"id":"course-114194-56","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114194-57","html":"<p>Я знаю, где найти действующий QR-код или ссылку своей точки.</p><p>Я умею нейтрально пригласить гостя поделиться впечатлениями.</p><p>Я знаю алгоритм работы с жалобой: выслушать, поблагодарить, извиниться и при необходимости позвать менеджера.</p><p>Я умею проверять актуальные условия бонусов и способы оплаты по конкретной акции.</p><p>Я проверил остатки текстиля и расходников в конце смены.</p>","type":"text"},{"id":"course-114194-58","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114194-59","text":"...гость хочет написать отзыв, но у него нет телефона под рукой?","type":"heading","level":2},{"id":"course-114194-60","html":"<p>Предложи визитку с QR-кодом или ссылку, чтобы гость мог оставить отзыв позже со своего устройства.</p>","type":"text"},{"id":"course-114194-61","text":"...гость пишет негативный отзыв прямо при тебе?","type":"heading","level":2},{"id":"course-114194-62","html":"<p>Не спорь. Скажи: «Спасибо за честность, мы обязательно учтем». И передай наставнику.</p>","type":"text"},{"id":"course-114194-63","text":"...ты забыл проверить салфетницы, а утром у коллег не оказалось салфеток?","type":"heading","level":2},{"id":"course-114194-64","html":"<p>Это плохо. Постарайся не забывать. Если забыл — предупреди сменщика, чтобы он проверил сам.</p>","type":"text"},{"id":"course-114194-65","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114194-66","html":"<p>Сегодня ты учишься работать с людьми — и с довольными, и с недовольными. Это важнейший навык. Будь вежлив, внимателен и не бойся звать старших, если ситуация сложная.</p><p>И помни: отзывы — это не про \"галочку\", а про то, как стать лучше. Даже негатив — это подарок, если правильно его использовать. 😊</p><p>Ты справишься! Уже завтра ты будешь чувствовать себя еще увереннее. 💪</p><p>Следующая смена — плотная загрузка и работа в пик. Готовься! 🔥</p>","type":"text"}]},{"id":"114195","title":"Смена 10. Режим штурма","blocks":[{"id":"course-114195-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-10-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 10. Режим штурма"},{"id":"course-114195-2","text":"Плотная загрузка — работаем в команде с наставником 🔥","type":"heading","level":2},{"id":"course-114195-3","html":"<p>Сегодня ты выходишь на новый уровень! Твоя задача — работать в связке с наставником, но уже с гораздо большей ответственностью. Наставник теперь только общается с гостями и принимает заказы, а всё остальное делаешь ты. Поехали! 🚀</p>","type":"text"},{"id":"course-114195-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114195-5","html":"<p>Работать в паре с наставником: он говорит — ты делаешь</p><p>Обслуживать 3–5 столов в режиме «помощник на полную»</p><p>Понять, что такое пиковые часы и как в них работать</p><p>Подготовиться к мини-квизу по винам и алкоголю</p>","type":"text"},{"id":"course-114195-6","text":"Новая роль: почти полноценный официант 💪","type":"heading","level":2},{"id":"course-114195-7","text":"Сегодня схема работы меняется:","type":"heading","level":3},{"id":"course-114195-8","type":"list","items":["Наставник: Общается с гостями, принимает заказы, решает сложные вопросы","Ты: Всё остальное: встречаешь, подаешь, убираешь, доливаешь, носишь, следишь за столом"],"ordered":false},{"id":"course-114195-9","text":"Твои задачи в этой связке:","type":"heading","level":3},{"id":"course-114195-10","type":"list","items":["✅ Встретить гостей (улыбка, приветствие)","✅ Помочь с меню (если нужно)","✅ Подать воду/аперитив","✅ Подавать все блюда (по мере готовности)","✅ Убирать пустую посуду","✅ Следить за чистотой стола","✅ Доливать напитки","✅ Приносить дополнительное (соусы, салфетки, приборы)","✅ Финалить стол перед расчетом"],"ordered":false},{"id":"course-114195-11","text":"Чего ты НЕ делаешь (пока):","type":"heading","level":3},{"id":"course-114195-12","type":"list","items":["❌ Не принимаешь заказ (это делает наставник)","❌ Не решаешь конфликты (зовешь наставника)","❌ Не работаешь со скидками и особыми пожеланиями без наставника"],"ordered":false},{"id":"course-114195-13","text":"Пиковые часы: когда бывает тяжело, но мы справляемся ⏰","type":"heading","level":2},{"id":"course-114195-14","html":"<p>Что такое пиковые часы?</p><p>Это время, когда в баре максимальное количество гостей. Нагрузка растет, все бегают, но мы держим удар! 💪</p>","type":"text"},{"id":"course-114195-15","text":"Как подготовиться к пику","type":"heading","level":3},{"id":"course-114195-16","type":"list","items":["На брифинге уточни ожидаемую загрузку по броням и мероприятиям, а также распределение зон.","Если одновременно сели новые столы, а на раздаче ждут готовые блюда, согласуй с наставником приоритеты. Распределите задачи так, чтобы гостей заметили, а готовое ушло вовремя.","При высокой загрузке уточняй время подачи у кухни и бара."],"ordered":false},{"id":"course-114195-17","text":"Как предупредить гостя до подтверждения заказа","type":"heading","level":3},{"id":"course-114195-18","type":"list","items":["Назови актуальный ориентир, который подтвердили кухня или бар.","Если гость торопится, предложи позицию, которую смогут подать быстрее.","Если срок меняется, предупреди гостя и сообщи, когда вернёшься с обновлением."],"ordered":false},{"id":"course-114195-19","text":"Как работать в пик без стресса:","type":"heading","level":3},{"id":"course-114195-21","src":"assets/extra-courses/waiter-internship-10-2.jpg","type":"image","caption":""},{"id":"course-114195-22","text":"Шпаргалка по вину: готовимся к мини-квизу 🍷","type":"heading","level":2},{"id":"course-114195-23","html":"<p>Сегодня тебя ждёт мини-квиз по винам от наставника или менеджера. Чтобы быть готовым, изучи актуальные карточки вин своего заведения. Здесь собраны все позиции из нашей винной карты с характеристиками и гастрономическими рекомендациями.</p><p>🥂 Игристые вина / Шампанское (11 позиций)</p><p>🍾 Белые вина (9 позиций)</p><p>🍷 Красные вина (9 позиций)</p><p>🌸 Розовые вина (1 позиция)</p><p>СКАЧАЙ ШПАРГАЛКУ</p><p>Что будет в мини-квизе?</p><p>Назвать 3 белых, 3 красных, 3 игристых вина из нашей карты</p><p>Кратко описать вкус (сухое/сладкое, легкое/насыщенное)</p><p>Посоветовать, к какому блюду подойдет</p><p>💡 Совет: Если не уверен — лучше честно сказать «Я пока не очень разбираюсь, но могу позвать наставника». Это лучше, чем советовать ерунду.</p>","type":"text"},{"id":"course-114195-28","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114195-29","html":"<p>Задание 1. Работа в связке</p><p>В начале смены наставник показывает тебе 3–5 столов, за которые вы отвечаете. Он принимает заказ, ты делаешь всё остальное. Постарайся действовать так, чтобы наставнику не приходилось тебя подгонять.</p><p>Задание 2. Контроль времени</p><p>Когда наставник принимает заказ на блюдо с долгим приготовлением, слушай, как он предупреждает гостя. В следующий раз попробуй сам сказать эту фразу (с разрешения наставника).</p><p>Задание 3. Мини-квиз</p><p>В конце смены или в затишье наставник проведет мини-квиз. Постарайся ответить хотя бы на половину. Если ошибешься — не страшно, это тренировка.</p>","type":"text"},{"id":"course-114195-30","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114195-31","html":"<p>Я работал в связке «наставник говорит — я делаю» 🤝</p><p>Я обслуживал 3–5 столов практически самостоятельно 💪</p><p>Я умею уточнять ожидаемую загрузку на брифинге и распределять задачи с наставником.</p><p>Я знаю, что в пик время ожидания увеличивается 🕐</p><p>Я выучил 3 белых, 3 красных и 3 игристых вина 🍷</p><p>Я прошел мини-квиз (или готов к нему) 📝</p>","type":"text"},{"id":"course-114195-32","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114195-33","html":"<p>...ты не успеваешь?</p><p>Попроси помощи у коллег. Это нормально в пиковые часы.</p><p>...гость зовет, а ты с тарелками?</p><p>Скажи: «Одну минуту, я сейчас вернусь» — поставь тарелки и подойди. Или кивни другому официанту, чтобы он помог.</p><p>...наставник занят, а гость требует внимания?</p><p>Сделай что можешь: долить воду, убрать тарелки, принести салфетки. Если вопрос серьезный — скажи: «Я позову наставника».</p><p>...ты устал?</p><p>Пиковые часы выматывают. Держись, пей воду в подсобке, делай глубокие вдохи. Скоро смена кончится! 💪</p>","type":"text"},{"id":"course-114195-34","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114195-35","html":"<p>Сегодня ты доказываешь, что готов к большой нагрузке. Работай четко, не суетись, помогай наставнику и коллегам. Пиковые часы — это проверка на прочность. Пройди её достойно! 🔥</p><p>Ты справишься! Уже скоро ты будешь работать наравне со всеми. 💪</p><p>Следующая смена — сервировка и обслуживание банкетов. Готовься! 🎉</p>","type":"text"},{"id":"merged-rvb---12","type":"text","html":"<p>Открой актуальное <a href=\"https://askacademy.ru/#/menu?section=bar\">меню бара своего заведения</a> в академии. Состав, подачу, цену и наличие проверяй по его действующим карточкам и стоп-листу смены.</p><p>Подготовь по три белых, красных и игристых вина из доступной карты, если ассортимент категории это позволяет. Для каждого назови страну, сорт, сахар, стиль, основные вкусы и подходящее блюдо. Если категория меньше — изучи все её позиции. Основы повтори в библиотеке в материале «Вино».</p>"}]},{"id":"114197","title":"Смена 11. Выход на большую сцену","blocks":[{"id":"course-114197-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-11-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 11. Выход на большую сцену"},{"id":"course-114197-2","text":"Банкеты — готовимся к особому формату 🎉🍽️","type":"heading","level":2},{"id":"course-114197-3","html":"<p>Сегодня ты погружаешься в мир банкетного обслуживания. Это совсем другой уровень! Здесь важна не только скорость, но и четкая координация с командой, знание последовательности подач и умение работать с большим количеством гостей одновременно.</p><p>Банкет — это мини-спектакль, и у тебя в нем важная роль! 🎭</p>","type":"text"},{"id":"course-114197-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114197-5","html":"<p>Понять специфику банкетного обслуживания</p><p>Научиться сервировать стол в зависимости от предзаказа</p><p>Освоить порционную раскладку блюд</p><p>Научиться координировать поздравления с ведущим, баром и кухней</p>","type":"text"},{"id":"course-114197-6","text":"Сервировка банкетного стола 🍽️","type":"heading","level":2},{"id":"course-114197-7","html":"<p>Главное правило: сервировка зависит от предзаказа!</p><p>У банкета всегда есть предзаказ — список блюд и напитков, которые гости заказали заранее. Именно от него мы и отталкиваемся.</p>","type":"text"},{"id":"course-114197-8","text":"Что нужно узнать из предзаказа:","type":"heading","level":3},{"id":"course-114197-9","src":"assets/extra-courses/waiter-internship-11-1.jpg","type":"image","caption":""},{"id":"course-114197-10","text":"Бокалы для банкета","type":"heading","level":2},{"id":"course-114197-11","html":"<p>Подбирай бокалы под напитки из предзаказа по посуде своей точки. Полный справочник посуды находится в смене 4; перед банкетом проверь количество и запас, чистоту и отсутствие сколов.</p>","type":"text"},{"id":"course-114197-15","text":"Подготовка к банкету 📋","type":"heading","level":2},{"id":"course-114197-16","text":"За день до банкета (или в начале смены) нужно подготовить:","type":"heading","level":3},{"id":"course-114197-17","text":"1. Сменные тарелки 🍽️","type":"heading","level":3},{"id":"course-114197-18","html":"<p>Для каждого гостя должно быть минимум 2 комплекта тарелок (под закуски и под горячее)</p><p>Лучше подготовить с запасом (+2–3 комплекта)</p>","type":"text"},{"id":"course-114197-19","text":"2. Приборы 🥄🔪","type":"heading","level":3},{"id":"course-114197-20","html":"<p>Ножи, вилки, ложки — по количеству гостей + запас</p><p>Для общих блюд — ложки и вилки для раскладки (отдельно!)</p>","type":"text"},{"id":"course-114197-21","text":"3. Салфетки 🧻","type":"heading","level":3},{"id":"course-114197-22","html":"<p>Бумажные и влажные — с запасом</p><p>Текстильные салфетки для сервировки</p>","type":"text"},{"id":"course-114197-23","text":"Обслуживание банкета 🛎️","type":"heading","level":2},{"id":"course-114197-24","html":"<p>Порционная раскладка (самое важное!)</p><p>Большинство банкетных блюд подаются в общей посуде (большие тарелки, салатники, блюда). Твоя задача — разложить еду по тарелкам гостей.</p>","type":"text"},{"id":"course-114197-25","text":"Как правильно раскладывать:","type":"heading","level":3},{"id":"course-114197-26","type":"list","items":["Подходи к гостю с левой стороны (так удобнее)","Держи общее блюдо в левой руке, ложку и вилку для раскладки — в правой","Аккуратно выкладывай порцию, стараясь, чтобы она выглядела аппетитно","Если блюдо с соусом — полей соусом сверху","Уточни: «Вам добавить еще?» — если гость хочет добавки"],"ordered":false},{"id":"course-114197-27","text":"Важно!","tone":"yellow","type":"callout","title":""},{"id":"course-114197-28","html":"<p>Используй отдельные приборы для раскладки (не те, которыми едят гости!)</p><p>Не касайся еды руками</p><p>Если блюдо горячее — предупреди гостя</p><p>Последовательность подачи на банкете</p><p>Перед началом сверь согласованный предзаказ и тайминг с ответственным за банкет и кухней.</p>","type":"text"},{"id":"course-114197-29","text":"Важные правила подачи:","type":"heading","level":3},{"id":"course-114197-30","type":"list","items":["Подготовь стол и посуду по подтверждённому предзаказу.","Подавай блюда в согласованной последовательности.","Если организатор просит подать блюдо раньше, проверь готовность у кухни и согласуй изменение с ответственным за банкет. Сообщи гостю новое время после подтверждения."],"ordered":false},{"id":"course-114197-31","text":"Что делать между подачами:","type":"heading","level":3},{"id":"course-114197-32","type":"list","items":["Убирать использованную посуду","Менять приборы (если нужно)","Доливать напитки","Следить за чистотой стола","💡 Совет: Если в банкете несколько горячих блюд, они могут подаваться одновременно (все на стол) или по очереди. Уточни это у наставника или организатора банкета заранее."],"ordered":false},{"id":"course-114197-33","text":"Координация с командой 🤝","type":"heading","level":2},{"id":"course-114197-34","html":"<p>Банкет — это командная работа. Ты не один!</p>","type":"text"},{"id":"course-114197-35","text":"С кем координируемся:","type":"heading","level":3},{"id":"course-114197-36","src":"assets/extra-courses/waiter-internship-11-5.jpg","type":"image","caption":""},{"id":"course-114197-37","text":"Поздравление именинника 🎂🎉","type":"heading","level":2},{"id":"course-114197-38","html":"<p>Согласуй формат поздравления и время с организатором и менеджером. Уточни, кто готовит десерт, кто координирует подачу и нужен ли ведущий.</p>","type":"text"},{"id":"course-114197-39","text":"Алгоритм действий:","type":"heading","level":3},{"id":"course-114197-41","html":"<p>Если менеджер согласовал комплимент, до подачи уточни, как оформить его в iiko по правилам точки и кто отвечает за оформление и подачу.</p><p>Свечу и участие коллег подготовь, если они предусмотрены согласованным форматом.</p>","type":"text"},{"id":"course-114197-42","rows":[["Согласование","Уточни удобное время у организатора и формат у менеджера."],["Оформление","Если согласован комплимент, проверь порядок оформления в iiko и ответственного."],["Подготовка","Передай согласованное время кухне и ведущему, если он участвует."],["Подача","Вынеси десерт в согласованный момент вместе с командой, если это входит в формат."]],"type":"table","headers":["Шаг","Действие"]},{"id":"course-114197-43","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114197-44","html":"<p>Задание 1. Изучение предзаказа</p><p>Возьми реальный предзаказ на банкет (или учебный). Посмотри, какие напитки заказаны. Определи, какие бокалы нужно поставить.</p><p>Задание 2. Сервировка</p><p>Под руководством наставника попробуй сервировать стол под конкретный предзаказ.</p><p>Задание 3. Порционная раскладка</p><p>Если будет возможность, попробуй разложить блюдо в общей посуде по тарелкам (под присмотром).</p><p>Задание 4. Координация поздравления</p><p>Если в смене есть банкет с именинником — поучаствуй в подготовке и самом поздравлении.</p>","type":"text"},{"id":"course-114197-45","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114197-46","html":"<p>Я знаю, что сервировка банкета зависит от предзаказа 📋</p><p>Я умею подбирать бокалы под напитки (по файлу посуды) 🥂</p><p>Я знаю, какие тарелки и приборы нужны для банкета 🍽️</p><p>Я понимаю, как делать порционную раскладку 🥄</p><p>Я запомнил последовательность подачи блюд (5 этапов) 🔢</p><p>Я знаю, с кем координироваться (ведущий, бар, кухня) 🤝</p><p>Я умею организовывать поздравление именинника 🎂</p>","type":"text"},{"id":"course-114197-47","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114197-48","html":"<p>...в предзаказе нет информации о напитках?</p><p>Спроси у наставника или менеджера. Возможно, гости будут заказывать на месте.</p><p>...гостей больше, чем мы ожидали?</p><p>Срочно добавляй приборы и тарелки. Если не хватает — бери у коллег или со склада.</p><p>...кто-то из гостей просит добавки, а блюдо закончилось?</p><p>Вежливо скажи: «Сейчас уточню на кухне, возможно, есть еще». Если нет — предложи альтернативу.</p><p>...свеча погасла перед выходом?</p><p>Не паникуй. Зажги новую. Главное — улыбайся.</p>","type":"text"},{"id":"course-114197-49","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114197-50","html":"<p>Банкет — это как дирижировать оркестром. Ты должен чувствовать ритм, вовремя подавать сигналы и работать в команде. Не бойся просить помощи у коллег и координироваться с ведущим.</p><p>И помни: именинник запомнит не только торт, но и твою улыбку. 😊</p><p>Ты справишься! Банкеты — это сложно, но очень интересно. 💪</p><p>Следующая смена — контроль чистоты и заготовок, закрытие смены. Готовься! 🧹</p>","type":"text"}]},{"id":"114198","title":"Смена 12. Чисто, чётко, по стилю","blocks":[{"id":"course-114198-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-12-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 12. Чисто, чётко, по стилю"},{"id":"course-114198-2","text":"Чистота, заготовки, закрытие смены и продажа авторских коктейлей 🧹✨","type":"heading","level":2},{"id":"course-114198-3","html":"<p>Сегодня ты осваиваешь важнейшие навыки, которые отличают профессионала: поддержание чистоты в течение всей смены, правильное закрытие и продажа авторских коктейлей. Поехали! 🚀</p>","type":"text"},{"id":"course-114198-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114198-5","html":"<p>Научиться контролировать чистоту в зале в течение всей смены</p><p>Освоить работу с заготовками (расходниками)</p><p>Изучить алгоритм закрытия смены по чек-листу</p><p>Выучить авторские коктейли и научиться их продавать</p><p>Отработать нейтральное приглашение оставить отзыв.</p>","type":"text"},{"id":"course-114198-6","text":"Режим работы и тайминг ⏰","type":"heading","level":2},{"id":"course-114198-8","text":"Контроль чистоты в течение смены 🧼","type":"heading","level":2},{"id":"course-114198-9","html":"<p>Чистота — это лицо бара. Гость не простит грязный стол или липкие салфетницы.</p>","type":"text"},{"id":"course-114198-10","text":"Что нужно контролировать постоянно:","type":"heading","level":3},{"id":"course-114198-11","text":"Золотое правило:","type":"heading","level":3},{"id":"course-114198-12","type":"list","items":["Лучше убрать сразу, чем потом объяснять гостю, почему грязно."],"ordered":false},{"id":"course-114198-13","src":"assets/extra-courses/waiter-internship-12-2.jpg","type":"image","caption":""},{"id":"course-114198-14","text":"Заготовки (расходники) — твоя зона ответственности 📦","type":"heading","level":2},{"id":"course-114198-15","text":"В течение смены ты должен следить, чтобы на станции всегда было достаточно:","type":"heading","level":3},{"id":"course-114198-16","text":"Основные расходники:","type":"heading","level":3},{"id":"course-114198-17","text":"Как складывать салфетницы:","type":"heading","level":3},{"id":"course-114198-18","type":"list","items":["Мы складываем салфетницы заранее (не в момент, когда гость уже сел). Научись делать это красиво и быстро — это часть сервиса."],"ordered":false},{"id":"course-114198-19","src":"assets/extra-courses/waiter-internship-12-3.jpg","type":"image","caption":""},{"id":"course-114198-20","text":"Закрытие смены (Чек-лист) ✅","type":"heading","level":2},{"id":"course-114198-21","html":"<p>После ухода гостей выполни чек-лист закрытия своей точки. Проверь зал и станцию, подготовь расходники к следующей смене, передай результат ответственному. Смену считают закрытой после выполнения чек-листа и передачи старшему.</p>","type":"text"},{"id":"course-114198-22","text":"Чек-лист закрытия:","type":"heading","level":3},{"id":"course-114198-23","text":"Важно!","tone":"yellow","type":"callout","title":""},{"id":"course-114198-24","html":"<p>Фотоотчет — это доказательство, что зал убран идеально. Фотографируем столы, стулья, стейшены.</p><p>ОС о смене — пишем, что было хорошо, что плохо, какие проблемы возникли.</p>","type":"text"},{"id":"course-114198-25","src":"assets/extra-courses/waiter-internship-12-4.jpg","type":"image","caption":""},{"id":"course-114198-26","text":"Продажа авторских коктейлей 🍸🔥","type":"heading","level":2},{"id":"course-114198-27","html":"<p>У нас есть не только классические коктейли, но и авторские. Их нужно знать в лицо (вернее, в бокал) и уметь продавать.</p>","type":"text"},{"id":"course-114198-28","text":"Что нужно знать о каждом авторском коктейле:","type":"heading","level":3},{"id":"course-114198-29","src":"assets/extra-courses/waiter-internship-12-5.jpg","type":"image","caption":""},{"id":"course-114198-30","text":"Основные авторские коктейли из нашего меню 🍹","type":"heading","level":2},{"id":"course-114198-31","text":"Как продавать авторские коктейли:","type":"heading","level":3},{"id":"course-114198-32","type":"list","items":["Не жди, пока гость спросит. Предлагай сам!"],"ordered":false},{"id":"course-114198-33","text":"Используй \"вкусные\" описания:","type":"heading","level":3},{"id":"course-114198-34","type":"list","items":["«Попробуйте наш авторский коктейль \"Мальчик хочет в Таиланд\" — он на джине, с ананасовым соком и ликёром, очень освежающий!»","3. Если гость сомневается, предложи попробовать (если разрешено политикой бара)."],"ordered":false},{"id":"course-114198-35","text":"4. Расскажи историю — многие авторские коктейли имеют интересное название или","type":"heading","level":3},{"id":"course-114198-36","html":"<p>историю создания.</p>","type":"text"},{"id":"course-114198-37","text":"5. Обращай внимание на подачу — коктейли в больших бокалах (1 л) или необычных","type":"heading","level":3},{"id":"course-114198-38","html":"<p>формах привлекают внимание.</p>","type":"text"},{"id":"course-114198-41","text":"Работа с отзывами (продолжение) 📱💬","type":"heading","level":2},{"id":"course-114198-42","html":"<p>Уточни у наставника, какой QR-код или ссылку используют в твоей точке.</p>","type":"text"},{"id":"course-114198-45","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114198-46","html":"<p>Задание 1. Контроль чистоты</p><p>В течение смены следи за чистой своих столов. Наставник будет проверять, как ты убираешь и замечаешь ли грязь.</p><p>Задание 2. Заготовки</p><p>Проверь станцию в начале и середине смены. Доложи наставнику, если чего-то не хватает.</p><p>Задание 3. Продажа авторских коктейлей</p><p>Попробуй предложить авторский коктейль хотя бы 3 столам. Запиши, сколько раз получилось продать.</p><p>Задание 4. Закрытие смены</p><p>Вместе с наставником пройди весь чек-лист закрытия. Сделай фотоотчет.</p><p>Задание 5. Отзывы</p><p>Проверь действующий QR-код и отработай нейтральное приглашение с наставником.</p>","type":"text"},{"id":"course-114198-47","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114198-48","html":"<p>Я знаю, что контролировать чистоту нужно постоянно, а не только в конце 🧼</p><p>Я умею проверять заготовки и пополнять расходники 📦</p><p>Я уточнил порядок закрытия своей точки и кому передать результат.</p><p>Я знаю чек-лист закрытия смены и выполняю его 📋</p><p>Я умею составлять фотоотчет и писать ОС о смене 📸</p><p>Я знаю авторские коктейли и могу их рекомендовать 🍸</p><p>Я умею предложить ссылку на отзыв и оставить решение за гостем.</p>","type":"text"},{"id":"course-114198-49","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114198-50","html":"<p>...закончились салфетницы, а новых нет?</p><p>Скажи наставнику или менеджеру. Возможно, нужно сходить на склад.</p><p>...гость оставил сильное загрязнение (пролил вино)?</p><p>Убери сразу, используй спецсредства. Если нужно — позови уборщицу.</p><p>...ты устал под утро?</p><p>Держись! Осталось немного. Работа в команде помогает — поддерживай коллег.</p><p>...не знаешь, как продать авторский коктейль?</p><p>Спроси у бармена — он расскажет про каждый коктейль лучше всех!</p>","type":"text"},{"id":"course-114198-51","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114198-52","html":"<p>Чистота, заготовки и знание коктейлей — это то, что делает официанта профессионалом. Гость не видит, как ты моешь ножки стульев при закрытии, но он видит чистый стол и вовремя поданные салфетки.</p><p>И помни: авторские коктейли — это не просто напитки, это наша гордость. Продавай их с душой! ❤️</p><p>Ты справишься! Уже совсем скоро ты будешь закрывать смену как настоящий профи. 💪</p><p>Следующая смена — участок и контроль подачи на время. Готовься! ⏱️</p>","type":"text"},{"id":"merged-rvb---13","type":"text","html":"<p>Открой актуальное <a href=\"https://askacademy.ru/#/menu?section=bar\">меню бара своего заведения</a> в академии. Состав, подачу, цену и наличие проверяй по его действующим карточкам и стоп-листу смены.</p><p>Выбери авторские коктейли своей точки. Для каждого выучи ингредиенты по гостевому меню, бокал, вкус и подачу. Предлагай сочетание под запрос гостя, не придумывай историю или состав. Порядок приглашения к честному отзыву изучен в смене 9 — сегодня отработай его на практике.</p><p>Время начала и завершения работы проверь по актуальному графику своей точки. Закрытие согласуй со старшим после выполнения чек-листа.</p>"}]},{"id":"114199","title":"Смена 13. Теперь ты — наставник","blocks":[{"id":"course-114199-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-13-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 13. Теперь ты — наставник"},{"id":"course-114199-2","text":"Участок и контроль подачи на время — обслуживание топ-персонала ⏱️👔","type":"heading","level":2},{"id":"course-114199-3","html":"<p>Сегодня особенный день! Ты будешь обслуживать не обычных гостей, а топ-персонал — менеджеров, управляющих, бар-менеджеров. Это своего рода экзамен: они будут следить за твоей скоростью, точностью и качеством сервиса. А ещё ты попробуешь себя в роли наставника и узнаешь главные техники продаж. Поехали! 🚀</p>","type":"text"},{"id":"course-114199-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114199-5","html":"<p>Научиться контролировать время подачи блюд и напитков</p><p>Обслужить топ-персонал, показав всё, на что ты способен</p><p>Провести мини-инструктаж для стажёра (в роли наставника)</p><p>Освоить базовые техники продаж в ресторане/баре</p>","type":"text"},{"id":"course-114199-6","text":"Работа с топ-персоналом: почему это важно? 🤔","type":"heading","level":2},{"id":"course-114199-7","html":"<p>Сегодня твои гости — свои же коллеги, но в роли требовательных посетителей. Это отличная тренировка, потому что:</p><p>Они точно знают стандарты и заметят каждую мелочь</p><p>Они будут оценивать твою скорость и последовательность</p><p>После смены они дадут честную обратную связь</p>","type":"text"},{"id":"course-114199-8","text":"Что они будут проверять:","type":"heading","level":3},{"id":"course-114199-9","text":"Твоя задача:","type":"heading","level":3},{"id":"course-114199-10","type":"list","items":["Обслужить их так, чтобы они забыли, что они твои коллеги, и почувствовали себя настоящими гостями. Это твой шанс показать, что ты готов к самостоятельной работе! 💪"],"ordered":false},{"id":"course-114199-11","src":"assets/extra-courses/waiter-internship-13-1.jpg","type":"image","caption":""},{"id":"course-114199-12","text":"Контроль времени подачи ⏱️","type":"heading","level":2},{"id":"course-114199-13","html":"<p>Главный навык сегодня — тайминг. Ты должен четко понимать, когда что нести, чтобы гость не ждал, но и не чувствовал, что его торопят.</p>","type":"text"},{"id":"course-114199-14","text":"Идеальный тайминг обслуживания:","type":"heading","level":3},{"id":"course-114199-15","text":"Что важно:","type":"heading","level":3},{"id":"course-114199-16","type":"list","items":["Напитки должны быть на столе быстро — это первое впечатление","Не носи всё сразу — если горячее ещё не готово, не стой у раздачи, займись другими столами","Следи за временем в iiko — система показывает, когда блюдо отправлено на кухню"],"ordered":false},{"id":"course-114199-18","text":"Мини-инструктаж стажёра (в роли наставника) 🎓","type":"heading","level":2},{"id":"course-114199-19","html":"<p>Сегодня тебе предстоит побыть в роли наставника для другого стажёра (или понарошку). Это важное упражнение, потому что:</p><p>Лучший способ понять материал — объяснить его другому.</p>","type":"text"},{"id":"course-114199-20","text":"Что нужно сделать:","type":"heading","level":3},{"id":"course-114199-21","type":"list","items":["Выбери одну тему, в которой ты уже уверен (например, «Как правильно держать тарелку» или «Последовательность подачи блюд»)."],"ordered":false},{"id":"course-114199-22","text":"Объясни стажёру так, как тебе объясняли в первые дни:","type":"heading","level":3},{"id":"course-114199-23","type":"list","items":["Покажи на примере","Дай попробовать","Ответь на вопросы","3. Дай обратную связь: что получилось, что можно улучшить."],"ordered":false},{"id":"course-114199-24","text":"Темы для инструктажа (выбери одну):","type":"heading","level":3},{"id":"course-114199-25","type":"list","items":["Как правильно держать тарелку и бокал","С какой стороны подавать и убирать","Как проверить чек перед оплатой","Как предлагать авторские коктейли","Как нейтрально предложить отзыв и показать действующий QR-код своей точки"],"ordered":false},{"id":"course-114199-26","text":"Почему это полезно:","type":"heading","level":3},{"id":"course-114199-27","type":"list","items":["Ты лучше запоминаешь стандарты","Учишься доносить информацию","Развиваешь лидерские качества"],"ordered":false},{"id":"course-114199-28","text":"Техники продаж💰🗣️","type":"heading","level":2},{"id":"course-114199-29","html":"<p>Умение продавать — это то, что отличает хорошего официанта от отличного. Гости часто не знают, чего хотят, и ждут твоей подсказки.</p>","type":"text"},{"id":"course-114199-30","text":"1. Техника «Золотой треугольник» 🔺","type":"heading","level":3},{"id":"course-114199-31","html":"<p>Это база: когда гость смотрит в меню, его взгляд движется по треугольнику. Размещай самые выгодные позиции в центре внимания.</p><p>Твоя задача: если гость колеблется, предложи блюдо, которое находится в центре меню</p><p>или выделено визуально.</p>","type":"text"},{"id":"course-114199-32","text":"2. Техника «Открытые вопросы» ❓","type":"heading","level":3},{"id":"course-114199-33","text":"Вместо вопросов, на которые можно ответить «да» или «нет», задавай открытые вопросы:","type":"heading","level":3},{"id":"course-114199-34","text":"3. Техника «Аппетитное описание» 🍔🔥","type":"heading","level":3},{"id":"course-114199-35","text":"Не просто называй блюдо, а описывай его так, чтобы у гостя потекли слюнки:","type":"heading","level":3},{"id":"course-114199-36","text":"4. Техника «Дополнительные продажи» (Upsell) ⬆️","type":"heading","level":3},{"id":"course-114199-37","text":"Всегда предлагай что-то к заказу:","type":"heading","level":3},{"id":"course-114199-38","type":"list","items":["К напиткам: «К вашему вину отлично подойдёт сырное плато»","К основному блюду: «Хотите добавить фирменный соус или овощи гриль?»","После еды: «На десерт сегодня потрясающая \"Памела Андерсон\" — сезонные фрукты и ягоды»"],"ordered":false},{"id":"course-114199-39","text":"5. Техника «Ограниченное предложение» ⏳","type":"heading","level":3},{"id":"course-114199-40","text":"Люди боятся упустить возможность:","type":"heading","level":3},{"id":"course-114199-41","type":"list","items":["Если условия подтверждены: «Сегодня последний день акции на этот сет».","«Это блюдо готовится только по выходным»","«У нас осталось всего две порции этого десерта»"],"ordered":false},{"id":"course-114199-42","src":"assets/extra-courses/waiter-internship-13-3.jpg","type":"image","caption":""},{"id":"course-114199-44","text":"Практика с наставником 🤝","type":"heading","level":2},{"id":"course-114199-45","html":"<p>Задание 1. Обслуживание топ-персонала</p><p>К тебе за стол садятся менеджер, управляющий и бар-менеджер. Твоя задача — обслужить их по полной программе, соблюдая тайминг и последовательность.</p><p>Задание 2. Контроль времени</p><p>Засеки время от пробития заказа до подачи каждого блюда. После смены обсуди с наставником, где можно было быстрее.</p><p>Задание 3. Мини-инструктаж</p><p>Проведи для другого стажёра (или наставника в роли стажёра) мини-урок по одной из тем. Получи обратную связь.</p><p>Задание 4. Техники продаж</p><p>Попробуй применить хотя бы 3 техники продаж за смену. Запиши, что сработало, а что нет.</p>","type":"text"},{"id":"course-114199-46","text":"Чек-лист: что ты сегодня освоил ✅","type":"heading","level":2},{"id":"course-114199-47","html":"<p>Я обслуживал топ-персонал и показал высокий уровень сервиса 👔</p><p>Я контролировал время подачи и соблюдал последовательность ⏱️</p><p>Я провел мини-инструктаж для стажёра 🎓</p><p>Я использовал технику открытых вопросов ❓</p><p>Я практиковал аппетитные описания блюд 🍔</p><p>Я предлагал дополнительные позиции к заказу ⬆️</p>","type":"text"},{"id":"course-114199-48","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114199-49","html":"<p>...топ-персонал специально пытается тебя запутать?</p><p>Не паникуй. Это проверка. Внимательно слушай, переспрашивай, если нужно. Делай свою работу чётко.</p><p>...ты ошибся с временем подачи?</p><p>Если видишь, что блюдо задерживается, подойди и скажи честно: «Блюдо готовится чуть дольше, спасибо за терпение». Честность ценят больше, чем молчание.</p><p>...стажёр не понимает твоего объяснения?</p><p>Попробуй объяснить по-другому, покажи на примере. Спроси: «Что именно непонятно?».</p><p>...гость сказал «нет» на твоё предложение?</p><p>Не настаивай. Улыбнись и скажи: «Хорошо, если захотите что-то ещё — обращайтесь!»</p>","type":"text"},{"id":"course-114199-50","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114199-51","html":"<p>Сегодня ты не просто официант, а почти полноценный член команды. Топ-персонал будет оценивать тебя строго, но справедливо. Не бойся ошибок — бойся не сделать выводы.</p><p>И помни: продажи — это не про \"впарить\", а про помочь гостю выбрать то, что ему действительно понравится. Если ты искренне рекомендуешь, гость это чувствует.</p><p>Ты справишься! Уже завтра ты будешь готов к финальной аттестации. 💪</p><p>Следующая смена — максимальная загрузка и работа без помощи наставника. Готовься!</p>","type":"text"}]},{"id":"114200","title":"Смена 14. Первый сольник","blocks":[{"id":"course-114200-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-14-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 14. Первый сольник"},{"id":"course-114200-2","text":"Полная самостоятельность и максимальная загрузка","type":"heading","level":2},{"id":"course-114200-3","html":"<p>Поздравляю! Ты дошёл до финишной прямой. Сегодня ты работаешь полностью самостоятельно. Никто не подсказывает, не страхует, не направляет. Ты сам открываешь смену, сервируешь столы, встречаешь гостей, принимаешь заказы, решаешь вопросы. Это твой звёздный час! ⭐</p>","type":"text"},{"id":"course-114200-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114200-5","html":"<p>Самостоятельно открыть смену по чек-листу</p><p>Работать без помощи наставника при максимальной загрузке</p><p>Показать всё, чему научился за время стажировки</p><p>Подготовиться к финальной аттестации</p>","type":"text"},{"id":"course-114200-6","text":"Открытие смены: твой личный чек-лист 📋","type":"heading","level":2},{"id":"course-114200-7","html":"<p>Перед сменой проверь время выхода и сбора в актуальном графике своей точки. Если график и памятка расходятся или предстоит банкет, заранее уточни время у ответственного за смену.</p><p>Перед открытием пройди чек-лист своей зоны, проверь стоп-лист и изменения на смену.</p>","type":"text"},{"id":"course-114200-8","text":"Дополнительные действия при открытии:","type":"heading","level":3},{"id":"course-114200-9","type":"list","items":["Проверить наличие расходников (салфетки бумажные/влажные, соль/перец, палочки)","Убедиться, что на станции достаточно чистых тарелок и приборов","Открыть личную смену в iiko (прокатить карту или ввести PIN)"],"ordered":false},{"id":"course-114200-10","rows":[["До выхода","Время выхода и брифинга по актуальному графику."],["Подготовка","Форма, мебель, чистота столов, посуда, текстиль и расходники."],["Перед открытием","Готовность своей зоны, актуальный стоп-лист и изменения на смену."],["Брифинг","Акции, брони и распределение зон."]],"type":"table","headers":["Этап","Что проверить"]},{"id":"course-114200-11","text":"Работа в течение смены: ты сам за себя 💪","type":"heading","level":2},{"id":"course-114200-12","text":"Сегодня наставник не подходит к твоим столам. Ты сам:","type":"heading","level":3},{"id":"course-114200-13","type":"list","items":["✅ Встречаешь гостей","✅ Принимаешь заказы (используй техники продаж!)","✅ Вносишь заказы в iiko","✅ Отправляешь на кухню","✅ Следишь за временем подачи","✅ Подаёшь блюда и напитки","✅ Убираешь посуду","✅ Предлагаешь десерты и дополнительные позиции","✅ По ситуации предлагаешь гостям оставить отзыв и показываешь ссылку своей точки.","✅ Проверяешь условия акции и способ оплаты. Скидки, бонусы и закрытие стола оформляешь в пределах полномочий по правилам точки.","✅ Решаешь стандартные вопросы (если нестандартное — зовёшь менеджера, но старайся сам)"],"ordered":false},{"id":"course-114200-14","text":"Что важно помнить:","type":"heading","level":3},{"id":"course-114200-15","type":"list","items":["Контроль времени — следи за таймингом, предупреждай о задержках","Чистота столов — убирай сразу, как только гости доели","Коммуникация — улыбайся, будь вежлив, используй открытые вопросы","Стоп-лист — проверяй перед каждым заказом"],"ordered":false},{"id":"course-114200-16","text":"Максимальная загрузка: как выжить и победить 🔥","type":"heading","level":2},{"id":"course-114200-17","text":"Если одновременно много новых гостей и готовых блюд","type":"heading","level":3},{"id":"course-114200-18","text":"Распредели задачи с командой","type":"heading","level":3},{"id":"course-114200-19","type":"list","items":["Ожидаемую загрузку уточни на брифинге. В пик согласуй приоритеты так, чтобы новые гости получили внимание, а готовые блюда ушли вовремя."],"ordered":false},{"id":"course-114200-20","text":"Советы для работы в пик:","type":"heading","level":3},{"id":"course-114200-21","type":"list","items":["Не бегай — ходи быстро, но плавно. Бег создаёт панику и повышает риск ошибок.","Согласуй приоритеты с коллегами. Поприветствуйте новых гостей и распределите задачи, чтобы готовые блюда не ждали на раздаче.","Используй блокнот. Если много заказов — записывай, чтобы не забыть.","Не носи больше трёх тарелок сразу. Лучше сделать два подхода, чем всё уронить.","Помогай коллегам, даже если это не твой стол. Команда — наша сила. Но сегодня ты сам за себя, но взаимовыручка никем не отменялась.","Если не успеваешь — попроси помощи. Это нормально.","Дыши. В пике легко запаниковать. Остановись на секунду, глубокий вдох — и дальше."],"ordered":false},{"id":"course-114200-22","text":"Чек-лист самопроверки в конце смены ✅","type":"heading","level":2},{"id":"course-114200-23","html":"<p>Я открыл смену по чек-листу без напоминаний</p><p>Я обслужил свои столы от начала до конца без помощи наставника</p><p>Я контролировал время подачи и предупреждал о задержках</p><p>Я применял техники продаж (аппетитные описания, доп. продажи)</p><p>Я умею показать ссылку на отзыв своей точки и предложить оставить его без давления.</p><p>Я проверил остатки расходников перед закрытием</p><p>Я закрыл смену по чек-листу (уборка, фотоотчёт, ОС, отчёт старшему)</p>","type":"text"},{"id":"course-114200-24","text":"⚠️ Важно! Что делать, если...","type":"heading","level":2},{"id":"course-114200-25","html":"<p>...гость жалуется, а менеджера рядом нет?</p><p>Выслушай, поблагодари, предложи решение в рамках своих полномочий (позвать менеджера, уточнить на кухне). Не обещай того, в чём не уверен.</p><p>...ты ошибся в заказе, и блюдо уже готовится?</p><p>Если можешь исправить без последствий — исправь. Если нет — предупреди гостя, предложи альтернативу или комплимент (после согласования с менеджером).</p><p>...ты чувствуешь, что выгораешь к концу смены?</p><p>Держись! Ты почти у цели. Пей воду, делай микро-паузы. Помни, что после смены — заслуженный отдых.</p>","type":"text"},{"id":"course-114200-26","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114200-27","html":"<p>Сегодня ты доказываешь самому себе, что готов. Всё, чему ты учился — от правильного хвата тарелки до техник продаж — сегодня работает в полную силу. Доверяй своим знаниям, будь внимателен и профессионален.</p><p>И помни: самостоятельность — это не страшно, это свобода делать свою работу так, как ты умеешь лучше всего.</p><p>Ты справишься! Завтра — финальная аттестация. 💪</p><p>Следующая смена — решение о допуске. Ты готов!</p>","type":"text"}]},{"id":"114201","title":"Смена 15. Финальный трек","blocks":[{"id":"course-114201-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-15-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 15. Финальный трек"},{"id":"course-114201-2","text":"Финальное тестирование и решение о допуске 🎓","type":"heading","level":2},{"id":"course-114201-3","html":"<p>Сегодня проверь теоретическую подготовку по стандартам сервиса, меню, барной карте и iiko. Закрой обязательные тесты и разбери ошибки с наставником. Следующий этап — практическая аттестация в смене 16. Окончательный допуск и подписание чек-листа — после оценки практики руководителем.</p>","type":"text"},{"id":"merged-rvb---14","type":"heading","text":"Как пройти проверку в ASK Academy","level":2},{"id":"merged-rvb---15","type":"text","html":"<p>Открой раздел «Обучение» и тесты своей программы. Перед началом каждого теста проверь его условия и ограничение времени. Единого обещания «30 секунд на вопрос» или «две попытки» для всей программы нет — действуют настройки конкретного теста.</p><p>После завершения посмотри результат и работу над ошибками, повтори нужные занятия. Общая аттестация учитывает обязательные занятия и зачтённые тесты. Устные аттестации кухни и бара проводятся принимающими своего заведения; их результаты отображаются в профиле.</p><p>Отметка «Материал изучен» отражает изучение занятия. Практические навыки и решение о допуске подтверждает наставник и руководитель.</p>"},{"id":"course-114201-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114201-5","html":"<p>Пройти обязательные проверки своей программы, повторить темы с ошибками и получить обратную связь наставника. Подготовиться к практической аттестации следующей смены.</p>","type":"text"},{"id":"course-114201-12","text":"Что нужно повторить перед тестом 📚","type":"heading","level":2},{"id":"course-114201-13","text":"1. Стандарты сервиса","type":"heading","level":3},{"id":"course-114201-14","html":"<p>Шаги обслуживания (приветствие, приём заказа, подача, чек-бэк, расчёт, проводы)</p><p>Правила подачи и уборки посуды (с какой стороны, как держать)</p><p>Чек-бэк: зачем и как делать</p><p>Поведение при жалобах (не убирать самому, звать старшего)</p>","type":"text"},{"id":"course-114201-15","text":"2. Меню (закуски, салаты, горячие блюда)","type":"heading","level":3},{"id":"course-114201-16","html":"<p>Состав актуальных позиций меню своей точки</p><p>Время приготовления каждой категории</p><p>Блюда на компанию и их особенности</p><p>Акции и спецпредложения</p>","type":"text"},{"id":"course-114201-17","text":"3. Барная карта","type":"heading","level":3},{"id":"course-114201-18","html":"<p>Вина (3 белых, 3 красных, 3 игристых) — названия, характеристики, к чему рекомендовать</p><p>Авторские коктейли — состав, бокал, вкус</p><p>Крепкий алкоголь (базовые позиции)</p>","type":"text"},{"id":"course-114201-19","text":"4. Работа в iiko (POS)","type":"heading","level":3},{"id":"course-114201-20","html":"<p>Как открыть заказ, добавить блюдо, модификаторы</p><p>Как отправить на кухню</p><p>Применение скидок (процентные, бонусы, акционные).</p><p>Поиск гостя по номеру телефона для карты лояльности.</p><p>Проверка доступной суммы списания и оформление бонусов в пределах своих полномочий.</p>","type":"text"},{"id":"course-114201-21","text":"5. Программа лояльности","type":"heading","level":2},{"id":"course-114201-22","html":"<p>Проверь действующую программу лояльности своей точки и данные гостя в iiko, если условия зависят от его уровня. Назови подтверждённые условия начисления или списания. При сомнении уточни у менеджера.</p>","type":"text"},{"id":"course-114201-23","text":"Что проверить перед обещанием гостю","type":"heading","level":3},{"id":"course-114201-24","type":"list","items":["Действует ли программа на этой точке и для этого заказа.","Какой у гостя уровень и какие начисления доступны.","Сколько бонусов можно списать и сочетаются ли они с текущей акцией.","Кто оформляет операцию в iiko."],"ordered":false},{"id":"course-114201-25","text":"6. Открытие и закрытие смены","type":"heading","level":3},{"id":"course-114201-26","html":"<p>Чек-лист открытия (время, действия)</p><p>Контроль чистоты и расходников</p><p>Чек-лист закрытия (уборка, фотоотчёт, ОС)</p>","type":"text"},{"id":"course-114201-27","text":"Полезные советы перед тестом 💡","type":"heading","level":2},{"id":"course-114201-28","html":"<p>Отдохни. Уставший мозг хуже соображает.</p><p>Найти тихое место. Ничто не должно отвлекать.</p><p>Читай вопросы внимательно. Иногда правильный ответ прячется в деталях.</p><p>Не застревай на одном вопросе. Если не уверен — отметь примерно.</p><p>Дыши. Если волнуешься, сделай глубокий вдох.</p>","type":"text"},{"id":"course-114201-29","text":"Оценка знаний и сервиса 📊","type":"heading","level":2},{"id":"course-114201-30","text":"После теста твои результаты увидит менеджер. Он также оценит:","type":"heading","level":3},{"id":"course-114201-31","type":"list","items":["Твою работу в зале за всё время стажировки","Отзывы наставников","Твоё отношение к делу, пунктуальность, чистоту, коммуникабельность","На основе всего этого принимается решение о допуске."],"ordered":false},{"id":"course-114201-32","text":"Решение о допуске и подписание чек-листа ✅","type":"heading","level":2},{"id":"course-114201-33","html":"<p>Если ты успешно прошёл аттестацию и показал себя в работе, тебя допускают к самостоятельной работе. Это значит, что с этого момента ты — полноценный официант нашей команды! 🎉</p><p>Финальный шаг — подписание чек-листа стажёра. Это документ, подтверждающий, что ты прошёл все этапы обучения и готов работать самостоятельно. Чек-лист подписывают:</p><p>Ты (стажёр)</p><p>Твой наставник</p><p>Управляющий</p><p>После завершения практической аттестации и подтверждения руководителем тебя вводят в график и ты начинаешь работать как полноценный сотрудник.</p>","type":"text"},{"id":"course-114201-34","text":"Чек-лист: что ты сегодня сделаешь ✅","type":"heading","level":2},{"id":"course-114201-35","html":"<p>Я прошёл обязательные тесты своей программы в ASK Academy</p><p>Я повторил все ключевые темы (стандарты, меню, бар, iiko) 📚</p><p>Я получил результат теста и узнал свою оценку 📊</p><p>Я согласовал с наставником подготовку к практической аттестации</p><p>Я подготовил чек-лист для финальной оценки и подписания после практической аттестации</p>","type":"text"},{"id":"course-114201-36","text":"Финальный совет на смену 🌟","type":"heading","level":2},{"id":"course-114201-37","html":"<p>Ты проделал огромный путь. Первые дни, когда ты боялся подойти к гостю, — позади. Сегодня ты готов доказать, что достоин быть частью команды. Верь в себя, не суетись, и всё получится.</p><p>А после теоретической аттестации тебя ждёт практическая — Смена 16: обслуживание административного состава. Это твой звёздный час: покажи всё, на что способен, перед руководством! 🔥</p><p>А потом — обязательно отпразднуй это событие! Ты заслужил. 🥳</p><p>Удачи! Мы верим в тебя! 💪</p><p>Следующая смена — твоя практическая аттестация с администрацией. Ждём тебя в команде!</p>","type":"text"}]},{"id":"114202","title":"Смена 16. Выпускной","blocks":[{"id":"course-114202-1","tone":"sky","type":"hero","image":"assets/extra-courses/waiter-internship-16-0.jpg","label":"Стандарты и стажировка официанта","title":"Смена 16. Выпускной"},{"id":"course-114202-2","text":"Практическая аттестация — обслуживание административного состава 🎯👔","type":"heading","level":2},{"id":"course-114202-3","html":"<p>Поздравляю! Это финальный экзамен. Твои гости — административный состав (управляющие, менеджеры, топ‑персонал). Они будут оценивать не только знание стандартов, но и твою уверенность, скорость, умение держаться и продавать. Покажи всё, чему научился за стажировку. Это твой выход на сцену! 🔥</p>","type":"text"},{"id":"course-114202-4","text":"Цель смены 🎯","type":"heading","level":2},{"id":"course-114202-5","html":"<p>Продемонстрировать все навыки обслуживания в реальной ситуации</p><p>Подтвердить готовность к самостоятельной работе</p><p>Получить финальное «добро» от руководства</p>","type":"text"},{"id":"course-114202-6","text":"Памятка: что нужно сделать обязательно ✅","type":"heading","level":2},{"id":"course-114202-7","text":"1. Подготовка к смене 🧹","type":"heading","level":3},{"id":"course-114202-8","html":"<p>Перед сменой проверь время выхода и сбора в актуальном графике своей точки. Если график и памятка расходятся или предстоит банкет, заранее уточни время у ответственного за смену.</p><p>Переоденься, проверь внешний вид (чисто, глажено, дресс‑код).</p>","type":"text"},{"id":"course-114202-9","text":"Пройди по чек‑листу открытия:","type":"heading","level":3},{"id":"course-114202-10","type":"list","items":["опустить стулья, протереть столы,","разложить тарелки, приборы, текстиль,","выставить салфетницы, тейбл‑тенты,","проверить стоп‑лист и наличие расходников.","Участвуй в брифинге в согласованное время.","Прокати карту и открой личную смену в iiko."],"ordered":false},{"id":"course-114202-11","text":"2. Встреча гостей (администрации) 😊","type":"heading","level":3},{"id":"course-114202-12","html":"<p>Когда администрация сядет за твой стол, подойди с улыбкой в течение 1–2 минут.</p><p>Приветствие: «Добрый вечер, меня зовут [Имя], сегодня я буду вас обслуживать. Приятно видеть!»</p><p>Подай меню открытой рукой, предложи аперитив/воду.</p>","type":"text"},{"id":"course-114202-13","text":"3. Приём заказа 📝","type":"heading","level":3},{"id":"course-114202-14","html":"<p>Используй открытые вопросы: «Что бы вы хотели попробовать из новинок?»</p><p>Применяй аппетитные описания (например, для стейка из лосося, авторских коктейлей).</p><p>Уточни детали: прожарка мяса, аллергии, пожелания.</p><p>Повтори заказ перед отправкой.</p><p>Зафиксируй в iiko: количество гостей, все позиции, модификаторы.</p><p>Предупреди о времени ожидания, если блюдо готовится долго (стейк, горячее).</p>","type":"text"},{"id":"course-114202-15","text":"4. Подача и сервис 🍽️","type":"heading","level":3},{"id":"course-114202-16","html":"<p>Напитки принеси в течение 3–5 минут.</p><p>Подавай блюда синхронно (сначала закуски, потом горячее, десерт).</p><p>Используй правильную технику: подходи справа, тарелки ставь аккуратно, проговаривай название блюда.</p><p>Следи за чистотой стола: убирай пустые тарелки, доливай воду, меняй пепельницы.</p><p>Проводи чек-бэк через 2–3 минуты после подачи: «Как вам вкус и температура блюда?»</p><p>Если возникла проблема — действуй по алгоритму: выслушай, поблагодари, сообщи менеджеру (но сегодня ты сам должен решить в рамках своих полномочий, а менеджер наблюдает).</p>","type":"text"},{"id":"course-114202-17","text":"5. Работа с допродажами 💰","type":"heading","level":3},{"id":"course-114202-18","text":"Предложи дополнительные позиции:","type":"heading","level":3},{"id":"course-114202-19","type":"list","items":["«К вашему вину отлично подойдёт сырное плато»,","«Хотите добавить фирменный соус или овощи гриль?»,","«К вашему заказу могу предложить десерт из сегодняшнего меню».","Если гость просит рекомендацию по вину или коктейлю, уверенно посоветуй (вспомни мини‑квиз)."],"ordered":false},{"id":"course-114202-20","text":"6. Расчёт 💳","type":"heading","level":3},{"id":"course-114202-21","html":"<p>Когда гость просит счёт, проверь позиции и применимые условия бронирования, в том числе депозит, если они были согласованы.</p><p>Если в счёте акция, заранее уточни её условия и доступные способы оплаты. Бонусы сверяй по действующей программе точки и данным гостя.</p><p>Уточни способ оплаты и формат счёта. На экзаменационной смене окончательный расчёт и закрытие стола проводит менеджер.</p>","type":"text"},{"id":"course-114202-22","text":"7. Прощание и уборка 👋","type":"heading","level":3},{"id":"course-114202-23","html":"<p>Поблагодари гостей: «Спасибо, что были у нас! Приходите ещё, будем рады!»</p><p>Убери стол сразу после ухода гостей, подготовь его к следующей посадке.</p>","type":"text"},{"id":"course-114202-24","text":"В конце смены выполни закрытие по чек‑листу:","type":"heading","level":3},{"id":"course-114202-25","type":"list","items":["протереть столы, стейшены,","вымыть ножки стульев,","почистить диваны,","натереть посуду,","нагладить текстиль,","сделать фотоотчёт,","написать ОС о смене,","отчитаться старшему официанту/менеджеру."],"ordered":false},{"id":"course-114202-26","text":"8. Самоанализ 📝","type":"heading","level":3},{"id":"course-114202-27","html":"<p>После обслуживания подойди к менеджеру (экзаменатору) и спроси: «Есть ли замечания? Что я могу улучшить?»</p><p>Выслушай обратную связь спокойно, без оправданий. Запомни зоны роста.</p>","type":"text"},{"id":"course-114202-28","text":"⚠️ Важные моменты, на которые будут смотреть","type":"heading","level":2},{"id":"course-114202-29","html":"<p>Уверенность и спокойствие (не суетись, говори чётко).</p><p>Знание меню и барной карты (состав, вкусы, рекомендации).</p><p>Соблюдение стандартов (правильная подача, уборка, гигиена).</p><p>Скорость реакции (быстрое выполнение просьб).</p><p>Навыки продаж (предложения доп. позиций).</p><p>Чистота и порядок на столе и станции.</p><p>Взаимодействие с командой (если нужна помощь – попроси, но не злоупотребляй).</p>","type":"text"},{"id":"course-114202-30","text":"Чек-лист самопроверки после смены ✅","type":"heading","level":2},{"id":"course-114202-31","html":"<p>Я встретил гостей с улыбкой и представился.</p><p>Я правильно принял заказ, повторил его и внёс в iiko.</p><p>Я контролировал время подачи и предупреждал о задержках.</p><p>Я применил техники продаж (аппетитное описание, доп. продажи).</p><p>Я следил за чистотой стола и вовремя убирал посуду.</p><p>Я провёл чек-бэк и отреагировал на возможные замечания.</p><p>Я проверил счёт и применимые условия, передал окончательный расчёт менеджеру.</p><p>Я попрощался и пригласил приходить снова.</p><p>Я закрыл смену по чек-листу и сдал отчёт.</p>","type":"text"},{"id":"course-114202-32","text":"Напутствие 🌟","type":"heading","level":2},{"id":"course-114202-33","html":"<p>Сегодня ты показываешь всё, чему научился. Не бойся ошибиться — ошибки бывают у всех. Главное — твоё отношение, старание и желание стать лучше. Администрация будет оценивать не идеальность, а твой потенциал.</p><p>Ты готов! Выходи и зажги! 🔥💪</p><p>После этой смены — финальное решение. Мы верим в тебя!</p>","type":"text"}]}],"mergedFromIds":["rvb--waiter-standards"],"mergedLessonIds":{"42956":"114183","42957":"114185","42958":"114188","42959":"114188"},"mergeRevision":"waiter-service-20261117","referenceCompletion":{"lessonIds":["114183","114185","114188"],"testIds":["rvb--100075","rvb--100153","rvb--100159"]},"legacyLessonCredits":{"114183":[["42956"]],"114185":[["42957"]],"114188":[["42959","42958"]]},"routeAliases":["waiter-standards"],"legacyLessonCourseId":"rvb--waiter-standards"}},"expectedUpdatedAt":"2026-11-17T15:01:19.443047+00:00"},{"record":{"id":"rvb--100075","kind":"test","title":"Правила и работа в команде","payload":{"id":"rvb--100075","brand":"rvb","title":"Правила и работа в команде","priority":"attestation","passCount":15,"questions":[{"id":"100075-1","text":"К согласованному времени зал готов, но терминал не работает. Что делать?","type":"single","options":["Отметить зал готовым и проверить терминал при первом расчёте","Сообщить старшему и уточнить, как принимать оплату до устранения сбоя","Самостоятельно перенести открытие зала"]},{"id":"100075-2","text":"Какой внешний вид считается нарушением стандартов?","type":"single","options":["Неряшливая форма, неухоженные волосы, грязная обувь","Джинсовка и аксессуары в стиле 90-х","Минимальный макияж"]},{"id":"100075-3","text":"Что считается нарушением дисциплины?","type":"single","options":["Смена без бейджа","Опоздание без предупреждения менеджера","Отсутствие аксессуаров 90-х в образе"]},{"id":"100075-4","text":"На перерыве ты понадобился за одним из своих столов. Как это предусмотреть заранее?","type":"single","options":["Попросить гостей подождать твоего возвращения","Оставить включённым телефон","Передать столы конкретному коллеге и убедиться, что он принял подмену"]},{"id":"100075-5","text":"К какому времени должен быть готов зал РВБ Минск?","type":"single","options":["16:00","16:30","16:45","17:00"]},{"id":"100075-6","text":"Что делать, если форма испачкалась во время смены?","type":"single","options":["Продолжить работать до конца смены","Спрятать пятно под фартуком","Привести форму в порядок или заменить на чистую"]},{"id":"100075-7","text":"Что необходимо сделать после перекура, прежде чем вернуться к работе?","type":"single","options":["Освежить дыхание и убедиться, что одежда не пахнет дымом","Проверить телефон","Сразу вернуться в зал"]},{"id":"100075-8","text":"Что нужно сделать, если понимаешь, что опаздываешь на смену?","type":"single","options":["Прийти как можно быстрее, не предупреждая","Немедленно сообщить менеджеру и уточнить, требуется ли замена","Написать коллеге, чтобы передал сообщение"]},{"id":"100075-9","text":"Почему внешний вид официанта — часть стандарта обслуживания?","type":"single","options":["Потому что гость оценивает качество заведения по чистоте и опрятности персонала","Потому что так удобнее для фотоотчётов","Потому что это требование менеджера"]},{"id":"100075-10","text":"Почему запрещено ходить курить толпой?","type":"single","options":["Это может не понравиться гостям","Потому что зал должен оставаться под контролем — кто-то обязан быть на месте","Так требует охрана"]},{"id":"92988-5","text":"Гость перестал поддерживать шутки и отвечает коротко. Как продолжить обслуживание?","type":"single","options":["Перейти на спокойный доброжелательный тон и дать гостю пространство","Продолжить шутить, чтобы его разговорить","Свести общение к подаче и расчёту"]},{"id":"92988-7","text":"Как официант должен действовать, если не знает ответа на вопрос гостя?","type":"single","options":["Сказать то, что первое придет в голову, главное - уверенно","Перевести тему","Уточнить у менеджера и вернуться с ответом"]},{"id":"92988-8","text":"Где уточнить, разрешён ли аксессуар для смены в твоём заведении?","type":"single","options":["По фотографиям команды","По памятке другой точки","По действующему стандарту формы своей точки, при сомнении у менеджера"]},{"id":"92988-9","text":"Перед открытием сломалось крепление аксессуара на форме. Что сделать?","type":"single","options":["Снять аксессуар и согласовать замену, если он обязателен","Оставить его до первого перерыва","Закрепить подручным способом и сразу выйти в зал"]},{"id":"92988-10","text":"Ты заметил, что гости за столом коллеги пытаются привлечь внимание. Как поступить?","type":"single","options":["Дождаться, пока коллега сам увидит гостей","Подойти, уточнить просьбу и передать её ответственному официанту","Сразу забрать стол и вести его до расчёта"]}],"restaurantIds":["minsk"],"trainingBrand":"rvb","timeLimitSeconds":450,"trainingSourceId":"100075","requiredRestaurantIds":["minsk"],"completionCredits":[["rvb--92988"]],"mergedFromIds":["rvb--92988"],"routeAliases":["92988"],"legacyTestTitles":{"rvb--92988":"Тест 1. Правила работы официанта"}},"course_id":"rvb--waiter-internship","published":true,"department":null,"updated_at":"2026-11-17T15:01:19.443047+00:00","restaurant_id":"minsk"},"keys":{"100075-1":[1],"100075-2":[0],"100075-3":[1],"100075-4":[2],"100075-5":[2],"100075-6":[2],"100075-7":[0],"100075-8":[1],"100075-9":[0],"100075-10":[1],"92988-5":[0],"92988-7":[2],"92988-8":[2],"92988-9":[0],"92988-10":[1]},"expectedUpdatedAt":"2026-11-17T15:01:19.443047+00:00"},{"record":{"id":"rvb--100153","kind":"test","title":"Открытие смены","payload":{"id":"rvb--100153","brand":"rvb","title":"Открытие смены","priority":"attestation","passCount":8,"questions":[{"id":"100153-3","text":"Как должен выглядеть порядок в подсобке?","type":"single","options":["Обувь на полке, вещи на вешалке, ничего не валяется","Всё должно быть разложено","Проверяются только шкафчики","Проверка не требуется"]},{"id":"100153-4","text":"Какой уровень наполнения соли и перца считается правильным?","type":"single","options":["Только если заканчивается","Полный","На ¾ емкости","Наполовину"]},{"id":"100153-5","text":"Как проверяется исправность терминала перед сменой?","type":"single","options":["Проверять только при необходимости","Убедиться, что работает и есть чековая лента","Просто включить","Проверить только наличие ленты"]},{"id":"100153-6","text":"Какой инструмент помогает официанту держать всё под контролем при открытии смены?","type":"single","options":["Чек-лист","График смен","Лист заказов","Инструкция по безопасности"]},{"id":"100153-8","text":"После мойки приборы чистые, но на них остались капли воды. Что сделать перед сервировкой?","type":"single","options":["Разложить приборы, чтобы высохли на столе","Просушить и отполировать чистой салфеткой по стандарту точки","Сразу сложить во влажный лоток"]},{"id":"100153-9","text":"Какое должно быть состояние меню при открытии зала?","type":"single","options":["Достаточно просто заменить грязные","Можно использовать даже слегка повреждённые меню","Чистое, без рваных страниц, протёртое влажной тряпкой","Меню не требует проверки"]},{"id":"100153-10","text":"Какие элементы зала необходимо проверить перед открытием?","type":"single","options":["Только стулья","Только столы и салфетки","Только терминалы","Пол, стулья, столы, подоконники"]},{"id":"92998-7","text":"При сервировке ты заметил на приборе следы еды. Что сделать?","type":"single","options":["Отполировать его салфеткой","Отложить до конца подготовки","Отправить прибор на повторную мойку и взять чистый"]}],"restaurantIds":["minsk"],"trainingBrand":"rvb","timeLimitSeconds":240,"trainingSourceId":"100153","requiredRestaurantIds":["minsk"],"completionCredits":[["rvb--92998"]],"mergedFromIds":["rvb--92998"],"routeAliases":["92998"],"legacyTestTitles":{"rvb--92998":"Тест 2. Открытие смены"}},"course_id":"rvb--waiter-internship","published":true,"department":null,"updated_at":"2026-11-17T15:01:19.443047+00:00","restaurant_id":"minsk"},"keys":{"100153-3":[0],"100153-4":[2],"100153-5":[1],"100153-6":[0],"100153-8":[1],"100153-9":[2],"100153-10":[3],"92998-7":[2]},"expectedUpdatedAt":"2026-11-17T15:01:19.443047+00:00"},{"record":{"id":"rvb--100159","kind":"test","title":"Обслуживание и чек-бэк","payload":{"id":"rvb--100159","brand":"rvb","title":"Обслуживание и чек-бэк","priority":"attestation","passCount":16,"questions":[{"id":"100159-1","text":"Как официант должен сообщать о времени приготовления?","type":"single","options":["Обещать минимальное время","Говорить «скоро будет»","Честно сказать реальное время"]},{"id":"100159-2","text":"Как официант должен заходить к гостю?","type":"single","options":["С улыбкой и на позитиве, создавая атмосферу 90-х","Без эмоций, сразу подавая меню","Спокойно и официально"]},{"id":"100159-3","text":"Как правильно делать чек-бэк?","type":"single","options":["Проявлять искренний интерес, считывать эмоции гостя","Спрашивать только, если гость выглядит недовольным","Спросить «Всё в порядке?»"]},{"id":"100159-4","text":"Что важно сделать при подаче меню?","type":"single","options":["Спросить, хочет ли гость что-то заказать сразу","Оставить на столе без слов","Подавать открытой рукой, предложить освежающий напиток"]},{"id":"100159-5","text":"Как лучше всего задавать вопросы гостю во время чек-бэка?","type":"single","options":["Чётко и официально","Строго по шаблону","С искренним интересом, без шаблонных фраз"]},{"id":"100159-6","text":"Зачем делать контрольный чек-бэк?","type":"single","options":["Уточнить сумму счета","Проверить, понравился ли официант","Закрепить положительное впечатление перед уходом"]},{"id":"100159-7","text":"Гость попробовал блюдо и отодвинул тарелку. Как начать чек-бэк?","type":"single","options":["Сразу спросить, можно ли убрать тарелку","Сразу предложить замену","Спокойно уточнить, как ему блюдо, и выслушать ответ"]},{"id":"100159-8","text":"Когда официант должен делать текущий чек-бэк?","type":"single","options":["Через 2-3 минуты после первой вилки еды","После того, как гость полностью съел блюдо","Сразу после подачи блюда"]},{"id":"100159-9","text":"Что такое Check Back (чек-бэк)?","type":"single","options":["Обратная связь с гостем о качестве еды и сервиса","Проверка счета гостя","Оценка работы персонала"]},{"id":"100159-10","text":"Какой приём помогает увеличить продажу блюд?","type":"single","options":["Просто назвать позиции из меню, гость разберется по ходу заказа","Дать гостю меню и уйти, тогда он сам закажет все, что нужно","Описание блюд с эмоциями и аппетитными деталями"]},{"id":"92995-6","text":"Как правильно проводить расчёт гостя?","type":"single","options":["Только при повторном запросе","Без задержек, уточнив тип оплаты","Подождать, пока гость напомнит"]},{"id":"92993-5","text":"Что делать, если гость не в восторге от твоей рекомендации?","type":"single","options":["Переубедить его","Посоветовать что-то другое","Принять спокойно и учесть для будущих советов","Спросить, почему он выбрал это блюдо"]},{"id":"92993-6","text":"Какой стиль общения рекомендуется при чек-бэке?","type":"single","options":["Формальный и строгий","Минимальный, без эмоций","Дружеский, искренний, ненавязчивый","Только при необходимости"]},{"id":"92993-7","text":"Что делать, если гость недоволен блюдом?","type":"single","options":["Выяснить причину и сообщить менеджеру","Сказать, что так и должно быть","Извиниться и уйти","Заменить блюдо без уведомления"]},{"id":"92993-9","text":"Когда официант делает поэтапный чек-бэк?","type":"single","options":["После выдачи чека","До подачи блюда","Когда убирает тарелку у гостя","В начале смены"]},{"id":"92993-10","text":"Что делать, если гость не доел блюдо?","type":"single","options":["Немедленно предложить другое блюдо","Спросить причину ненавязчиво","Просто забрать тарелку","Ничего не делать"]}],"restaurantIds":["minsk"],"trainingBrand":"rvb","timeLimitSeconds":480,"trainingSourceId":"100159","requiredRestaurantIds":["minsk"],"completionCredits":[["rvb--92995","rvb--92993"]],"mergedFromIds":["rvb--92995","rvb--92993"],"routeAliases":["92995","92993"],"legacyTestTitles":{"rvb--92995":"Тест 3. Обслуживание гостей","rvb--92993":"Тест 4. Чек бэк"}},"course_id":"rvb--waiter-internship","published":true,"department":null,"updated_at":"2026-11-17T15:01:19.443047+00:00","restaurant_id":"minsk"},"keys":{"100159-1":[2],"100159-2":[0],"100159-3":[0],"100159-4":[2],"100159-5":[2],"100159-6":[2],"100159-7":[2],"100159-8":[0],"100159-9":[0],"100159-10":[2],"92995-6":[1],"92993-5":[2],"92993-6":[2],"92993-7":[0],"92993-9":[2],"92993-10":[1]},"expectedUpdatedAt":"2026-11-17T15:01:19.443047+00:00"},{"record":{"id":"rvb--waiter-standards","kind":"course","title":"Стандарты работы официанта","course_id":null,"published":false,"department":null,"updated_at":"2026-11-17T20:01:40.500292+00:00","restaurant_id":"minsk","payload":{"id":"rvb--waiter-standards","pass":80,"brand":"rvb","title":"Стандарты работы официанта","outline":[{"type":"lesson","title":"Урок 1. Правила работы официанта","lessonIndex":0},{"id":"rvb--92988","type":"test","title":"Тест 1. Правила работы официанта"},{"type":"lesson","title":"Урок 2. Стандарты открытия смены","lessonIndex":1},{"id":"rvb--92998","type":"test","title":"Тест 2. Открытие смены"},{"type":"lesson","title":"Урок 3. Обслуживание гостей","lessonIndex":2},{"id":"rvb--92995","type":"test","title":"Тест 3. Обслуживание гостей"},{"type":"lesson","title":"Урок 4. Чек-бэк и его важность","lessonIndex":3},{"id":"rvb--92993","type":"test","title":"Тест 4. Чек бэк"}],"testIds":["92988","92998","92995","92993"],"priority":"start","sequence":[{"id":"42956","type":"lesson"},{"id":"rvb--92988","type":"test"},{"id":"42957","type":"lesson"},{"id":"rvb--92998","type":"test"},{"id":"42959","type":"lesson"},{"id":"rvb--92995","type":"test"},{"id":"42958","type":"lesson"},{"id":"rvb--92993","type":"test"}],"positions":["Официант","Администратор зала","Хостес"],"questions":[],"departments":["Зал"],"description":"Правила работы, открытие смены, обслуживание гостей и чек-бэк. Исходные материалы вашей команды «90-е».","restaurantIds":["minsk"],"trainingBrand":"rvb","audienceLevels":["trainee","certified"],"trainingSourceId":"waiter-standards","audiencePositions":["Официант","Администратор зала"],"audiencePriorities":{},"requiredRestaurantIds":["minsk"],"lessons":[{"id":"42956","text":"Кто такой официант?\nТы стал частью реально клёвой команды официантов \"Бара 90-е\". Это не просто работа – это тусовка, где ты не только разносишь заказы, но и создаёшь атмосферу 90-х! Гость должен чувствовать себя как на вечеринке у старых друзей, и ты – главный ведущий этого движа. Делай так, чтобы гость запомнил этот вечер, захотел вернуться и притащил с собой друзей! Для этого важно знать основные правила, выглядеть как надо и владеть всеми нужными навыками.\nКакие правила?\nПриход на работу 🏃‍♂️ В РВБ Минск с воскресенья по четверг приходи к 16:00, в пятницу и субботу — к 15:30. Зал должен быть готов к 16:45. Если на конкретную смену согласован особый график, уточни его у менеджера. Опаздываешь? Проблема! Заранее предупреди менеджера, если не успеваешь. Опоздания портят атмосферу и работу всей команды. Здесь важен командный дух, поэтому подводить своих не вариант. Если заранее нашел себе замену – молодец, но все равно предупреди. Перекуры 🚬 Согласуй короткий перерыв со старшим. Передай столы конкретному коллеге и убедись, что он принял подмену. Сообщи, что уже заказано, чего ждут гости и о чём они просили. Не ходи курить группой, ты же не на перемене в школе! После перекура – жвачка или спрей для свежести Общение с гостями 🗣 Всегда улыбаемся! Даже если день не задался – твоя улыбка делает атмосферу. Используем лёгкий сленг 90-х – так гости сразу понимают, что здесь их ждёт ностальгия Если что-то не знаешь, уточни у менеджера, а если это происходит в разговоре с Гостями - предупреди, что уточнишь и вернешься с ответом. Держим лицо в любой ситуации – даже если гость капризный, решаем всё с позитивом и юмором Это еще не все правила, которые ты должен соблюдать. Чтобы изучить их, переходи в Библиотеку , там есть Правила сотрудника на смене\nКак должен выглядеть официант \"Бара 90-е\"?\nФизическая форма – Симпатяга Чистая кожа (желательно наличие штукатурки), уложенные волосы, ухоженные ногти Свежий аромат – без перегибов с резким парфюмом. Стильный прикид в духе 90-х: джинсовки, яркие цвета, модные аксессуары. Форма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же. Форма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.\nДля нас официант – это:\nГлавный моторчик движа, без которого не будет улетной атмосферы.\nВеселый друг, которому не фиолетово, что происходит в зале – он понимает, что всё зависит от него.\nЧеловек, который сам тащится от заведения и заряжает этой любовью гостей. Они возвращаются снова и снова, потому что здесь кайф!\nДля наших гостей официант – это:\nЭмоции: Лучший друг\nСвой в доску, всегда на позитиве, улыбается и создаёт уютную атмосферу домашнего праздника.\nЛичностные качества: Радушный хозяин\nВнимательный – сразу видит, что нужно гостю, и приносит это моментально.\nЧестный – никаких мутных тем, репутация заведения на кону.\nДержит лицо – даже если устал или день не задался, гостю этого видеть не положено.\nНе сыплет негативом – бар должен быть местом кайфа, а не разборок.\nРазруливает конфликты ещё до того, как они завелись.\nОткрытый – сам заводит разговор, легко общается, помогает выбрать блюдо.\nПрофнавыки: Знает и умеет\nРазбирается в меню как настоящий профи: знает, что вкусное, как готовят, за сколько минут принесут.\nМастер подачи: напитки и блюда на столе всегда быстро, красиво и в правильном порядке.\nЧек закроет в два счёта, а стол поддержит в идеальной чистоте","title":"Урок 1. Правила работы официанта","blocks":[{"id":"course-42956-1","tone":"sky","type":"hero","image":"assets/waiter/lesson-1-0.jpg","label":"Стандарты работы официанта","title":"Урок 1. Правила работы официанта"},{"id":"course-42956-2","text":"Кто такой официант?","type":"heading","level":2},{"id":"course-42956-3","html":"<p>Ты стал частью реально клёвой команды официантов \"Бара 90-е\". Это не просто работа – это тусовка, где ты не только разносишь заказы, но и создаёшь атмосферу 90-х! Гость должен чувствовать себя как на вечеринке у старых друзей, и ты – главный ведущий этого движа.</p><p>Делай так, чтобы гость запомнил этот вечер, захотел вернуться и притащил с собой друзей! Для этого важно знать основные правила, выглядеть как надо и владеть всеми нужными навыками.</p>","type":"text"},{"id":"course-42956-4","text":"Какие правила?","type":"heading","level":2},{"id":"course-42956-5","html":"<p>Приход на работу 🏃‍♂️</p><p>В РВБ Минск приходи на работу к 15:30. Зал должен быть готов к 16:45.</p><p>Если на конкретную смену согласован особый график, уточни его у менеджера.</p><p>Опаздываешь? Проблема! Заранее предупреди менеджера, если не успеваешь. Опоздания портят атмосферу и работу всей команды. Здесь важен командный дух, поэтому подводить своих не вариант.</p><p>Если заранее нашел себе замену – молодец, но все равно предупреди.</p><p>Перекуры 🚬</p><p>Согласуй короткий перерыв со старшим. Передай столы конкретному коллеге и убедись, что он принял подмену. Сообщи, что уже заказано, чего ждут гости и о чём они просили.</p><p>Не ходи курить группой, ты же не на перемене в школе!</p><p>После перекура – жвачка или спрей для свежести</p><p>Общение с гостями 🗣</p><p>Всегда улыбаемся! Даже если день не задался – твоя улыбка делает атмосферу.</p><p>Используем лёгкий сленг 90-х – так гости сразу понимают, что здесь их ждёт ностальгия</p><p>Если что-то не знаешь, уточни у менеджера, а если это происходит в разговоре с Гостями - предупреди, что уточнишь и вернешься с ответом.</p><p>Держим лицо в любой ситуации – даже если гость капризный, решаем всё с позитивом и юмором</p><p>Это еще не все правила, которые ты должен соблюдать. Чтобы изучить их, переходи в Библиотеку , там есть Правила сотрудника на смене</p>","type":"text"},{"id":"course-42956-6","text":"Как должен выглядеть официант?","type":"heading","level":2},{"id":"course-42956-7","html":"<p>Физическая форма – Симпатяга</p><p>Чистая кожа (желательно наличие штукатурки), уложенные волосы, ухоженные ногти</p><p>Свежий аромат – без перегибов с резким парфюмом.</p><p>Стильный прикид в духе 90-х: джинсовки, яркие цвета, модные аксессуары.</p><p>Форма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.</p><p>Форма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.</p>","type":"text"},{"id":"course-42956-8","src":"assets/waiter/lesson-1-1.jpg","type":"image","caption":""},{"id":"course-42956-9","src":"assets/waiter/lesson-1-2.jpg","type":"image","caption":""},{"id":"course-42956-10","src":"assets/waiter/lesson-1-3.jpg","type":"image","caption":""},{"id":"course-42956-11","text":"Для нас официант – это:","type":"heading","level":2},{"id":"course-42956-12","type":"list","items":["Главный моторчик движа, без которого не будет улетной атмосферы.","Веселый друг, которому не фиолетово, что происходит в зале – он понимает, что всё зависит от него.","Человек, который сам тащится от заведения и заряжает этой любовью гостей. Они возвращаются снова и снова, потому что здесь кайф!"],"ordered":false},{"id":"course-42956-13","src":"assets/waiter/lesson-1-4.jpg","type":"image","caption":""},{"id":"course-42956-14","text":"Для наших гостей официант – это:","type":"heading","level":2},{"id":"course-42956-15","type":"list","items":["Эмоции: Лучший друг","Свой в доску, всегда на позитиве, улыбается и создаёт уютную атмосферу домашнего праздника.","Личностные качества: Радушный хозяин","Внимательный – сразу видит, что нужно гостю, и приносит это моментально.","Честный – никаких мутных тем, репутация заведения на кону.","Держит лицо – даже если устал или день не задался, гостю этого видеть не положено.","Не сыплет негативом – бар должен быть местом кайфа, а не разборок.","Разруливает конфликты ещё до того, как они завелись.","Открытый – сам заводит разговор, легко общается, помогает выбрать блюдо.","Профнавыки: Знает и умеет","Разбирается в меню как настоящий профи: знает, что вкусное, как готовят, за сколько минут принесут.","Мастер подачи: напитки и блюда на столе всегда быстро, красиво и в правильном порядке.","Чек закроет в два счёта, а стол поддержит в идеальной чистоте"],"ordered":false}],"images":["assets/waiter/lesson-1-0.jpg","assets/waiter/lesson-1-1.jpg","assets/waiter/lesson-1-2.jpg","assets/waiter/lesson-1-3.jpg","assets/waiter/lesson-1-4.jpg"]},{"id":"42957","text":"Открытие зала\n\nЧек-лист – твой лучший инструмент, чтобы держать всё под контролем! Это список вещей, которые нельзя пропустить при открытии смены.\n\nМебель. Опустить стулья, выровнять мебель, почистить ее средством, протереть подножья столов и стульев \nСтолы. Протереть их чистой влажной тряпкой \nЗасервировать столы. Постановочная тарелка, столовые приборы (нож, вилка), хайбол, тейблтенты с актуальной информацией, салфетница, текстильная салфетка. Приборы ополаскиваем в кипятке либо брызгаем разведенным уксусом\nПроверить и заполнить расходники в стейшене, также в стейшенах всегда должна быть чистая вода в ведре для уборки столов\nПривести в порядок декор зала, протереть пыль \nРасставить таблички с надписями на барный стол \nВсё в порядке? Значит, ты готов к улётной смене! 🚀","title":"Урок 2. Стандарты открытия смены","blocks":[{"id":"course-42957-1","tone":"sky","type":"hero","image":"assets/waiter/lesson-2-0.jpg","label":"Стандарты работы официанта","title":"Урок 2. Стандарты открытия смены"},{"id":"course-42957-2","text":"Открытие зала","type":"heading","level":2},{"id":"course-42957-3","html":"<p>Чек-лист – твой лучший инструмент, чтобы держать всё под контролем! Это список вещей, которые нельзя пропустить при открытии смены.</p><p>Мебель. Опустить стулья, выровнять мебель, почистить ее средством, протереть подножья столов и стульев</p><p>Столы. Протереть их чистой влажной тряпкой</p><p>Засервировать столы. Постановочная тарелка, столовые приборы (нож, вилка), хайбол, тейблтенты с актуальной информацией, салфетница, текстильная салфетка. Приборы ополаскиваем в кипятке либо брызгаем разведенным уксусом</p><p>Проверить и заполнить расходники в стейшене, также в стейшенах всегда должна быть чистая вода в ведре для уборки столов</p><p>Привести в порядок декор зала, протереть пыль</p><p>Расставить таблички с надписями на барный стол</p>","type":"text"},{"id":"course-42957-4","text":"Всё в порядке? Значит, ты готов к улётной смене! 🚀","type":"heading","level":2}],"images":["assets/waiter/lesson-2-0.jpg"]},{"id":"42959","text":"Как сделать так, чтобы гость вернулся? 🎤🔥\n\nЛистай шаги обслуживания и запоминай\n\nВрываемся с улыбкой! 😃\nЗаходим на позитиве – дарим гостю хорошее настроение с порога и представляемся!\nМеню подаём открытой рукой\nБонус: пока гость листает меню, предлагай что-нибудь освежающее – сразу +1 к продажам!\nВыясняем, чего душа хочет, помогаем выбрать блюда\nРаскачиваем эмоции – аппетитные описания блюд, от которых слюнки потекут.\nБонус: «Хотите крутой гарнир или эксклюзивный соус к этому?» – больше вкуса, больше кайфа, больше продаж!\nВремя приготовления – если задержка, сразу говорим реальное время, гость будет благодарен за честность.\nПовторяем заказ – чтобы не испортить впечатления от возможной ошибки!\nБлюда подаём открытой рукой, как профессионалы.\nВсё приносим синхронно – никто не ждёт, все довольны!\nПервыми – закуски, потом горячее, потом десерты – чистый ритм сервиса!\n«Ну как? Огонь? 🔥» – не просто спрашиваем, а реально чувствуем эмоции гостя!\nЕсли что-то не так – сразу решаем вопрос.\nГасим возможные конфликты ещё до их появления.\nПодробнее о чек бэке - в следующем уроке\nГость попросил счёт? Не стоим, несём моментально!\nЕсли в точке действует программа лояльности, уточни у гостя, пользуется ли он ей. Перед расчётом проверь условия акции и назови доступные способы оплаты.\n«Наличные или карта, общий или раздельный?» – всё чётко, без лишних вопросов.\n«Спасибо, что заглянули, ждём снова!» – главное, чтобы звучало искренне.\nФинальный аккорд: Улыбка, кивок, возможно даже стильный жест рукой – гость должен уходить с ощущением, что его реально ждали!\nПересервируем стол за 2-3 минуты – новые гости уже на подходе!","title":"Урок 3. Обслуживание гостей","blocks":[{"id":"course-42959-1","tone":"sky","type":"hero","image":"assets/waiter/lesson-3-0.jpg","label":"Стандарты работы официанта","title":"Урок 3. Обслуживание гостей"},{"id":"course-42959-2","text":"Как сделать так, чтобы гость вернулся? 🎤🔥","type":"heading","level":2},{"id":"course-42959-3","text":"Листай шаги обслуживания и запоминай","type":"heading","level":2},{"id":"course-42959-4","html":"<p>Врываемся с улыбкой! 😃</p><p>Заходим на позитиве – дарим гостю хорошее настроение с порога и представляемся!</p><p>Меню подаём открытой рукой</p><p>Бонус: пока гость листает меню, предлагай что-нибудь освежающее – сразу +1 к продажам!</p><p>Выясняем, чего душа хочет, помогаем выбрать блюда</p><p>Раскачиваем эмоции – аппетитные описания блюд, от которых слюнки потекут.</p><p>Бонус: «Хотите крутой гарнир или эксклюзивный соус к этому?» – больше вкуса, больше кайфа, больше продаж!</p><p>Время приготовления – если задержка, сразу говорим реальное время, гость будет благодарен за честность.</p><p>Повторяем заказ – чтобы не испортить впечатления от возможной ошибки!</p><p>Блюда подаём открытой рукой, как профессионалы.</p><p>Всё приносим синхронно – никто не ждёт, все довольны!</p><p>Первыми – закуски, потом горячее, потом десерты – чистый ритм сервиса!</p><p>«Ну как? Огонь? 🔥» – не просто спрашиваем, а реально чувствуем эмоции гостя!</p><p>Если что-то не так – сразу решаем вопрос.</p><p>Гасим возможные конфликты ещё до их появления.</p><p>Подробнее о чек бэке - в следующем уроке</p><p>Гость попросил счёт? Не стоим, несём моментально!</p><p>Если в точке действует программа лояльности, уточни у гостя, пользуется ли он ей. Перед расчётом проверь условия акции и назови доступные способы оплаты.</p><p>«Наличные или карта, общий или раздельный?» – всё чётко, без лишних вопросов.</p><p>«Спасибо, что заглянули, ждём снова!» – главное, чтобы звучало искренне.</p><p>Финальный аккорд: Улыбка, кивок, возможно даже стильный жест рукой – гость должен уходить с ощущением, что его реально ждали!</p><p>Пересервируем стол за 2-3 минуты – новые гости уже на подходе!</p>","type":"text"},{"id":"course-42959-5","src":"assets/waiter/lesson-3-1.jpg","type":"image","caption":""},{"id":"course-42959-6","src":"assets/waiter/lesson-3-2.jpg","type":"image","caption":""},{"id":"course-42959-7","src":"assets/waiter/lesson-3-3.jpg","type":"image","caption":""},{"id":"course-42959-8","src":"assets/waiter/lesson-3-4.jpg","type":"image","caption":""},{"id":"course-42959-9","src":"assets/waiter/lesson-3-5.jpg","type":"image","caption":""},{"id":"course-42959-10","src":"assets/waiter/lesson-3-6.jpg","type":"image","caption":""}],"images":["assets/waiter/lesson-3-0.jpg","assets/waiter/lesson-3-1.jpg","assets/waiter/lesson-3-2.jpg","assets/waiter/lesson-3-3.jpg","assets/waiter/lesson-3-4.jpg","assets/waiter/lesson-3-5.jpg","assets/waiter/lesson-3-6.jpg"]},{"id":"42958","text":"Для начала: что такое чек-бэк?\n\nCheck Back (чек-бэк) – это твой инструмент, чтобы понять, насколько гость доволен. Вкусно ли ему? Всё ли ок с качеством блюд и напитков? Не нужно ли ему что-то еще (салфетки, соус, пепельница)? А ещё чек-бэк – это твой шанс предотвратить конфликт на ранней стадии!\n\nКак его делать?\nПосле подачи блюд ждём немного времени, чтобы гость успел попробовать.\nПодходим, спрашиваем, как ему еда.\nЕсли гость недоволен – выясняем, в чём дело.\nЕсли проблема из-за качества блюда (неправильно приготовлено, остывшее и т.д.), сообщаем менеджеру.\nМенеджер решает, включать ли блюдо в счёт.\nВиды чек-бэка:\n\nТекущий – быстрый фидбэк\n\nЖдёшь 2-3 минуты после первой вилки еды.\nПодходишь, если гость заказал твою рекомендацию или новинку.\nВажно! Не перебиваем важную беседу, ждём удачного момента.\n\nПоэтапный – шаг за шагом\n\nСпрашиваем мнение, когда убираем тарелку.\nЕсли гость не доел – обязательно выясняем, почему.\nЕсли гость не в восторге от твоей рекомендации – не паримся: «Да, вкусы у всех разные, зато теперь я знаю, что советовать вам в следующий раз!»\n\nКонтрольный – закрепляем успех\n\nСпрашиваем о впечатлениях, когда гость просит счёт.\nОн ещё раз вспоминает, как классно провёл время.\nПроговаривая впечатления, фиксирует их в памяти, а значит, захочет вернуться!\n\nВажный момент!\n\nНе спрашиваем скучные «Всё ли в порядке?» или «Вам что-то не нравится?» – такие вопросы не цепляют. Подходи к гостю с искренним интересом!\n\nКакой чек-бэк использовать? ﻿﻿﻿﻿Решай сам, пробуй разные варианты и найди тот, который работает для тебя лучше всего! 🚀","title":"Урок 4. Чек-бэк и его важность","blocks":[{"id":"course-42958-1","tone":"sky","type":"hero","image":"assets/waiter/lesson-4-0.jpg","label":"Стандарты работы официанта","title":"Урок 4. Чек-бэк и его важность"},{"id":"course-42958-2","text":"Для начала: что такое чек-бэк?","type":"heading","level":2},{"id":"course-42958-3","html":"<p>Check Back (чек-бэк) – это твой инструмент, чтобы понять, насколько гость доволен. Вкусно ли ему? Всё ли ок с качеством блюд и напитков? Не нужно ли ему что-то еще (салфетки, соус, пепельница)? А ещё чек-бэк – это твой шанс предотвратить конфликт на ранней стадии!</p>","type":"text"},{"id":"course-42958-4","src":"assets/waiter/lesson-4-1.jpg","type":"image","caption":""},{"id":"course-42958-5","text":"Как его делать?","type":"heading","level":2},{"id":"course-42958-6","html":"<p>После подачи блюд ждём немного времени, чтобы гость успел попробовать.</p><p>Подходим, спрашиваем, как ему еда.</p><p>Если гость недоволен – выясняем, в чём дело.</p><p>Если проблема из-за качества блюда (неправильно приготовлено, остывшее и т.д.), сообщаем менеджеру.</p><p>Менеджер решает, включать ли блюдо в счёт.</p>","type":"text"},{"id":"course-42958-7","text":"Виды чек-бэка:","type":"heading","level":2},{"id":"course-42958-8","type":"list","items":["Текущий – быстрый фидбэк","Ждёшь 2-3 минуты после первой вилки еды.","Подходишь, если гость заказал твою рекомендацию или новинку."],"ordered":false},{"id":"course-42958-9","text":"Важно! Не перебиваем важную беседу, ждём удачного момента.","tone":"yellow","type":"callout","title":""},{"id":"course-42958-10","html":"<p>Поэтапный – шаг за шагом</p><p>Спрашиваем мнение, когда убираем тарелку.</p><p>Если гость не доел – обязательно выясняем, почему.</p><p>Если гость не в восторге от твоей рекомендации – не паримся: «Да, вкусы у всех разные, зато теперь я знаю, что советовать вам в следующий раз!»</p><p>Контрольный – закрепляем успех</p><p>Спрашиваем о впечатлениях, когда гость просит счёт.</p><p>Он ещё раз вспоминает, как классно провёл время.</p><p>Проговаривая впечатления, фиксирует их в памяти, а значит, захочет вернуться!</p><p>Важный момент!</p><p>Не спрашиваем скучные «Всё ли в порядке?» или «Вам что-то не нравится?» – такие вопросы не цепляют. Подходи к гостю с искренним интересом!</p><p>Какой чек-бэк использовать? Решай сам, пробуй разные варианты и найди тот, который работает для тебя лучше всего! 🚀</p>","type":"text"}],"images":["assets/waiter/lesson-4-0.jpg","assets/waiter/lesson-4-1.jpg"]}],"mergedIntoId":"rvb--waiter-internship"}},"expectedUpdatedAt":"2026-11-17T20:01:40.500292+00:00"},{"record":{"id":"rvb--92988","kind":"test","title":"Тест 1. Правила работы официанта","payload":{"id":"rvb--92988","brand":"rvb","title":"Тест 1. Правила работы официанта","priority":"attestation","passCount":10,"questions":[{"id":"92988-1","text":"Коллега подменит тебя на перерыве. Что ему передать?","type":"single","options":["Только номера столов","Что уже заказано, чего ждут гости и о чём они просили","Только список столов, которые ждут счёт"]},{"id":"92988-2","text":"Во сколько официант РВБ Минск приходит на смену в пятницу?","type":"single","options":["15:00","15:30","16:00"]},{"id":"92988-3","text":"Что делать, если официант опаздывает?","type":"single","options":["Предупредить менеджера","Просто приехать в бар и начать работу","Опоздать и извиниться"]},{"id":"92988-4","text":"Как официант должен подавать блюда и напитки?","type":"single","options":["В любом порядке","Быстро, красиво и в правильной последовательности","Гость сам забирает с бара"]},{"id":"92988-5","text":"Гость перестал поддерживать шутки и отвечает коротко. Как продолжить обслуживание?","type":"single","options":["Перейти на спокойный доброжелательный тон и дать гостю пространство","Продолжить шутить, чтобы его разговорить","Свести общение к подаче и расчёту"]},{"id":"92988-6","text":"Что проверить в своём внешнем виде перед выходом в зал?","type":"single","options":["Только наличие бейджа и фартука","Чистоту и опрятность формы, обуви и соответствие стандарту заведения","Только наличие элементов в стиле бара"]},{"id":"92988-7","text":"Как официант должен действовать, если не знает ответа на вопрос гостя?","type":"single","options":["Сказать то, что первое придет в голову, главное - уверенно","Перевести тему","Уточнить у менеджера и вернуться с ответом"]},{"id":"92988-8","text":"Где уточнить, разрешён ли аксессуар для смены в твоём заведении?","type":"single","options":["По фотографиям команды","По памятке другой точки","По действующему стандарту формы своей точки, при сомнении у менеджера"]},{"id":"92988-9","text":"Перед открытием сломалось крепление аксессуара на форме. Что сделать?","type":"single","options":["Снять аксессуар и согласовать замену, если он обязателен","Оставить его до первого перерыва","Закрепить подручным способом и сразу выйти в зал"]},{"id":"92988-10","text":"Ты заметил, что гости за столом коллеги пытаются привлечь внимание. Как поступить?","type":"single","options":["Дождаться, пока коллега сам увидит гостей","Подойти, уточнить просьбу и передать её ответственному официанту","Сразу забрать стол и вести его до расчёта"]}],"restaurantIds":["minsk"],"trainingBrand":"rvb","timeLimitSeconds":300,"trainingSourceId":"92988","requiredRestaurantIds":["minsk"],"mergedIntoId":"rvb--100075"},"course_id":"rvb--waiter-standards","published":false,"department":null,"updated_at":"2026-11-17T15:01:19.443047+00:00","restaurant_id":"minsk"},"expectedUpdatedAt":"2026-11-17T15:01:19.443047+00:00"},{"record":{"id":"rvb--92993","kind":"test","title":"Тест 4. Чек бэк","payload":{"id":"rvb--92993","brand":"rvb","title":"Тест 4. Чек бэк","priority":"attestation","passCount":10,"questions":[{"id":"92993-1","text":"Зачем делать контрольный чек-бэк?","type":"single","options":["Сообщить об акциях","Закрепить положительное впечатление перед уходом","Уточнить сумму счета","Проверить, понравился ли официант"]},{"id":"92993-2","text":"Что такое Check Back (чек-бэк)?","type":"single","options":["Контроль за работой кухни","Проверка счета гостя","Обратная связь с гостем о качестве еды и сервиса","Оценка работы персонала"]},{"id":"92993-3","text":"Когда официант должен делать текущий чек-бэк?","type":"single","options":["Через 2-3 минуты после первой вилки еды","Перед оплатой счета","После того, как гость полностью съел блюдо","Сразу после подачи блюда"]},{"id":"92993-4","text":"Как лучше всего задавать вопросы гостю во время чек-бэка?","type":"single","options":["Ограничиваться «Всё ок?»","С искренним интересом, без шаблонных фраз","Чётко и официально","Быстро и без эмоций"]},{"id":"92993-5","text":"Что делать, если гость не в восторге от твоей рекомендации?","type":"single","options":["Переубедить его","Посоветовать что-то другое","Принять спокойно и учесть для будущих советов","Спросить, почему он выбрал это блюдо"]},{"id":"92993-6","text":"Какой стиль общения рекомендуется при чек-бэке?","type":"single","options":["Формальный и строгий","Минимальный, без эмоций","Дружеский, искренний, ненавязчивый","Только при необходимости"]},{"id":"92993-7","text":"Что делать, если гость недоволен блюдом?","type":"single","options":["Выяснить причину и сообщить менеджеру","Сказать, что так и должно быть","Извиниться и уйти","Заменить блюдо без уведомления"]},{"id":"92993-8","text":"Гость уже попробовал блюдо. Какая реплика поможет получить конкретную обратную связь?","type":"single","options":["«Как вам прожарка и температура блюда?»","«Всё в порядке?»","«Вы ведь довольны блюдом?»"]},{"id":"92993-9","text":"Когда официант делает поэтапный чек-бэк?","type":"single","options":["После выдачи чека","До подачи блюда","Когда убирает тарелку у гостя","В начале смены"]},{"id":"92993-10","text":"Что делать, если гость не доел блюдо?","type":"single","options":["Немедленно предложить другое блюдо","Спросить причину ненавязчиво","Просто забрать тарелку","Ничего не делать"]}],"restaurantIds":["minsk"],"trainingBrand":"rvb","timeLimitSeconds":300,"trainingSourceId":"92993","requiredRestaurantIds":["minsk"],"mergedIntoId":"rvb--100159"},"course_id":"rvb--waiter-standards","published":false,"department":null,"updated_at":"2026-11-17T15:01:19.443047+00