rainingBrand":"rvb","timeLimitSeconds":210,"trainingSourceId":"92995","requiredRestaurantIds":["minsk"],"mergedIntoId":"rvb--100159"},"course_id":"rvb--waiter-standards","published":false,"department":null,"updated_at":"2026-11-17T15:01:19.443047+00:00","restaurant_id":"minsk"},"expectedUpdatedAt":"2026-11-17T15:01:19.443047+00:00"},{"record":{"id":"rvb--92998","kind":"test","title":"Тест 2. Открытие смены","payload":{"id":"rvb--92998","brand":"rvb","title":"Тест 2. Открытие смены","priority":"attestation","passCount":7,"questions":[{"id":"92998-1","text":"Как проверяется исправность терминала перед сменой?","type":"single","options":["Проверить только наличие ленты","Убедиться, что работает и есть чековая лента","Просто включить","Проверять только при необходимости"]},{"id":"92998-2","text":"Как должен выглядеть порядок в подсобке?","type":"single","options":["Проверяются только шкафчики","Обувь на полке, вещи на вешалке, ничего не валяется","Всё должно быть разложено","Проверка не требуется"]},{"id":"92998-4","text":"Какой инструмент помогает официанту держать всё под контролем при открытии смены?","type":"single","options":["Лист заказов","Чек-лист","Инструкция по безопасности","График смен"]},{"id":"92998-6","text":"Какое должно быть состояние меню при открытии зала?","type":"single","options":["Достаточно просто заменить грязные","Можно использовать даже слегка повреждённые меню","Меню не требует проверки","Чистое, без рваных страниц, протёртое влажной тряпкой"]},{"id":"92998-7","text":"При сервировке ты заметил на приборе следы еды. Что сделать?","type":"single","options":["Отполировать его салфеткой","Отложить до конца подготовки","Отправить прибор на повторную мойку и взять чистый"]},{"id":"92998-8","text":"Какой уровень наполнения соли и перца считается правильным?","type":"single","options":["Только если заканчивается","Полный","Наполовину","На ¾ емкости"]},{"id":"92998-9","text":"Какие элементы зала необходимо проверить перед открытием?","type":"single","options":["Пол, стулья, столы, подоконники","Только столы и салфетки","Только стулья","Только терминалы"]}],"restaurantIds":["minsk"],"trainingBrand":"rvb","timeLimitSeconds":300,"trainingSourceId":"92998","requiredRestaurantIds":["minsk"],"mergedIntoId":"rvb--100153"},"course_id":"rvb--waiter-standards","published":false,"department":null,"updated_at":"2026-11-17T15:01:19.443047+00:00","restaurant_id":"minsk"},"expectedUpdatedAt":"2026-11-17T15:01:19.443047+00:00"}]$patches$::jsonb) loop
  select * into strict current_record from public.academy_content where id=patch->'record'->>'id' for update;
  if current_record.updated_at<>(patch->>'expectedUpdatedAt')::timestamptz then raise exception 'Content changed since review: %',current_record.id;end if;
  if current_record.kind='course' and exists(select 1 from academy_private.course_drafts where course_id=current_record.id) then raise exception 'Unpublished course draft exists: %',current_record.id;end if;
  update public.academy_content set title=patch->'record'->>'title',payload=patch->'record'->'payload',published=(patch->'record'->>'published')::boolean,updated_at=now() where id=current_record.id;
  if patch ? 'keys' then update academy_private.test_keys set keys=patch->'keys' where test_id=current_record.id; if not found then raise exception 'Missing test keys: %',current_record.id;end if;end if;
 end loop;
end $merge$;
do $verify$
begin
 if (select progress from merge_history_before) is distinct from (select coalesce(jsonb_agg(to_jsonb(p) order by p.user_id,p.course_id,p.lesson_id),'[]'::jsonb) from public.academy_progress p where course_id in ('waiter-internship','100075','100153','100159','waiter-standards','92988','92993','92995','92998','rvb--waiter-internship','rvb--100075','rvb--100153','rvb--100159','rvb--waiter-standards','rvb--92988','rvb--92993','rvb--92995','rvb--92998')) then raise exception 'Progress history changed';end if;
 if (select attempts from merge_history_before) is distinct from (select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('private_keys',k.keys) order by a.id),'[]'::jsonb) from public.academy_attempts a left join academy_private.attempt_keys k on k.attempt_id=a.id where test_id in ('waiter-internship','100075','100153','100159','waiter-standards','92988','92993','92995','92998','rvb--waiter-internship','rvb--100075','rvb--100153','rvb--100159','rvb--waiter-standards','rvb--92988','rvb--92993','rvb--92995','rvb--92998')) then raise exception 'Attempt history changed';end if;
 if exists(select 1 from public.academy_content c cross join lateral jsonb_array_elements(c.payload->'questions') q where c.id in ('waiter-internship','100075','100153','100159','waiter-standards','92988','92993','92995','92998','rvb--waiter-internship','rvb--100075','rvb--100153','rvb--100159','rvb--waiter-standards','rvb--92988','rvb--92993','rvb--92995','rvb--92998') and c.kind='test' and c.published and not exists(select 1 from academy_private.test_keys k where k.test_id=c.id and k.keys ? (q->>'id'))) then raise exception 'Missing answer key';end if;
end $verify$;
commit;
select c.id,c.title,jsonb_array_length(c.payload->'lessons') as lessons,(select count(*) from public.academy_content t where t.course_id=c.id and t.kind='test' and t.published) as tests from public.academy_content c where c.id in ('waiter-internship','rvb--waiter-internship');
